    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ select exists(select 1 from public."Autotask_tasks" t where t.id=p_task_id and t.assignee_user_id=auth.uid() and t.status not in ('completed','cancelled')) $$;


--
-- Name: Autotask_complete_task(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public."Autotask_complete_task"(p_actor_user_id uuid, p_task_id uuid, p_completion_data jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_task public."Autotask_tasks"; v_photos integer; v_has_balance boolean;
begin
  select * into v_task from public."Autotask_tasks" where id=p_task_id for update;
  if not found then raise exception 'Task not found'; end if;
  if not exists(select 1 from public.users u where u.id=p_actor_user_id and u.status='active') then raise exception 'Active Aqura user not found'; end if;
  if v_task.assignee_user_id<>p_actor_user_id then raise exception 'Task is not assigned to this user'; end if;
  if v_task.task_number not in (1,2,3) then raise exception 'This task closes automatically'; end if;
  if exists(select 1 from public."Autotask_dependencies" d join public."Autotask_tasks" p on p.id=d.prerequisite_task_id where d.dependent_task_id=v_task.id and p.status<>'completed') then raise exception 'Task dependencies are not complete'; end if;
  select count(*) into v_photos from public."Autotask_evidence" where task_id=p_task_id and evidence_type='photo' and is_finalized;
  if v_task.task_number=1 and v_photos<1 then raise exception 'At least one photo is required'; end if;
  if v_task.task_number=3 then v_has_balance:=coalesce((p_completion_data->>'has_warehouse_balance')::boolean,null); if v_has_balance is null then raise exception 'Warehouse balance choice is required'; end if; if v_has_balance and v_photos<1 then raise exception 'At least one photo is required when balance remains'; end if; end if;
  update public."Autotask_tasks" set status='completed',status_reason_code='user_completed',outcome_code='completed',completion_data=coalesce(p_completion_data,'{}'::jsonb),completed_at=now(),completed_by_user_id=p_actor_user_id,row_version=row_version+1,updated_at=now() where id=p_task_id;
  insert into public."Autotask_activity"(task_id,event_id,activity_type,actor_type,actor_user_id,old_status,new_status,details) values(v_task.id,v_task.event_id,'completion','user',p_actor_user_id,v_task.status,'completed',p_completion_data);
  update public."Autotask_tasks" d set status='open',updated_at=now() where d.event_id=v_task.event_id and d.status='blocked' and not exists(select 1 from public."Autotask_dependencies" x join public."Autotask_tasks" p on p.id=x.prerequisite_task_id where x.dependent_task_id=d.id and p.status<>'completed');
  perform public."Autotask_refresh_source"(v_task.source_table,v_task.source_record_id);
  return jsonb_build_object('success',true,'task_id',p_task_id);
end $$;


--
-- Name: Autotask_decide_advance_approval(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public."Autotask_decide_advance_approval"(p_actor_user_id uuid, p_source_table text, p_source_record_id text, p_decision text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$ declare v_row jsonb; v_updated bigint; begin
  if not exists(select 1 from public.users where id=p_actor_user_id and status='active') then raise exception 'Active Aqura user not found'; end if;
  if p_source_table not in ('receiving_records','pending_receiving_records') or p_decision not in ('approved','rejected') then raise exception 'Invalid approval decision'; end if;
  execute format('select to_jsonb(r) from public.%I r where r.id::text=$1 for update',p_source_table) into v_row using p_source_record_id;
  if coalesce(v_row->>'autotask_advance_approval_status','')<>'sent_for_approval' then raise exception 'Approval already decided or unavailable'; end if;
  if nullif(btrim(coalesce(v_row->>'original_bill_url','')),'') is null then raise exception 'Original bill must be uploaded before this request can be decided'; end if;
  if not (p_actor_user_id=any(array(select jsonb_array_elements_text(coalesce(v_row->'autotask_advance_approval_approver_ids','[]'::jsonb))::uuid))) then raise exception 'User is not an eligible approver'; end if;
  execute format('update public.%I set autotask_advance_approval_status=$1,autotask_advance_approval_decided_by=$2,autotask_advance_approval_decided_at=now(),autotask_advance_approval_notes=$3 where id::text=$4 and autotask_advance_approval_status=$5 and nullif(btrim(coalesce(original_bill_url,'''')::text),'''') is not null',p_source_table) using p_decision,p_actor_user_id,p_notes,p_source_record_id,'sent_for_approval';
  get diagnostics v_updated = row_count;
  if v_updated=0 then raise exception 'Approval was already decided or the original bill is unavailable'; end if;
  perform public."Autotask_refresh_source"(p_source_table,p_source_record_id);
  return jsonb_build_object('success',true,'decision',p_decision);
end $_$;


--
-- Name: Autotask_get_branch_config(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public."Autotask_get_branch_config"(p_branch_id text) RETURNS TABLE(rule_id uuid, rule_code text, task_number integer, title_en text, title_ar text, default_user_ids uuid[], is_enabled boolean, timeline_minutes integer, row_version integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select r.id, r.rule_code, r.task_number, r.title_en, r.title_ar,
         coalesce(c.default_user_ids,'{}'::uuid[]), coalesce(c.is_enabled,true),
         coalesce(c.timeline_minutes_override,r.timeline_minutes), coalesce(c.row_version,0)
  from public."Autotask_rules" r
  left join public."Autotask_branch_config" c on c.rule_id=r.id and c.branch_id=p_branch_id
  order by r.task_number;
$$;


--
-- Name: Autotask_get_branch_performance_dashboard(uuid, integer, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public."Autotask_get_branch_performance_dashboard"(p_requesting_user_id uuid, p_days_back integer DEFAULT 30, p_specific_date date DEFAULT NULL::date) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
with authorized as (
  select exists(select 1 from public.users u where u.id=p_requesting_user_id and u.status='active' and
    (coalesce(u.is_master_admin,false) or exists(select 1 from public.button_permissions bp where bp.user_id=u.id and bp.button_code='BRANCH_PERFORMANCE' and bp.is_enabled=true))) ok
), bounds as (
  select case when p_specific_date is null then now()-(p_days_back||' days')::interval else p_specific_date::timestamp end f,
         case when p_specific_date is null then now() else (p_specific_date+1)::timestamp end t from authorized where ok
), base as (select public.get_branch_performance_dashboard(p_days_back,p_specific_date)::jsonb j),
tasks as (
 select ta.assigned_to_user_id uid,e.current_branch_id::text bid,ta.status,ta.assigned_at created_at,ta.completed_at,
   case when ta.deadline_date is null then null else (ta.deadline_date::text||' '||coalesce(ta.deadline_time::text,'23:59:59'))::timestamptz end due_at,'regular' typ
 from task_assignments ta left join hr_employee_master e on e.user_id=ta.assigned_to_user_id,bounds x where ta.assigned_at>=x.f and ta.assigned_at<x.t
 union all select qta.assigned_to_user_id,e.current_branch_id::text,qta.status,qta.created_at,qta.completed_at,qt.deadline_datetime,'quick'
 from quick_task_assignments qta join quick_tasks qt on qt.id=qta.quick_task_id left join hr_employee_master e on e.user_id=qta.assigned_to_user_id,bounds x where qta.created_at>=x.f and qta.created_at<x.t
 union all select a.assignee_user_id,a.branch_id,a.status,a.created_at,a.completed_at,a.due_at,'auto'
 from "Autotask_tasks" a,bounds x where a.created_at>=x.f and a.created_at<x.t
), totals as (
 select jsonb_build_object('total_tasks',count(*),'completed_tasks',count(*) filter(where status='completed'),
 'pending_tasks',count(*) filter(where status not in('completed','cancelled')),
 'overdue_tasks',count(*) filter(where status not in('completed','cancelled') and due_at<now()),
 'avg_completion_hours',round(coalesce(avg(extract(epoch from(completed_at-created_at))/3600) filter(where status='completed'),0)::numeric,1),
 'auto_tasks',count(*) filter(where typ='auto')) j from tasks
), branch_rows as (
 select b.id branch_id,b.name_en branch_name_en,b.name_ar branch_name_ar,b.location_en branch_location_en,b.location_ar branch_location_ar,
 count(t.*) total_tasks,count(t.*) filter(where status='completed') completed,count(t.*) filter(where status not in('completed','cancelled')) pending,
 count(t.*) filter(where status not in('completed','cancelled') and due_at<now()) overdue,
 count(t.*) filter(where typ='regular') regular_count,count(t.*) filter(where typ='quick') quick_count,count(t.*) filter(where typ='receiving') receiving_count,
 count(t.*) filter(where typ='auto') auto_count,coalesce(cl.cnt,0) checklist_count,coalesce(cl.score,0) avg_checklist_score,
 case when count(t.*)>0 then round(count(t.*) filter(where status='completed')::numeric/count(t.*)*100,1) else 0 end completion_rate
 from branches b left join tasks t on t.bid=b.id::text left join lateral(select count(*) cnt,round(avg(c.total_points::numeric/nullif(c.max_points,0)*100),1) score from hr_checklist_operations c,bounds x where c.branch_id=b.id and c.created_at>=x.f and c.created_at<x.t)cl on true
 group by b.id,b.name_en,b.name_ar,b.location_en,b.location_ar,cl.cnt,cl.score having count(t.*)+coalesce(cl.cnt,0)>0
), employee_rows as (
 select t.uid,e.name_en,e.name_ar,b.name_en branch_name_en,b.name_ar branch_name_ar,count(*) total,count(*) filter(where t.status='completed') completed,
 case when count(*)>0 then round(count(*) filter(where t.status='completed')::numeric/count(*)*100,1) else 0 end rate,
 count(*) filter(where typ='auto') auto_count,coalesce(cl.cnt,0) checklist_count,coalesce(cl.score,0) avg_checklist_score
 from tasks t left join hr_employee_master e on e.user_id=t.uid left join branches b on b.id=e.current_branch_id
 left join lateral(select count(*) cnt,round(avg(c.total_points::numeric/nullif(c.max_points,0)*100),1) score from hr_checklist_operations c,bounds x where c.user_id=t.uid and c.created_at>=x.f and c.created_at<x.t)cl on true
 where t.uid is not null group by t.uid,e.name_en,e.name_ar,b.name_en,b.name_ar,cl.cnt,cl.score
), daily_rows as (
 select d::date as day,count(t.*) filter(where t.created_at::date=d::date) as created,count(t.*) filter(where t.status='completed' and t.completed_at::date=d::date) as completed
 from bounds x,generate_series(x.f::date,least(x.t::date,current_date),'1 day')d left join tasks t on t.created_at::date=d::date or t.completed_at::date=d::date group by d::date
), assembled as (
 select (base.j||jsonb_build_object('totals',(totals.j||jsonb_build_object('total_checklists',base.j#>'{totals,total_checklists}','avg_checklist_score',base.j#>'{totals,avg_checklist_score}')),
 'branch_stats',coalesce((select jsonb_agg(to_jsonb(branch_rows) order by total_tasks desc) from branch_rows),'[]'::jsonb),
 'top_employees',coalesce((select jsonb_agg(to_jsonb(employee_rows) order by completed desc) from employee_rows),'[]'::jsonb),
 'daily_stats',coalesce((select jsonb_agg(to_jsonb(daily_rows) order by day) from daily_rows),'[]'::jsonb),
 'task_type_stats',(base.j->'task_type_stats')||jsonb_build_object('auto',(select count(*) from tasks where typ='auto')))) j from base,totals
) select assembled.j::json from assembled,authorized where authorized.ok
$$;


--
-- Name: Autotask_get_source_tasks(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public."Autotask_get_source_tasks"(p_source_table text, p_source_record_id text) RETURNS TABLE(id uuid, title text, assigned_user_name text, role_type text, task_status text, due_date timestamp with time zone, task_number integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select t.id,t.title_en,u.username,'auto_task',t.status,t.due_at,t.task_number
  from public."Autotask_tasks" t join public.users u on u.id=t.assignee_user_id
  where t.source_table=p_source_table and t.source_record_id=p_source_record_id
  order by t.task_number,u.username;
$$;


--
-- Name: Autotask_ingest_receiving_certificate(text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public."Autotask_ingest_receiving_certificate"(p_source_table text, p_source_record_id text, p_certificate_url text, p_actor_user_id uuid DEFAULT auth.uid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_row jsonb; v_event public."Autotask_events"; v_rule record; v_users uuid[]; v_user uuid; v_task_id uuid; v_created integer:=0; v_branch text; v_branch_name text; v_key text; v_amount numeric; v_approvers uuid[]; v_notifications integer:=0; v_vendor_name text; v_received_by text; v_receiving_date text;
begin
  if p_source_table not in ('receiving_records','pending_receiving_records') then raise exception 'Unsupported source table'; end if;
  execute format('select to_jsonb(r) from public.%I r where r.id::text=$1',p_source_table) into v_row using p_source_record_id;
  if v_row is null then raise exception 'Receiving record not found'; end if;
  select v.vendor_name into v_vendor_name from public.vendors v where v.erp_vendor_id=(v_row->>'vendor_id')::integer;
  select u.username into v_received_by from public.users u where u.id=(v_row->>'user_id')::uuid;
  v_receiving_date:=coalesce(v_row->>'bill_date',v_row->>'created_at');
  v_branch:=v_row->>'branch_id'; v_key:='receiving.clearance_certificate_generated:'||p_source_table||':'||p_source_record_id||':v1';
  select b.name_en into v_branch_name from public.branches b where b.id::text=v_branch;
  insert into public."Autotask_events"(event_type,source_module,source_table,source_record_id,branch_id,idempotency_key,payload,status,created_by)
  values('receiving.clearance_certificate_generated','receiving',p_source_table,p_source_record_id,v_branch,v_key,jsonb_build_object('certificate_url',p_certificate_url),'processing',p_actor_user_id)
  on conflict(idempotency_key) do update set updated_at=now() returning * into v_event;
  if v_event.status='processed' then return jsonb_build_object('success',true,'duplicate',true,'tasks_created',0,'event_id',v_event.id); end if;
  for v_rule in select r.*,c.default_user_ids,c.is_enabled,coalesce(c.timeline_minutes_override,r.timeline_minutes) effective_timeline from public."Autotask_rules" r left join public."Autotask_branch_config" c on c.rule_id=r.id and c.branch_id=v_branch where r.is_active order by r.task_number loop
    if v_rule.task_number=1 then
      select coalesce(array_agg(x::uuid),'{}'::uuid[]) into v_users from jsonb_array_elements_text(coalesce(v_row->'shelf_stocker_user_ids','[]'::jsonb)) x;
    elsif coalesce(v_rule.is_enabled,true) then v_users:=coalesce(v_rule.default_user_ids,'{}'::uuid[]); else v_users:='{}'::uuid[]; end if;
    if coalesce(v_rule.is_enabled,true) and cardinality(v_users)=0 then raise exception 'No assignee configured for Auto Task % (%)',v_rule.task_number,v_rule.title_en; end if;
    foreach v_user in array v_users loop
      insert into public."Autotask_tasks"(event_id,rule_id,rule_code,task_number,task_group_key,assignee_user_id,assignment_source,branch_id,source_module,source_table,source_record_id,source_refs,title_en,title_ar,status,completion_mode,due_at,timeline_minutes,dependency_snapshot,closing_snapshot,evidence_snapshot,notification_title_en,notification_title_ar,notification_body_en,notification_body_ar,idempotency_key)
      values(v_event.id,v_rule.id,v_rule.rule_code,v_rule.task_number,v_key||':task:'||v_rule.task_number,v_user,case when v_rule.task_number=1 then 'source_selected_users' else 'branch_default_users' end,v_branch,'receiving',p_source_table,p_source_record_id,jsonb_build_object('certificate_url',p_certificate_url,'vendor_name',coalesce(v_vendor_name,'Unknown vendor'),'branch_name',coalesce(v_branch_name,'Unknown branch'),'receiving_date',v_receiving_date,'received_by',coalesce(v_received_by,'Unknown user')),v_rule.title_en,v_rule.title_ar,case when v_rule.task_number in (2,3,10) then 'blocked' else 'open' end,v_rule.completion_mode,now()+make_interval(mins=>v_rule.effective_timeline),v_rule.effective_timeline,v_rule.dependency_policy,v_rule.closing_policy,v_rule.evidence_policy,v_rule.notification_title_en,v_rule.notification_title_ar,v_rule.notification_body_en,v_rule.notification_body_ar,v_key||':'||v_rule.task_number||':'||v_user)
      on conflict(idempotency_key) do nothing returning id into v_task_id;
      if v_task_id is not null then v_created:=v_created+1; insert into public."Autotask_activity"(task_id,event_id,activity_type,new_status,details) values(v_task_id,v_event.id,'task_created',case when v_rule.task_number in (2,3,10) then 'blocked' else 'open' end,jsonb_build_object('assignee_user_id',v_user)); end if;
      v_task_id:=null;
    end loop;
  end loop;
  insert into public."Autotask_dependencies"(dependent_task_id,prerequisite_task_id)
  select d.id,p.id from public."Autotask_tasks" d join public."Autotask_tasks" p on p.event_id=d.event_id where d.event_id=v_event.id and ((d.task_number in (2,3) and p.task_number=1) or (d.task_number=10 and p.task_number between 1 and 9)) on conflict do nothing;
  update public."Autotask_tasks" d set status='open' where d.event_id=v_event.id and d.status='blocked' and not exists(select 1 from public."Autotask_dependencies" x join public."Autotask_tasks" p on p.id=x.prerequisite_task_id where x.dependent_task_id=d.id and p.status<>'completed');
  v_amount:=coalesce(nullif(v_row->>'final_bill_amount','')::numeric,nullif(v_row->>'bill_amount','')::numeric,0);
  select coalesce(array_agg(x.user_id),'{}'::uuid[]) into v_approvers from (
    select ap.user_id
    from public.approval_permissions ap
    where ap.is_active=true and ap.can_approve_vendor_payments=true
      and (coalesce(ap.vendor_payment_amount_limit,0)=0 or ap.vendor_payment_amount_limit>=v_amount)
    order by (case when coalesce(ap.vendor_payment_amount_limit,0)=0 then 'infinity'::numeric else ap.vendor_payment_amount_limit end) asc, ap.user_id asc
    limit 1
  ) x;
  if cardinality(v_approvers)=0 then select coalesce(array_agg(u.id),'{}'::uuid[]) into v_approvers from public.users u where coalesce(u.is_master_admin,false)=true and u.status='active'; end if;
  execute format('update public.%I set autotask_advance_approval_status=$1,autotask_advance_approval_approver_ids=$2,autotask_advance_approval_requested_by=$3,autotask_advance_approval_requested_at=now() where id::text=$4',p_source_table) using 'sent_for_approval',v_approvers,p_actor_user_id,p_source_record_id;
  v_notifications:=public."Autotask_publish_event_notifications"(v_event.id,v_approvers);
  update public."Autotask_events" set status='processed',processed_at=now(),updated_at=now() where id=v_event.id;
  perform public."Autotask_refresh_source"(p_source_table,p_source_record_id);
  return jsonb_build_object('success',true,'duplicate',false,'tasks_created',v_created,'notifications_sent',v_notifications,'event_id',v_event.id,'approval_approver_ids',v_approvers);
exception when others then
  if v_event.id is not null then update public."Autotask_events" set status='failed',attempt_count=attempt_count+1,error_message=sqlerrm,updated_at=now() where id=v_event.id; end if;
  raise;
end $_$;


--
-- Name: Autotask_list_my_advance_approvals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public."Autotask_list_my_advance_approvals"(p_user_id uuid) RETURNS TABLE(source_table text, source_record_id text, branch_id text, vendor_name text, bill_number text, amount numeric, requested_at timestamp with time zone, status text, original_bill_url text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select distinct q.* from (
    select 'receiving_records'::text source_table,r.id::text source_record_id,r.branch_id::text branch_id,coalesce(v.vendor_name,'Unknown vendor') vendor_name,r.bill_number::text bill_number,coalesce(r.final_bill_amount,r.bill_amount,0)::numeric amount,r.autotask_advance_approval_requested_at requested_at,r.autotask_advance_approval_status status,r.original_bill_url::text original_bill_url
    from public.receiving_records r left join public.vendors v on v.erp_vendor_id=r.vendor_id where r.autotask_advance_approval_status='sent_for_approval' and p_user_id=any(r.autotask_advance_approval_approver_ids)
    union all
    select 'pending_receiving_records'::text,r.id::text,r.branch_id::text,coalesce(v.vendor_name,'Unknown vendor'),r.bill_number::text,coalesce(r.final_bill_amount,r.bill_amount,0)::numeric,r.autotask_advance_approval_requested_at,r.autotask_advance_approval_status,r.original_bill_url::text
    from public.pending_receiving_records r left join public.vendors v on v.erp_vendor_id=r.vendor_id where r.autotask_advance_approval_status='sent_for_approval' and p_user_id=any(r.autotask_advance_approval_approver_ids)
  ) q where exists(select 1 from public.users u where u.id=p_user_id and u.status='active') order by q.requested_at desc
$$;


--
-- Name: Autotask_list_my_tasks(uuid, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public."Autotask_list_my_tasks"(p_user_id uuid, p_include_completed boolean DEFAULT false, p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, rule_code text, task_number integer, title_en text, title_ar text, status text, is_overdue boolean, due_at timestamp with time zone, source_table text, source_record_id text, branch_id text, source_refs jsonb, completion_data jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT t.id,t.rule_code,t.task_number,t.title_en,t.title_ar,t.status,
         (t.status NOT IN ('completed','cancelled') AND t.due_at<now()),
         t.due_at,t.source_table,t.source_record_id,t.branch_id,t.source_refs,t.completion_data
  FROM public."Autotask_tasks" t
  WHERE t.assignee_user_id=p_user_id
    AND EXISTS(SELECT 1 FROM public.users u WHERE u.id=p_user_id AND u.status='active')
    AND (p_include_completed OR t.status NOT IN ('completed','cancelled'))
  ORDER BY t.created_at DESC
  LIMIT least(greatest(p_limit,1),500)
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: Autotask_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."Autotask_rules" (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    rule_code text NOT NULL,
    task_number integer NOT NULL,
    title_en text NOT NULL,
    title_ar text NOT NULL,
    trigger_event_type text DEFAULT 'receiving.clearance_certificate_generated'::text NOT NULL,
    assignment_mode text NOT NULL,
    completion_mode text NOT NULL,
    timeline_minutes integer NOT NULL,
    dependency_policy jsonb DEFAULT '[]'::jsonb NOT NULL,
    closing_policy jsonb DEFAULT '{}'::jsonb NOT NULL,
    evidence_policy jsonb DEFAULT '{}'::jsonb NOT NULL,
    notification_title_en text NOT NULL,
    notification_title_ar text NOT NULL,
    notification_body_en text NOT NULL,
    notification_body_ar text NOT NULL,
    configuration_version integer DEFAULT 1 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "Autotask_rules_assignment_mode_check" CHECK ((assignment_mode = ANY (ARRAY['source_selected_users'::text, 'branch_default_users'::text]))),
    CONSTRAINT "Autotask_rules_completion_mode_check" CHECK ((completion_mode = ANY (ARRAY['manual'::text, 'automatic'::text, 'hybrid'::text]))),
    CONSTRAINT "Autotask_rules_task_number_check" CHECK (((task_number >= 1) AND (task_number <= 10))),
    CONSTRAINT "Autotask_rules_timeline_minutes_check" CHECK ((timeline_minutes > 0))
);


--
-- Name: Autotask_list_rules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public."Autotask_list_rules"() RETURNS SETOF public."Autotask_rules"
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ select * from public."Autotask_rules" order by task_number $$;


--
-- Name: Autotask_publish_event_notifications(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public."Autotask_publish_event_notifications"(p_event_id uuid, p_approval_user_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_task record; v_notification_id uuid; v_count integer:=0; v_title_en text; v_title_ar text; v_body_en text; v_body_ar text; v_details_en text; v_details_ar text; v_approval_body_en text; v_approval_body_ar text;
begin
  for v_task in select * from public."Autotask_tasks" where event_id=p_event_id loop
    v_title_en:=v_task.notification_title_en;
    v_title_ar:=v_task.notification_title_ar;
    v_body_en:=replace(replace(v_task.notification_body_en,'{{vendor_name}}',coalesce(v_task.source_refs->>'vendor_name','')),'{{receiving_date}}',coalesce(v_task.source_refs->>'receiving_date',''));
    v_body_ar:=replace(replace(v_task.notification_body_ar,'{{vendor_name}}',coalesce(v_task.source_refs->>'vendor_name','')),'{{receiving_date}}',coalesce(v_task.source_refs->>'receiving_date',''));
    v_details_en:=E'\n\nTask: '||coalesce(v_task.title_en,'')||E'\nBranch: '||coalesce(v_task.source_refs->>'branch_name','')||E'\nVendor: '||coalesce(v_task.source_refs->>'vendor_name','')||E'\nBill number: '||coalesce(v_task.source_refs->>'bill_number','')||E'\nReceiving date: '||coalesce(v_task.source_refs->>'receiving_date','')||E'\nReceived by: '||coalesce(v_task.source_refs->>'received_by','');
    v_details_ar:=E'\n\nالمهمة: '||coalesce(v_task.title_ar,'')||E'\nالفرع: '||coalesce(v_task.source_refs->>'branch_name','')||E'\nالمورد: '||coalesce(v_task.source_refs->>'vendor_name','')||E'\nرقم الفاتورة: '||coalesce(v_task.source_refs->>'bill_number','')||E'\nتاريخ الاستلام: '||coalesce(v_task.source_refs->>'receiving_date','')||E'\nتم الاستلام بواسطة: '||coalesce(v_task.source_refs->>'received_by','');
    v_body_en:=v_body_en||v_details_en;
    v_body_ar:=v_body_ar||v_details_ar;
    insert into public.notifications(title,message,title_en,title_ar,message_en,message_ar,type,priority,target_type,target_users,created_by,created_by_name,created_by_role,status,total_recipients,metadata)
    values(v_title_en||' / '||v_title_ar,v_body_en||E'\n---\n'||v_body_ar,v_title_en,v_title_ar,v_body_en,v_body_ar,'task_assigned','medium','specific_users',to_jsonb(array[v_task.assignee_user_id]),'Auto Task System','Auto Task System','System','published',1,jsonb_build_object('autotask_id',v_task.id,'autotask_event_id',p_event_id,'source_table',v_task.source_table,'source_record_id',v_task.source_record_id))
    returning id into v_notification_id;
    v_count:=v_count+1;
  end loop;
  if cardinality(coalesce(p_approval_user_ids,'{}'::uuid[]))>0 then
    v_approval_body_en:='An advance-payment approval decision is required.'||E'\n\nBranch: '||coalesce(v_task.source_refs->>'branch_name','')||E'\nVendor: '||coalesce(v_task.source_refs->>'vendor_name','')||E'\nReceiving date: '||coalesce(v_task.source_refs->>'receiving_date','');
    v_approval_body_ar:='مطلوب قرار بشأن موافقة الدفعة المقدمة.'||E'\n\nالفرع: '||coalesce(v_task.source_refs->>'branch_name','')||E'\nالمورد: '||coalesce(v_task.source_refs->>'vendor_name','')||E'\nتاريخ الاستلام: '||coalesce(v_task.source_refs->>'receiving_date','');
    insert into public.notifications(title,message,title_en,title_ar,message_en,message_ar,type,priority,target_type,target_users,created_by,created_by_name,created_by_role,status,total_recipients,metadata)
    values('Advance Payment Approval / موافقة الدفعة المقدمة',v_approval_body_en||E'\n---\n'||v_approval_body_ar,'Advance Payment Approval','موافقة الدفعة المقدمة',v_approval_body_en,v_approval_body_ar,'approval_request','high','specific_users',to_jsonb(p_approval_user_ids),'Auto Task System','Auto Task System','System','published',cardinality(p_approval_user_ids),jsonb_build_object('autotask_event_id',p_event_id,'approval_type','receiving_advance_payment'))
    returning id into v_notification_id;
    v_count:=v_count+1;
  end if;
  return v_count;
end $$;


--
-- Name: Autotask_refresh_source(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public."Autotask_refresh_source"(p_source_table text, p_source_record_id text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_row jsonb; v_posted_row jsonb; v_task record; v_match boolean; v_closed integer:=0;
BEGIN
  IF p_source_table NOT IN ('receiving_records','pending_receiving_records') THEN RAISE EXCEPTION 'Unsupported source table'; END IF;
  EXECUTE format('select to_jsonb(r) from public.%I r where r.id::text=$1',p_source_table) INTO v_row USING p_source_record_id;
  IF v_row IS NULL THEN RETURN 0; END IF;
  IF p_source_table='pending_receiving_records' AND nullif(v_row->>'posted_receiving_record_id','') IS NOT NULL THEN
    SELECT to_jsonb(r) INTO v_posted_row FROM public.receiving_records r WHERE r.id::text=v_row->>'posted_receiving_record_id';
    IF v_posted_row IS NOT NULL THEN v_row:=v_row||v_posted_row; END IF;
  END IF;
  FOR v_task IN SELECT * FROM public."Autotask_tasks" WHERE source_table=p_source_table AND source_record_id=p_source_record_id AND status IN ('open','blocked') LOOP
    v_match:=false;
    CASE v_task.task_number
      WHEN 4 THEN v_match:=lower(coalesce(v_row#>>'{original_bill_check_result,status}',''))='matched' AND nullif(v_row->>'original_bill_url','') IS NOT NULL;
      WHEN 5 THEN v_match:=nullif(btrim(coalesce(v_row->>'pr_excel_file_url','')),'') IS NOT NULL;
      WHEN 6 THEN v_match:=coalesce((v_row->>'autotask_pr_excel_verified')::boolean,false);
      WHEN 7 THEN v_match:=nullif(btrim(coalesce(v_row->>'erp_purchase_invoice_reference','')),'') IS NOT NULL;
      WHEN 8 THEN v_match:=lower(coalesce(v_row#>>'{erp_check_result,status}',''))='matched';
      WHEN 9 THEN v_match:=coalesce(v_row->>'autotask_advance_approval_status','') IN ('approved','rejected');
      WHEN 10 THEN v_match:=NOT EXISTS(SELECT 1 FROM public."Autotask_dependencies" d JOIN public."Autotask_tasks" p ON p.id=d.prerequisite_task_id WHERE d.dependent_task_id=v_task.id AND p.status<>'completed');
      ELSE v_match:=false;
    END CASE;
    IF v_match AND v_task.task_number BETWEEN 4 AND 10 THEN
      UPDATE public."Autotask_tasks" SET status='completed',status_reason_code='source_condition_met',outcome_code=CASE WHEN v_task.task_number=9 THEN v_row->>'autotask_advance_approval_status' ELSE 'completed' END,completed_at=now(),completed_by_user_id=null,row_version=row_version+1,updated_at=now() WHERE id=v_task.id AND status<>'completed';
      IF found THEN
        v_closed:=v_closed+1;
        INSERT INTO public."Autotask_activity"(task_id,event_id,activity_type,old_status,new_status,reason_code,details) VALUES(v_task.id,v_task.event_id,'auto_completion','open','completed','source_condition_met',jsonb_build_object('task_number',v_task.task_number));
      END IF;
    END IF;
  END LOOP;
  IF v_closed>0 THEN
    PERFORM public."Autotask_refresh_source"(p_source_table,p_source_record_id)
    WHERE EXISTS(SELECT 1 FROM public."Autotask_tasks" WHERE source_table=p_source_table AND source_record_id=p_source_record_id AND task_number=10 AND status<>'completed');
  END IF;
  RETURN v_closed;
END $_$;


--
-- Name: Autotask_register_evidence(uuid, uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public."Autotask_register_evidence"(p_actor_user_id uuid, p_task_id uuid, p_storage_path text, p_mime_type text DEFAULT NULL::text, p_size_bytes bigint DEFAULT NULL::bigint) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ declare v_id uuid; begin
  if not exists(select 1 from public.users u where u.id=p_actor_user_id and u.status='active') then raise exception 'Active Aqura user not found'; end if;
  if not exists(select 1 from public."Autotask_tasks" where id=p_task_id and assignee_user_id=p_actor_user_id and status not in ('completed','cancelled')) then raise exception 'Task is not available'; end if;
  insert into public."Autotask_evidence"(task_id,evidence_type,storage_bucket,storage_path,mime_type,size_bytes,is_required,is_finalized,uploaded_by,finalized_at)
  values(p_task_id,'photo','Autotask_evidence',p_storage_path,p_mime_type,p_size_bytes,true,true,p_actor_user_id,now()) returning id into v_id;
  return v_id;
end $$;


--
-- Name: Autotask_branch_config; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."Autotask_branch_config" (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    branch_id text NOT NULL,
    rule_id uuid NOT NULL,
    default_user_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    is_enabled boolean DEFAULT true NOT NULL,
    timeline_minutes_override integer,
    row_version integer DEFAULT 1 NOT NULL,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "Autotask_branch_config_timeline_minutes_override_check" CHECK (((timeline_minutes_override IS NULL) OR (timeline_minutes_override > 0)))
);


--
-- Name: Autotask_save_branch_config(uuid, text, uuid, uuid[], boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public."Autotask_save_branch_config"(p_requesting_user_id uuid, p_branch_id text, p_rule_id uuid, p_user_ids uuid[], p_is_enabled boolean DEFAULT true, p_expected_version integer DEFAULT NULL::integer) RETURNS public."Autotask_branch_config"
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_result public."Autotask_branch_config"; v_invalid integer;
BEGIN
  IF NOT EXISTS(
    SELECT 1 FROM public.users u
    WHERE u.id=p_requesting_user_id
      AND u.status='active'
      AND (
        coalesce(u.is_master_admin,false)
        OR EXISTS(
          SELECT 1 FROM public.button_permissions bp
          WHERE bp.user_id=u.id
            AND bp.button_code IN ('DEFAULT_POSITIONS','APP_PERMISSIONS')
            AND bp.is_enabled=true
        )
      )
  ) THEN RAISE EXCEPTION 'Not authorized to manage Auto Tasks'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.branches b WHERE b.id::text=p_branch_id AND coalesce(b.is_active,true)) THEN RAISE EXCEPTION 'Active branch not found'; END IF;
  IF EXISTS(SELECT 1 FROM public."Autotask_rules" WHERE id=p_rule_id AND assignment_mode='source_selected_users') THEN RAISE EXCEPTION 'Task 1 uses receiving-selected users'; END IF;
  SELECT count(*) INTO v_invalid FROM unnest(coalesce(p_user_ids,'{}'::uuid[])) x WHERE NOT EXISTS(SELECT 1 FROM public.users u WHERE u.id=x AND u.status='active');
  IF v_invalid>0 THEN RAISE EXCEPTION 'One or more users are invalid'; END IF;
  IF p_expected_version IS NOT NULL AND EXISTS(SELECT 1 FROM public."Autotask_branch_config" WHERE branch_id=p_branch_id AND rule_id=p_rule_id AND row_version<>p_expected_version) THEN RAISE EXCEPTION 'Configuration was changed by another user'; END IF;
  INSERT INTO public."Autotask_branch_config"(branch_id,rule_id,default_user_ids,is_enabled,created_by,updated_by)
  VALUES(p_branch_id,p_rule_id,(SELECT coalesce(array_agg(DISTINCT x),'{}'::uuid[]) FROM unnest(coalesce(p_user_ids,'{}'::uuid[])) x),p_is_enabled,p_requesting_user_id,p_requesting_user_id)
  ON CONFLICT(branch_id,rule_id) DO UPDATE SET default_user_ids=excluded.default_user_ids,is_enabled=excluded.is_enabled,row_version=public."Autotask_branch_config".row_version+1,updated_by=p_requesting_user_id,updated_at=now()
  RETURNING * INTO v_result;
  INSERT INTO public."Autotask_activity"(activity_type,actor_type,actor_user_id,details) VALUES('configuration_changed','admin',p_requesting_user_id,jsonb_build_object('branch_id',p_branch_id,'rule_id',p_rule_id,'user_ids',p_user_ids));
  RETURN v_result;
END $$;


--
-- Name: Autotask_set_pr_excel_verified(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public."Autotask_set_pr_excel_verified"(p_source_table text, p_source_record_id text, p_verified boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$ begin
  if p_source_table not in ('receiving_records','pending_receiving_records') then raise exception 'Unsupported source table'; end if;
  execute format('update public.%I set autotask_pr_excel_verified=$1 where id::text=$2',p_source_table) using p_verified,p_source_record_id;
  if p_source_table='receiving_records' then update public.vendor_payment_schedule set pr_excel_verified=p_verified,pr_excel_verified_by=case when p_verified then auth.uid() else null end,pr_excel_verified_date=case when p_verified then now() else null end where receiving_record_id::text=p_source_record_id; end if;
  perform public."Autotask_refresh_source"(p_source_table,p_source_record_id);
  return jsonb_build_object('success',true,'verified',p_verified);
end $_$;


--
-- Name: _ai_brand_enforce_single_default(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._ai_brand_enforce_single_default() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.is_default = true THEN
    UPDATE public.ai_brand_libraries SET is_default = false WHERE id <> NEW.id AND is_default = true;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: accept_order(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_order(p_order_id uuid, p_user_id uuid) RETURNS TABLE(success boolean, message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_current_status VARCHAR(50);
    v_user_name VARCHAR(255);
BEGIN
    -- Get current status
    SELECT order_status INTO v_current_status
    FROM orders
    WHERE id = p_order_id;
    
    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'Order not found';
        RETURN;
    END IF;
    
    IF v_current_status != 'new' THEN
        RETURN QUERY SELECT FALSE, 'Order can only be accepted from new status';
        RETURN;
    END IF;
    
    -- Get user name
    SELECT username INTO v_user_name
    FROM users
    WHERE id = p_user_id;
    
    -- Update order
    UPDATE orders
    SET order_status = 'accepted',
        accepted_at = NOW(),
        updated_at = NOW(),
        updated_by = p_user_id
    WHERE id = p_order_id;
    
    -- Create audit log
    INSERT INTO order_audit_logs (
        order_id,
        action_type,
        from_status,
        to_status,
        performed_by,
        performed_by_name,
        notes
    ) VALUES (
        p_order_id,
        'status_changed',
        'new',
        'accepted',
        p_user_id,
        v_user_name,
        'Order accepted'
    );
    
    RETURN QUERY SELECT TRUE, 'Order accepted successfully';
END;
$$;


--
-- Name: FUNCTION accept_order(p_order_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.accept_order(p_order_id uuid, p_user_id uuid) IS 'Admin accepts a new order';


--
-- Name: acknowledge_warning(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acknowledge_warning(warning_id_param uuid, acknowledged_by_param uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    UPDATE employee_warnings 
    SET 
        warning_status = 'acknowledged',
        acknowledged_at = CURRENT_TIMESTAMP,
        acknowledged_by = acknowledged_by_param,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = warning_id_param
    AND warning_status = 'active';
    
    RETURN FOUND;
END;
$$;


--
-- Name: add_email_group_member(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_email_group_member(p_group_id uuid, p_email_address text, p_display_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO public.email_group_members (email_group_id, email_address, display_name)
  VALUES (p_group_id, p_email_address, p_display_name)
  ON CONFLICT (email_group_id, email_address) DO UPDATE SET is_active = true, display_name = coalesce(p_display_name, email_group_members.display_name)
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('success', true, 'id', v_id);
END;
$$;


--
-- Name: adjust_product_stock_on_order_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.adjust_product_stock_on_order_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_quantity INTEGER;
BEGIN
    -- Validate that product_id exists
    IF NEW.product_id IS NULL THEN
        RAISE EXCEPTION 'product_id is required';
    END IF;

    -- Get current stock
    SELECT current_stock INTO current_quantity 
    FROM products 
    WHERE id = NEW.product_id;

    -- If product not found, raise error
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Product with id % does not exist', NEW.product_id;
    END IF;

    -- Decrease stock
    UPDATE products 
    SET current_stock = current_stock - NEW.quantity,
        updated_at = NOW()
    WHERE id = NEW.product_id;

    RAISE NOTICE 'Product % stock decreased by %. New stock: %', 
        NEW.product_id, NEW.quantity, (current_quantity - NEW.quantity);

    RETURN NEW;
END;
$$;


--
-- Name: admin_secret_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_secret_status() RETURNS TABLE(secret_name text, is_set boolean, updated_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT names.n AS secret_name,
         (s.id IS NOT NULL) AS is_set,
         s.updated_at
  FROM (VALUES ('supabase_url'), ('anon_key'), ('service_role_key')) AS names(n)
  LEFT JOIN vault.secrets s ON s.name = names.n;
$$;


--
-- Name: admin_upsert_secret(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_upsert_secret(secret_name text, secret_value text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  existing_id uuid;
BEGIN
  SELECT id INTO existing_id FROM vault.secrets WHERE name = secret_name LIMIT 1;
  IF existing_id IS NOT NULL THEN
    PERFORM vault.update_secret(existing_id, secret_value);
  ELSE
    PERFORM vault.create_secret(secret_value, secret_name);
  END IF;
END;
$$;


--
-- Name: approve_action_followup_po(bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_action_followup_po(p_po_id bigint, p_approver_id uuid, p_approver_name text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE action_followup_po SET approval_status = 'approved', approved_by = p_approver_id,
    approved_by_name = p_approver_name, approved_at = now(), updated_at = now()
  WHERE id = p_po_id AND approval_status = 'pending';
  IF NOT FOUND THEN RETURN json_build_object('success', false, 'error', 'Record not found or already processed'); END IF;
  RETURN json_build_object('success', true);
END;
$$;


--
-- Name: approve_customer_account(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_customer_account(p_customer_id uuid, p_status text, p_notes text DEFAULT ''::text, p_approved_by uuid DEFAULT NULL::uuid) RETURNS TABLE(success boolean, message text, customer_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_current_status TEXT;
    v_approved_by UUID;
    v_is_admin BOOLEAN;
    v_is_master_admin BOOLEAN;
BEGIN
    -- p_approved_by is required since we use custom auth (not Supabase Auth)
    IF p_approved_by IS NULL THEN
        RAISE EXCEPTION 'User ID (p_approved_by) is required.';
    END IF;

    -- Check if the user making the request has admin privileges
    SELECT is_admin, is_master_admin 
    INTO v_is_admin, v_is_master_admin
    FROM users 
    WHERE id = p_approved_by;

    -- Verify user exists and has admin privileges
    IF v_is_admin IS NULL THEN
        RAISE EXCEPTION 'User not found.';
    END IF;

    IF NOT (v_is_admin = true OR v_is_master_admin = true) THEN
        RAISE EXCEPTION 'Access denied. Admin privileges required.';
    END IF;

    -- Validate status parameter
    IF p_status NOT IN ('approved', 'rejected') THEN
        RETURN QUERY SELECT FALSE, 'Invalid status. Must be approved or rejected.', NULL::UUID;
        RETURN;
    END IF;

    -- Use the provided user ID
    v_approved_by := p_approved_by;

    -- Get current customer status
    SELECT registration_status INTO v_current_status
    FROM customers
    WHERE id = p_customer_id;

    -- Check if customer exists
    IF v_current_status IS NULL THEN
        RETURN QUERY SELECT FALSE, 'Customer not found.', NULL::UUID;
        RETURN;
    END IF;

    -- Check if customer is already processed
    IF v_current_status != 'pending' THEN
        RETURN QUERY SELECT FALSE, 'Customer has already been processed.', NULL::UUID;
        RETURN;
    END IF;

    -- Update customer status
    UPDATE customers
    SET 
        registration_status = p_status,
        approved_at = CURRENT_TIMESTAMP,
        approved_by = v_approved_by,
        registration_notes = p_notes,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_customer_id;

    -- Return success
    RETURN QUERY SELECT TRUE, 'Customer ' || p_status || ' successfully.', p_customer_id;
END;
$$;


--
-- Name: FUNCTION approve_customer_account(p_customer_id uuid, p_status text, p_notes text, p_approved_by uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.approve_customer_account(p_customer_id uuid, p_status text, p_notes text, p_approved_by uuid) IS 'Approves or rejects a customer account. Requires admin privileges. Creates user account for approved customers.';


--
-- Name: approve_customer_registration(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_customer_registration(p_customer_id uuid, p_approved_by uuid, p_notes text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_access_code text;
    v_customer_name text;
    v_whatsapp_number text;
    result json;
BEGIN
    -- Validate customer exists and is pending
    SELECT c.name, c.whatsapp_number
    INTO v_customer_name, v_whatsapp_number
    FROM public.customers c
    WHERE c.id = p_customer_id AND c.registration_status = 'pending';
    
    IF v_customer_name IS NULL THEN
        RAISE EXCEPTION 'Customer not found or not in pending status';
    END IF;
    
    -- Generate unique access code
    SELECT generate_unique_customer_access_code() INTO v_access_code;
    
    -- Update customer record
    UPDATE public.customers SET
        registration_status = 'approved',
        access_code = v_access_code,
        approved_by = p_approved_by,
        approved_at = now(),
        access_code_generated_at = now(),
        registration_notes = COALESCE(p_notes, registration_notes),
        updated_at = now()
    WHERE id = p_customer_id;
    
    -- Create approval notification
    INSERT INTO public.notifications (
        title,
        message,
        type,
        priority,
        metadata,
        deleted_at
    ) VALUES (
        'Customer Registration Approved',
        'Customer ' || v_customer_name || ' has been approved with access code ' || v_access_code,
        'customer_approved',
        'high',
        json_build_object(
            'customer_id', p_customer_id,
            'access_code', v_access_code,
            'approved_by', p_approved_by,
            'customer_name', v_customer_name,
            'whatsapp_number', v_whatsapp_number
        ),
        NULL
    );
    
    -- Return result
    result := json_build_object(
        'success', true,
        'access_code', v_access_code,
        'customer_name', v_customer_name,
        'whatsapp_number', v_whatsapp_number,
        'message', 'Customer registration approved successfully'
    );
    
    RETURN result;
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'error', SQLERRM
        );
END;
$$;


--
-- Name: approve_internal_expense_request(bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_internal_expense_request(p_id bigint, p_approver_id uuid, p_approver_name text) RETURNS json
