$$;


--
-- Name: aqura_assign_change_request_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aqura_assign_change_request_number() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_serial bigint;
  v_number text;
BEGIN
  NEW.request_date := (NEW.requested_at AT TIME ZONE 'Asia/Riyadh')::date;
  -- One lock per calendar day also protects against ambiguous digit combinations
  -- from different branch IDs when their serials become long.
  PERFORM pg_advisory_xact_lock(734205, (NEW.request_date - DATE '2000-01-01')::integer);
  SELECT coalesce(max(daily_serial), 0) + 1 INTO v_serial
  FROM public.aqura_change_requests
  WHERE request_date = NEW.request_date AND branch_id = NEW.branch_id;
  LOOP
    v_number := to_char(NEW.request_date, 'DDMMYYYY') || NEW.branch_id::text || v_serial::text;
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.aqura_change_requests WHERE request_number = v_number
    );
    v_serial := v_serial + 1;
  END LOOP;
  NEW.daily_serial := v_serial;
  NEW.request_number := v_number;
  RETURN NEW;
END;
$$;


--
-- Name: aqura_complete_safe_box_management(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aqura_complete_safe_box_management(p_operation_id uuid, p_user_id uuid, p_operation_type text, p_counts jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_operation public.aqura_safe_box_operations%ROWTYPE;
  v_record public.denomination_records%ROWTYPE;
  v_counts jsonb;
  v_safe jsonb;
  v_main_before jsonb := '{}'::jsonb;
  v_main_after jsonb := '{}'::jsonb;
  v_safe_before jsonb := '{}'::jsonb;
  v_safe_after jsonb := '{}'::jsonb;
  v_key text;
  v_main_quantity integer;
  v_safe_quantity integer;
  v_change integer;
  v_values jsonb := '{"d500":50000,"d200":20000,"d100":10000,"d50":5000,"d20":2000,"d10":1000,"d5":500,"d2":200,"d1":100,"d05":50,"d025":25,"coins":100,"damage":100}'::jsonb;
  v_main_before_cents bigint := 0;
  v_main_after_cents bigint := 0;
  v_safe_before_cents bigint := 0;
  v_safe_after_cents bigint := 0;
  v_amount_cents bigint := 0;
BEGIN
  SELECT * INTO v_operation FROM public.aqura_safe_box_operations
    WHERE id = p_operation_id FOR UPDATE;
  IF NOT FOUND OR v_operation.user_id <> p_user_id OR v_operation.status <> 'Open' THEN
    RAISE EXCEPTION 'Safe Box management opening is unavailable';
  END IF;
  IF p_operation_type IS DISTINCT FROM 'Withdraw' OR p_counts IS NULL OR
     jsonb_typeof(p_counts) <> 'object' THEN
    RAISE EXCEPTION 'Only Safe Box withdrawal is allowed';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id AND status = 'active' AND
    (coalesce(is_master_admin, false) OR EXISTS (
      SELECT 1 FROM public.aqura_safe_box_permissions
      WHERE user_id = p_user_id AND branch_id = v_operation.branch_id AND permission_type = 'depositor'
    ))) THEN
    RAISE EXCEPTION 'Safe Box Management access denied';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.hr_employee_master
    WHERE user_id = p_user_id AND current_branch_id = v_operation.branch_id) THEN
    RAISE EXCEPTION 'Safe Box branch mismatch';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.aqura_pos_print_actions WHERE flow_id = p_operation_id
    AND action_type = 'safe_box_opening' AND source = 'Aqura Safe Box'
    AND reason = 'Safe Box Management' AND print_status = 'success') THEN
    RAISE EXCEPTION 'Successful Safe Box opening print is required';
  END IF;

  -- This row lock makes the latest balance read, validation, both JSON updates,
  -- and the audit completion one atomic operation.
  SELECT * INTO v_record FROM public.denomination_records
    WHERE branch_id = v_operation.branch_id AND record_type = 'main'
    ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Branch denomination record is missing'; END IF;
  v_counts := coalesce(v_record.counts, '{}'::jsonb);
  v_safe := coalesce(v_counts->'safe_box', '{}'::jsonb);
  IF jsonb_typeof(v_counts) <> 'object' OR jsonb_typeof(v_safe) <> 'object' THEN
    RAISE EXCEPTION 'Invalid saved denomination counts';
  END IF;
  FOR v_key IN SELECT jsonb_object_keys(p_counts) LOOP
    IF NOT v_values ? v_key THEN RAISE EXCEPTION 'Unsupported denomination %', v_key; END IF;
  END LOOP;
  FOR v_key IN SELECT jsonb_object_keys(v_values) LOOP
    v_main_quantity := coalesce((v_counts->>v_key)::integer, 0);
    v_safe_quantity := coalesce((v_safe->>v_key)::integer, 0);
    v_change := coalesce((p_counts->>v_key)::integer, 0);
    IF v_main_quantity < 0 OR v_safe_quantity < 0 OR v_change < 0 OR
       v_change > v_safe_quantity OR v_change > 100000 OR
       v_main_quantity::bigint + v_change > 2147483647 THEN
      RAISE EXCEPTION 'Insufficient or invalid Safe Box quantity for %: available %', v_key, v_safe_quantity;
    END IF;
    v_main_before := jsonb_set(v_main_before, ARRAY[v_key], to_jsonb(v_main_quantity), true);
    v_main_after := jsonb_set(v_main_after, ARRAY[v_key], to_jsonb(v_main_quantity + v_change), true);
    v_safe_before := jsonb_set(v_safe_before, ARRAY[v_key], to_jsonb(v_safe_quantity), true);
    v_safe_after := jsonb_set(v_safe_after, ARRAY[v_key], to_jsonb(v_safe_quantity - v_change), true);
    v_counts := jsonb_set(v_counts, ARRAY[v_key], to_jsonb(v_main_quantity + v_change), true);
    v_main_before_cents := v_main_before_cents + v_main_quantity * (v_values->>v_key)::integer;
    v_main_after_cents := v_main_after_cents + (v_main_quantity + v_change) * (v_values->>v_key)::integer;
    v_safe_before_cents := v_safe_before_cents + v_safe_quantity * (v_values->>v_key)::integer;
    v_safe_after_cents := v_safe_after_cents + (v_safe_quantity - v_change) * (v_values->>v_key)::integer;
    v_amount_cents := v_amount_cents + v_change * (v_values->>v_key)::integer;
  END LOOP;
  IF v_amount_cents <= 0 THEN RAISE EXCEPTION 'Enter at least one withdrawal quantity'; END IF;
  IF v_main_before_cents + v_safe_before_cents <> v_main_after_cents + v_safe_after_cents THEN
    RAISE EXCEPTION 'Combined physical cash must remain unchanged';
  END IF;

  UPDATE public.denomination_records SET
    counts = jsonb_set(jsonb_set(v_counts, '{safe_box}', v_safe_after, true),
      '{safe_box_balance}', to_jsonb(v_safe_after_cents / 100.0), true),
    grand_total = v_main_after_cents / 100.0,
    difference = CASE WHEN difference IS NULL THEN NULL ELSE difference +
      (v_main_after_cents + v_safe_after_cents - v_main_before_cents - v_safe_before_cents) / 100.0 END
  WHERE id = v_record.id;

  UPDATE public.aqura_safe_box_operations SET
    denomination_record_id = v_record.id,
    operation_type = 'Withdraw', denomination_counts = p_counts,
    total_amount = v_amount_cents / 100.0,
    balance_before = v_safe_before_cents / 100.0,
    balance_after = v_safe_after_cents / 100.0,
    main_counts_before = v_main_before, main_counts_after = v_main_after,
    safe_box_counts_before = v_safe_before, safe_box_counts_after = v_safe_after,
    opening_print_status = 'success',
    status = 'Completed', completed_at = now()
  WHERE id = p_operation_id;

  RETURN jsonb_build_object('status', 'Completed', 'total_amount', v_amount_cents / 100.0,
    'main_total', v_main_after_cents / 100.0, 'safe_box_balance', v_safe_after_cents / 100.0);
END;
$$;


--
-- Name: aqura_finalize_safe_box_request(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aqura_finalize_safe_box_request(p_request_id uuid, p_user_id uuid, p_withdrawal_counts jsonb, p_printer_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_request public.aqura_change_requests%ROWTYPE;
  v_record public.denomination_records%ROWTYPE;
  v_safe jsonb;
  v_key text;
  v_old integer;
  v_in integer;
  v_out integer;
  v_values jsonb := '{"d500":50000,"d200":20000,"d100":10000,"d50":5000,"d20":2000,"d10":1000,"d5":500,"d2":200,"d1":100,"d05":50,"d025":25}'::jsonb;
  v_total_cents bigint := 0;
  v_old_balance numeric := 0;
  v_new_balance numeric := 0;
BEGIN
  SELECT * INTO v_request FROM public.aqura_change_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND OR v_request.requested_to_user_id <> p_user_id OR v_request.status <> 'Safe Box Printed' THEN
    RAISE EXCEPTION 'Request is not ready for Safe Box withdrawal';
  END IF;
  IF p_withdrawal_counts IS NULL OR jsonb_typeof(p_withdrawal_counts) <> 'object' THEN
    RAISE EXCEPTION 'Invalid withdrawal denominations';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.aqura_pos_print_actions
    WHERE request_id = p_request_id AND action_type = 'safe_box_opening' AND print_status = 'success') THEN
    RAISE EXCEPTION 'Successful Safe Box opening print is required';
  END IF;
  SELECT * INTO v_record FROM public.denomination_records
    WHERE branch_id = v_request.branch_id AND record_type = 'main'
    ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Branch denomination record is missing'; END IF;
  v_safe := coalesce(v_record.counts->'safe_box', '{}'::jsonb);
  FOR v_key IN SELECT jsonb_object_keys(p_withdrawal_counts) LOOP
    IF NOT v_values ? v_key THEN RAISE EXCEPTION 'Unsupported denomination %', v_key; END IF;
  END LOOP;
  FOR v_key IN SELECT jsonb_object_keys(v_values) LOOP
    v_old := coalesce((v_safe->>v_key)::integer, 0);
    v_in := coalesce((v_request.received_counts->>v_key)::integer, 0);
    v_out := coalesce((p_withdrawal_counts->>v_key)::integer, 0);
    IF v_old < 0 OR v_in < 0 OR v_out < 0 OR v_out > v_old THEN
      RAISE EXCEPTION 'Insufficient Safe Box balance for %: available %', v_key, v_old;
    END IF;
    v_old_balance := v_old_balance + v_old * (v_values->>v_key)::integer / 100.0;
    v_new_balance := v_new_balance + (v_old + v_in - v_out) * (v_values->>v_key)::integer / 100.0;
    v_total_cents := v_total_cents + v_out * (v_values->>v_key)::integer;
    v_safe := jsonb_set(v_safe, ARRAY[v_key], to_jsonb(v_old + v_in - v_out), true);
  END LOOP;
  -- Finance includes its Coins and Damage rows as one SAR each. Preserve them unchanged.
  v_old_balance := v_old_balance + coalesce((v_safe->>'coins')::numeric, 0) + coalesce((v_safe->>'damage')::numeric, 0);
  v_new_balance := v_new_balance + coalesce((v_safe->>'coins')::numeric, 0) + coalesce((v_safe->>'damage')::numeric, 0);
  IF v_total_cents <= 0 THEN RAISE EXCEPTION 'Enter at least one withdrawal denomination'; END IF;
  IF v_total_cents <> round(v_request.total_amount * 100)::bigint THEN
    RAISE EXCEPTION 'Cash taken must exactly match the requested amount of % SAR', v_request.total_amount;
  END IF;
  UPDATE public.denomination_records SET
    counts = jsonb_set(jsonb_set(coalesce(counts, '{}'::jsonb), '{safe_box}', v_safe, true),
      '{safe_box_balance}', to_jsonb(v_new_balance), true),
    difference = CASE WHEN difference IS NULL THEN NULL ELSE difference + v_new_balance - v_old_balance END
    WHERE id = v_record.id;
  UPDATE public.aqura_change_requests SET
    withdrawal_counts = p_withdrawal_counts, withdrawal_total = v_total_cents / 100.0,
    safe_box_printer_name = p_printer_name, processed_at = now(),
    status = 'Ready for Cashier Confirmation'
    WHERE id = p_request_id;
  RETURN jsonb_build_object('status', 'Ready for Cashier Confirmation', 'withdrawal_total', v_total_cents / 100.0,
    'safe_box_balance', v_new_balance);
END;
$$;


--
-- Name: assign_email_thread(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_email_thread(p_message_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_msg record;
  v_thread_id uuid;
  v_normalised_subject text;
BEGIN
  SELECT * INTO v_msg FROM public.email_messages WHERE id = p_message_id;
  IF v_msg IS NULL THEN RETURN NULL; END IF;

  -- Normalize subject (strip Re: Fwd: FW: etc)
  v_normalised_subject := regexp_replace(
    coalesce(v_msg.subject, ''),
    '^(Re|Fwd|FW|Fw|RE):\s*', '', 'gi'
  );
  v_normalised_subject := trim(regexp_replace(v_normalised_subject, '^(Re|Fwd|FW|Fw|RE):\s*', '', 'gi'));

  -- Try to find existing thread by In-Reply-To header
  IF v_msg.in_reply_to_header IS NOT NULL AND v_msg.in_reply_to_header != '' THEN
    SELECT thread_id INTO v_thread_id
    FROM public.email_messages
    WHERE email_account_id = v_msg.email_account_id
      AND message_id_header = v_msg.in_reply_to_header
      AND thread_id IS NOT NULL
    LIMIT 1;
    IF v_thread_id IS NOT NULL THEN
      UPDATE public.email_messages SET thread_id = v_thread_id WHERE id = p_message_id;
      -- Update thread
      UPDATE public.email_threads SET
        latest_message_at = greatest(latest_message_at, coalesce(v_msg.received_at, v_msg.sent_at, v_msg.created_at)),
        message_count = message_count + 1,
        unread_count = unread_count + (CASE WHEN v_msg.is_read = false THEN 1 ELSE 0 END)
      WHERE id = v_thread_id;
      RETURN v_thread_id;
    END IF;
  END IF;

  -- Try to find by normalized subject + same account (within 7 days)
  IF v_normalised_subject != '' THEN
    SELECT id INTO v_thread_id
    FROM public.email_threads
    WHERE email_account_id = v_msg.email_account_id
      AND normalised_subject = v_normalised_subject
      AND latest_message_at > (coalesce(v_msg.received_at, v_msg.created_at) - interval '7 days')
    ORDER BY latest_message_at DESC
    LIMIT 1;
    IF v_thread_id IS NOT NULL THEN
      UPDATE public.email_messages SET thread_id = v_thread_id WHERE id = p_message_id;
      UPDATE public.email_threads SET
        latest_message_at = greatest(latest_message_at, coalesce(v_msg.received_at, v_msg.sent_at, v_msg.created_at)),
        message_count = message_count + 1,
        unread_count = unread_count + (CASE WHEN v_msg.is_read = false THEN 1 ELSE 0 END)
      WHERE id = v_thread_id;
      RETURN v_thread_id;
    END IF;
  END IF;

  -- Create new thread
  INSERT INTO public.email_threads (email_account_id, normalised_subject, latest_message_at, message_count, unread_count)
  VALUES (v_msg.email_account_id, v_normalised_subject, coalesce(v_msg.received_at, v_msg.sent_at, v_msg.created_at), 1,
    CASE WHEN v_msg.is_read = false THEN 1 ELSE 0 END)
  RETURNING id INTO v_thread_id;

  UPDATE public.email_messages SET thread_id = v_thread_id WHERE id = p_message_id;
  RETURN v_thread_id;
END;
$$;


--
-- Name: assign_in_process_products(text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_in_process_products(p_old_employee_id text, p_new_employee_id text, p_barcodes text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_count INTEGER;
    v_now   TEXT := to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
BEGIN
    UPDATE erp_synced_products
    SET
        in_process = (
            SELECT COALESCE(jsonb_agg(elem), '[]'::JSONB)
            FROM jsonb_array_elements(in_process) AS elem
            WHERE elem->>'employee_id' != p_old_employee_id
        ),
        managed_by = COALESCE(managed_by, '[]'::JSONB) || (
            SELECT COALESCE(
                jsonb_agg(
                    (elem - 'moved_at') ||
                    jsonb_build_object(
                        'employee_id', p_new_employee_id,
                        'claimed_at',  v_now
                    )
                ),
                '[]'::JSONB
            )
            FROM jsonb_array_elements(in_process) AS elem
            WHERE elem->>'employee_id' = p_old_employee_id
        )
    WHERE barcode = ANY(p_barcodes)
      AND in_process IS NOT NULL;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


--
-- Name: assign_in_process_products(text, text, text[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_in_process_products(p_old_employee_id text, p_new_employee_id text, p_barcodes text[], p_branch_id integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer;
  v_now text := to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
BEGIN
  UPDATE public.erp_synced_products
  SET
    in_process = (
      SELECT COALESCE(jsonb_agg(elem), '[]'::jsonb)
      FROM jsonb_array_elements(in_process) AS elem
      WHERE NOT (
        elem->>'employee_id' = p_old_employee_id
        AND elem->>'branch_id' = p_branch_id::text
      )
    ),
    managed_by = COALESCE(managed_by, '[]'::jsonb) || (
      SELECT COALESCE(
        jsonb_agg(
          (elem - 'moved_at') || jsonb_build_object(
            'employee_id', p_new_employee_id,
            'claimed_at', v_now
          )
        ),
        '[]'::jsonb
      )
      FROM jsonb_array_elements(in_process) AS elem
      WHERE elem->>'employee_id' = p_old_employee_id
        AND elem->>'branch_id' = p_branch_id::text
    )
  WHERE barcode = ANY(p_barcodes)
    AND EXISTS (
      SELECT 1
      FROM jsonb_array_elements(in_process) AS elem
      WHERE elem->>'employee_id' = p_old_employee_id
        AND elem->>'branch_id' = p_branch_id::text
    );

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: assign_order_delivery(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_order_delivery(p_order_id uuid, p_delivery_person_id uuid, p_assigned_by uuid) RETURNS TABLE(success boolean, message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_delivery_name VARCHAR(255);
    v_assigned_by_name VARCHAR(255);
BEGIN
    -- Get delivery person name
    SELECT username INTO v_delivery_name
    FROM users
    WHERE id = p_delivery_person_id;
    
    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'Delivery person not found';
        RETURN;
    END IF;
    
    -- Get assigner name
    SELECT username INTO v_assigned_by_name
    FROM users
    WHERE id = p_assigned_by;
    
    -- Update order
    UPDATE orders
    SET delivery_person_id = p_delivery_person_id,
        delivery_assigned_at = NOW(),
        order_status = CASE 
            WHEN order_status = 'ready' THEN 'out_for_delivery'
            ELSE order_status
        END,
        updated_at = NOW(),
        updated_by = p_assigned_by
    WHERE id = p_order_id;
    
    -- Create audit log
    INSERT INTO order_audit_logs (
        order_id,
        action_type,
        assigned_user_id,
        assigned_user_name,
        assignment_type,
        performed_by,
        performed_by_name,
        notes
    ) VALUES (
        p_order_id,
        'assigned_delivery',
        p_delivery_person_id,
        v_delivery_name,
        'delivery',
        p_assigned_by,
        v_assigned_by_name,
        'Delivery person assigned to order'
    );
    
    RETURN QUERY SELECT TRUE, 'Delivery person assigned successfully';
END;
$$;


--
-- Name: FUNCTION assign_order_delivery(p_order_id uuid, p_delivery_person_id uuid, p_assigned_by uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.assign_order_delivery(p_order_id uuid, p_delivery_person_id uuid, p_assigned_by uuid) IS 'Assigns delivery person to order';


