-- Name: create_action_followup_other(bigint, text, text, text, text, text, time without time zone, integer, integer, integer, integer, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_action_followup_other(p_branch_id bigint, p_branch_name text, p_branch_location text, p_description text, p_schedule_type text, p_recurrence_type text DEFAULT NULL::text, p_recurrence_time time without time zone DEFAULT NULL::time without time zone, p_recurrence_day_of_week integer DEFAULT NULL::integer, p_recurrence_day_of_month integer DEFAULT NULL::integer, p_recurrence_month integer DEFAULT NULL::integer, p_recurrence_start_month integer DEFAULT NULL::integer, p_related_user_id uuid DEFAULT NULL::uuid, p_related_user_name text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result json;
  v_user_id uuid;
BEGIN
  v_user_id := COALESCE(p_user_id, auth.uid());

  INSERT INTO action_followup_other (
    branch_id, branch_name, branch_location, description, schedule_type,
    recurrence_type, recurrence_time, recurrence_day_of_week,
    recurrence_day_of_month, recurrence_month, recurrence_start_month,
    related_user_id, related_user_name, created_by
  ) VALUES (
    p_branch_id, p_branch_name, p_branch_location, p_description, p_schedule_type,
    p_recurrence_type, p_recurrence_time, p_recurrence_day_of_week,
    p_recurrence_day_of_month, p_recurrence_month, p_recurrence_start_month,
    p_related_user_id, p_related_user_name, v_user_id
  )
  RETURNING json_build_object(
    'id', id, 'branch_id', branch_id, 'branch_name', branch_name,
    'description', description, 'schedule_type', schedule_type,
    'recurrence_type', recurrence_type, 'recurrence_time', recurrence_time,
    'related_user_name', related_user_name, 'created_at', created_at
  ) INTO v_result;

  RETURN json_build_object('success', true, 'data', v_result);
END;
$$;


--
-- Name: create_action_followup_po(bigint, text, text, text, text, integer, numeric, date, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_action_followup_po(p_branch_id bigint, p_branch_name text, p_vendor_erp_id text, p_vendor_name text, p_payment_mode text, p_credit_period integer, p_po_amount numeric, p_expected_delivery_date date, p_salesman_name text DEFAULT NULL::text, p_salesman_contact text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_branch_location text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result json;
  v_user_id uuid;
BEGIN
  v_user_id := COALESCE(p_user_id, auth.uid());

  IF p_payment_mode = 'credit' AND (p_credit_period IS NULL OR p_credit_period <= 0) THEN
    RETURN json_build_object('success', false, 'error', 'Credit period is required for credit payment mode');
  END IF;

  INSERT INTO action_followup_po (
    branch_id, branch_name, branch_location, vendor_erp_id, vendor_name,
    payment_mode, credit_period, po_amount,
    expected_delivery_date, salesman_name, salesman_contact, created_by
  ) VALUES (
    p_branch_id, p_branch_name, p_branch_location, p_vendor_erp_id, p_vendor_name,
    p_payment_mode, p_credit_period, p_po_amount,
    p_expected_delivery_date, p_salesman_name, p_salesman_contact, v_user_id
  )
  RETURNING json_build_object(
    'id', id, 'branch_id', branch_id, 'branch_name', branch_name,
    'branch_location', branch_location,
    'vendor_erp_id', vendor_erp_id, 'vendor_name', vendor_name,
    'payment_mode', payment_mode, 'credit_period', credit_period,
    'po_amount', po_amount, 'expected_delivery_date', expected_delivery_date,
    'salesman_name', salesman_name, 'salesman_contact', salesman_contact,
    'created_by', created_by, 'created_at', created_at
  ) INTO v_result;

  RETURN json_build_object('success', true, 'data', v_result);
END;
$$;


