-- Name: create_email_account(text, text, uuid, text, text, text, integer, text, text, text, integer, text, text, integer, integer, boolean, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_email_account(p_account_name text, p_email_address text, p_provider_preset_id uuid DEFAULT NULL::uuid, p_from_name text DEFAULT NULL::text, p_reply_to_address text DEFAULT NULL::text, p_smtp_host text DEFAULT NULL::text, p_smtp_port integer DEFAULT 587, p_smtp_encryption text DEFAULT 'tls'::text, p_smtp_username text DEFAULT NULL::text, p_imap_host text DEFAULT NULL::text, p_imap_port integer DEFAULT 993, p_imap_encryption text DEFAULT 'ssl'::text, p_imap_username text DEFAULT NULL::text, p_hourly_send_limit integer DEFAULT 100, p_daily_send_limit integer DEFAULT 2000, p_sync_enabled boolean DEFAULT false, p_send_enabled boolean DEFAULT true, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO public.email_accounts (
    account_name, email_address, provider_preset_id, from_name, reply_to_address,
    smtp_host, smtp_port, smtp_encryption, smtp_username,
    imap_host, imap_port, imap_encryption, imap_username,
    hourly_send_limit, daily_send_limit, sync_enabled, send_enabled, notes,
    created_by
  ) VALUES (
    p_account_name, p_email_address, p_provider_preset_id, p_from_name, p_reply_to_address,
    p_smtp_host, p_smtp_port, p_smtp_encryption, p_smtp_username,
    p_imap_host, p_imap_port, p_imap_encryption, p_imap_username,
    p_hourly_send_limit, p_daily_send_limit, p_sync_enabled, p_send_enabled, p_notes,
    auth.uid()
  ) RETURNING id INTO v_id;

  -- Create secrets row
  INSERT INTO public.email_account_secrets (email_account_id)
  VALUES (v_id);

  -- Log
  INSERT INTO public.email_logs (event_type, email_account_id, user_id, safe_message)
  VALUES ('account_created', v_id, auth.uid(), 'Email account created: ' || p_account_name);

  RETURN jsonb_build_object('success', true, 'id', v_id);
END;
$$;


