CREATE FUNCTION public.create_my_task(p_user_id uuid, p_title text, p_description text DEFAULT NULL::text, p_timeline_type text DEFAULT 'no_timeline'::text, p_due_date date DEFAULT NULL::date, p_due_time time without time zone DEFAULT NULL::time without time zone, p_recurrence_type text DEFAULT NULL::text, p_recurrence_day_of_week integer DEFAULT NULL::integer, p_recurrence_day_of_month integer DEFAULT NULL::integer, p_recurrence_month integer DEFAULT NULL::integer, p_recurrence_start_month integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_result json;
BEGIN
  INSERT INTO action_followup_my_tasks (user_id, title, description, timeline_type, due_date, due_time,
    recurrence_type, recurrence_day_of_week, recurrence_day_of_month, recurrence_month, recurrence_start_month)
  VALUES (p_user_id, p_title, p_description, p_timeline_type, p_due_date, p_due_time,
    p_recurrence_type, p_recurrence_day_of_week, p_recurrence_day_of_month, p_recurrence_month, p_recurrence_start_month)
