--
-- Name: create_task(text, text, text, text, text, text, date, time without time zone, boolean, boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_task(title_param text, description_param text, created_by_param text, created_by_name_param text, created_by_role_param text, priority_param text, due_date_param date, due_time_param time without time zone, require_task_finished_param boolean, require_photo_upload_param boolean, require_erp_reference_param boolean, can_escalate_param boolean, can_reassign_param boolean) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    task_id UUID;
    calculated_due_datetime TIMESTAMPTZ;
BEGIN
    -- Calculate due_datetime if due_date is provided
    IF due_date_param IS NOT NULL THEN
        calculated_due_datetime := due_date_param + COALESCE(due_time_param, '23:59:59'::TIME);
    END IF;
    
    -- Insert only columns that exist in the tasks table
    INSERT INTO tasks (
        title,
        description,
        created_by,
        created_by_name,
        created_by_role,
        priority,
        due_date,
        due_time,
        due_datetime,
        require_task_finished,
        require_photo_upload,
        require_erp_reference,
        can_escalate,
        can_reassign,
        status
    ) VALUES (
        title_param,
        description_param,
        created_by_param,
        created_by_name_param,
        created_by_role_param,
        priority_param,
        due_date_param,
        due_time_param,
        calculated_due_datetime,
        require_task_finished_param,
        require_photo_upload_param,
        require_erp_reference_param,
        can_escalate_param,
        can_reassign_param,
        'active'
    ) RETURNING id INTO task_id;
    
    RETURN task_id;
END;
$$;


--
-- Name: create_user(character varying, character varying, boolean, boolean, character varying, bigint, uuid, uuid, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_user(p_username character varying, p_password character varying, p_is_master_admin boolean DEFAULT false, p_is_admin boolean DEFAULT false, p_user_type character varying DEFAULT 'branch_specific'::character varying, p_branch_id bigint DEFAULT NULL::bigint, p_employee_id uuid DEFAULT NULL::uuid, p_position_id uuid DEFAULT NULL::uuid, p_quick_access_code character varying DEFAULT NULL::character varying, p_requesting_user_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_quick_access_code varchar(6);
  v_quick_access_hash text;
  v_password_hash text;
  v_salt text;
  v_quick_access_salt text;
  v_requester_is_master boolean := false;
  v_requester_can_create boolean := false;
BEGIN
  SELECT COALESCE(u.is_master_admin, false)
    INTO v_requester_is_master
    FROM public.users u
   WHERE u.id = p_requesting_user_id AND u.status = 'active';

  SELECT EXISTS (
    SELECT 1 FROM public.button_permissions bp
     WHERE bp.user_id = p_requesting_user_id
       AND bp.button_code = 'CREATE_USER'
       AND bp.is_enabled = true
  ) INTO v_requester_can_create;

  IF NOT COALESCE(v_requester_is_master, false)
     AND NOT COALESCE(v_requester_can_create, false) THEN
    RETURN json_build_object('success', false, 'message', 'Access denied: Create User permission required');
  END IF;

  IF (COALESCE(p_is_admin, false) OR COALESCE(p_is_master_admin, false))
     AND NOT COALESCE(v_requester_is_master, false) THEN
    RETURN json_build_object('success', false, 'message', 'Access denied: only a Master Admin can create Admin or Master Admin users');
  END IF;

  v_salt := extensions.gen_salt('bf');
  v_quick_access_salt := extensions.gen_salt('bf');

  IF p_quick_access_code IS NULL THEN
    v_quick_access_code := lpad(floor(random() * 1000000)::text, 6, '0');
    WHILE EXISTS (
      SELECT 1 FROM public.users
       WHERE extensions.crypt(v_quick_access_code, quick_access_code) = quick_access_code
    ) LOOP
      v_quick_access_code := lpad(floor(random() * 1000000)::text, 6, '0');
    END LOOP;
  ELSE
    v_quick_access_code := p_quick_access_code;
    IF EXISTS (
      SELECT 1 FROM public.users
       WHERE extensions.crypt(v_quick_access_code, quick_access_code) = quick_access_code
    ) THEN
      RETURN json_build_object('success', false, 'message', 'Quick access code already exists');
    END IF;
  END IF;

  IF EXISTS (SELECT 1 FROM public.users WHERE username = p_username) THEN
    RETURN json_build_object('success', false, 'message', 'Username already exists');
  END IF;

  v_password_hash := extensions.crypt(p_password, v_salt);
  v_quick_access_hash := extensions.crypt(v_quick_access_code, v_quick_access_salt);

  INSERT INTO public.users (
    username, password_hash, salt, quick_access_code, quick_access_salt,
    is_master_admin, is_admin, user_type, branch_id, employee_id, position_id,
    status, is_first_login, failed_login_attempts, created_at, updated_at
  ) VALUES (
    p_username, v_password_hash, v_salt, v_quick_access_hash, v_quick_access_salt,
    COALESCE(p_is_master_admin, false), COALESCE(p_is_admin, false),
    p_user_type::user_type_enum, p_branch_id, p_employee_id, p_position_id,
    'active', true, 0, now(), now()
  ) RETURNING id INTO v_user_id;

  RETURN json_build_object(
    'success', true,
    'user_id', v_user_id,
    'quick_access_code', v_quick_access_code,
    'message', 'User created successfully'
  );
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('success', false, 'message', SQLERRM);
END;
$$;


