--
-- Name: delete_sync_app_installation(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_sync_app_installation(p_session_token text, p_device_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_is_master_admin boolean;
    v_deleted_device_id text;
BEGIN
    SELECT u.is_master_admin
    INTO v_is_master_admin
    FROM public.user_sessions s
    JOIN public.users u ON u.id = s.user_id
    WHERE s.session_token = p_session_token
      AND s.is_active = true
      AND u.status = 'active'
    ORDER BY s.created_at DESC
    LIMIT 1;

    IF NOT COALESCE(v_is_master_admin, false) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Access denied: Master Admin permission required');
    END IF;

    IF NULLIF(BTRIM(p_device_id), '') IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Device ID is required');
    END IF;

    DELETE FROM public.sync_app_heartbeats
    WHERE device_id = p_device_id
    RETURNING device_id INTO v_deleted_device_id;

    IF v_deleted_device_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Installation record not found');
    END IF;

    RETURN jsonb_build_object('success', true, 'device_id', v_deleted_device_id);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: denomination_audit_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.denomination_audit_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO denomination_audit_log (
            record_id, branch_id, user_id, action, record_type, box_number,
            old_counts, new_counts,
            old_erp_balance, new_erp_balance,
            old_grand_total, new_grand_total,
            old_difference, new_difference
        ) VALUES (
            NEW.id, NEW.branch_id, NEW.user_id, 'INSERT', NEW.record_type, NEW.box_number,
            NULL, NEW.counts,
            NULL, NEW.erp_balance,
            NULL, NEW.grand_total,
            NULL, NEW.difference
        );
        RETURN NEW;
    ELSIF TG_OP = 'UPDATE' THEN
        INSERT INTO denomination_audit_log (
            record_id, branch_id, user_id, action, record_type, box_number,
            old_counts, new_counts,
            old_erp_balance, new_erp_balance,
            old_grand_total, new_grand_total,
            old_difference, new_difference
        ) VALUES (
            NEW.id, NEW.branch_id, NEW.user_id, 'UPDATE', NEW.record_type, NEW.box_number,
            OLD.counts, NEW.counts,
            OLD.erp_balance, NEW.erp_balance,
            OLD.grand_total, NEW.grand_total,
            OLD.difference, NEW.difference
        );
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO denomination_audit_log (
            record_id, branch_id, user_id, action, record_type, box_number,
            old_counts, new_counts,
            old_erp_balance, new_erp_balance,
            old_grand_total, new_grand_total,
            old_difference, new_difference
        ) VALUES (
            OLD.id, OLD.branch_id, OLD.user_id, 'DELETE', OLD.record_type, OLD.box_number,
            OLD.counts, NULL,
            OLD.erp_balance, NULL,
            OLD.grand_total, NULL,
            OLD.difference, NULL
        );
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$$;


