--
-- Name: email_restore(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_restore(p_message_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_account_id uuid;
  v_inbox_folder_id uuid;
BEGIN
  SELECT email_account_id INTO v_account_id FROM public.email_messages WHERE id = p_message_ids[1];
  
  IF v_account_id IS NOT NULL THEN
    SELECT id INTO v_inbox_folder_id FROM public.email_folders
    WHERE email_account_id = v_account_id AND folder_type = 'inbox' LIMIT 1;
    
    UPDATE public.email_messages 
    SET is_deleted = false, folder_id = COALESCE(v_inbox_folder_id, folder_id)
    WHERE id = ANY(p_message_ids);
  END IF;
  
  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: email_soft_delete(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_soft_delete(p_message_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_account_id uuid;
  v_trash_folder_id uuid;
BEGIN
  -- Get account from first message
  SELECT email_account_id INTO v_account_id FROM public.email_messages WHERE id = p_message_ids[1];
  
  IF v_account_id IS NOT NULL THEN
    -- Get or create trash folder
    SELECT id INTO v_trash_folder_id FROM public.email_folders
    WHERE email_account_id = v_account_id AND folder_type = 'trash' LIMIT 1;
    
    IF v_trash_folder_id IS NULL THEN
      INSERT INTO public.email_folders (email_account_id, remote_folder_name, display_name, folder_type)
      VALUES (v_account_id, 'Trash', 'Trash', 'trash')
      RETURNING id INTO v_trash_folder_id;
    END IF;
    
    -- Move to trash folder and mark as deleted
    UPDATE public.email_messages 
    SET is_deleted = true, folder_id = v_trash_folder_id
    WHERE id = ANY(p_message_ids);
  END IF;
  
  RETURN jsonb_build_object('success', true);
END;
$$;


