--
-- Name: get_active_offers(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_offers(p_branch_id bigint DEFAULT NULL::bigint) RETURNS TABLE(id uuid, offer_name character varying, offer_name_en character varying, offer_name_ar character varying, branch_id bigint, branch_name_en text, branch_name_ar text, location_en text, location_ar text, file_url text, start_date date, end_date date, start_time time without time zone, end_time time without time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT o.id,
         o.offer_name,
         o.offer_name_en,
         o.offer_name_ar,
         o.branch_id,
         b.name_en::text,
         b.name_ar::text,
         b.location_en::text,
         b.location_ar::text,
         o.file_url,
         o.start_date,
         o.end_date,
         o.start_time,
         o.end_time
  FROM view_offer o
  JOIN branches b ON b.id = o.branch_id
  WHERE (p_branch_id IS NULL OR o.branch_id = p_branch_id)
    AND (o.start_date + COALESCE(o.start_time, '00:00:00'::time))
          <= (timezone('Asia/Riyadh', now()))::timestamp
    AND (o.end_date + COALESCE(o.end_time, '23:59:00'::time))
          >= (timezone('Asia/Riyadh', now()))::timestamp
    AND COALESCE(o.file_url, '') <> ''
    AND o.status = 'published'
  ORDER BY b.location_en, o.created_at DESC;
$$;


--
-- Name: get_active_offers_for_customer(uuid, integer, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_offers_for_customer(p_customer_id uuid, p_branch_id integer DEFAULT NULL::integer, p_service_type character varying DEFAULT 'both'::character varying) RETURNS TABLE(offer_id integer, offer_type character varying, name_ar character varying, name_en character varying, discount_type character varying, discount_value numeric, start_date timestamp with time zone, end_date timestamp with time zone, service_type character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        o.id,
        o.type,
        o.name_ar,
        o.name_en,
        o.discount_type,
        o.discount_value,
        o.start_date,
        o.end_date,
        o.service_type
    FROM offers o
    WHERE o.is_active = true
        AND NOW() BETWEEN o.start_date AND o.end_date
        AND (o.branch_id IS NULL OR o.branch_id = p_branch_id)
        AND (o.service_type = 'both' OR o.service_type = p_service_type)
        AND (
            -- General offers (not customer-specific)
            o.type != 'customer'
            OR
            -- Customer-specific offers assigned to this customer
            EXISTS (
                SELECT 1 FROM customer_offers co
                WHERE co.offer_id = o.id
                    AND co.customer_id = p_customer_id
                    AND co.is_used = false
            )
        )
        AND (
            -- Check max total uses not exceeded
            o.max_total_uses IS NULL OR o.current_total_uses < o.max_total_uses
        )
    ORDER BY o.priority DESC, o.created_at DESC;
END;
$$;


