--
-- Name: get_ai_flyer_generator_init_data(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ai_flyer_generator_init_data() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result json;
BEGIN
  SELECT json_build_object(
    'success', true,
    'offers', COALESCE((
      SELECT json_agg(json_build_object(
        'id', o.id, 'template_name', o.template_name, 'start_date', o.start_date,
        'end_date', o.end_date,
        'offer_names', CASE WHEN n.id IS NULL THEN NULL
          ELSE json_build_object('name_en', n.name_en, 'name_ar', n.name_ar) END
      ) ORDER BY o.created_at DESC)
      FROM flyer_offers o LEFT JOIN offer_names n ON n.id = o.offer_name_id
      WHERE o.is_active = true
    ), '[]'::json),
    'contexts', COALESCE((
      SELECT json_agg(json_build_object('id', c.id, 'name', c.name, 'description', c.description) ORDER BY c.sort_order)
      FROM flyer_offer_contexts c
      WHERE c.is_active = true
    ), '[]'::json),
    'branches', COALESCE((
      SELECT json_agg(json_build_object(
        'id', b.id, 'name_en', b.name_en, 'name_ar', b.name_ar,
        'location_en', b.location_en, 'location_ar', b.location_ar
      ) ORDER BY b.name_en)
      FROM branches b
      WHERE b.is_active = true
    ), '[]'::json)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: get_ai_flyer_library(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ai_flyer_library(p_page integer DEFAULT 0, p_page_size integer DEFAULT 20) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result json;
BEGIN
  SELECT json_build_object(
    'success', true,
    'total_count', COALESCE(MAX(page_row.total_count), 0),
    'has_more', (p_page + 1) * p_page_size < COALESCE(MAX(page_row.total_count), 0),
    'data', COALESCE(json_agg(
      json_build_object(
        'id', page_row.id, 'title', page_row.title, 'start_date', page_row.start_date,
        'end_date', page_row.end_date, 'page_count', page_row.page_count,
        'product_count', page_row.product_count, 'page_paths', page_row.page_paths,
        'created_at', page_row.created_at, 'context', page_row.context,
        'publications', page_row.publications
      ) ORDER BY page_row.created_at DESC
    ), '[]'::json)
  ) INTO v_result
  FROM (
    SELECT
      r.id, r.title, r.start_date, r.end_date, r.page_count, r.product_count,
      r.page_paths, r.created_at,
      r.snapshot->'context' AS context,
      COALESCE(pubs.publications, '[]'::json) AS publications,
      count(*) OVER() AS total_count
    FROM ai_generated_flyers r
    LEFT JOIN LATERAL (
      SELECT json_agg(json_build_object(
        'branch_id', p.branch_id,
        'page_paths', p.page_paths,
        'offer', json_build_object(
          'status', vo.status, 'start_date', vo.start_date, 'start_time', vo.start_time,
          'end_date', vo.end_date, 'end_time', vo.end_time
        )
      )) AS publications
      FROM ai_flyer_publications p JOIN view_offer vo ON vo.id = p.view_offer_id
      WHERE p.flyer_id = r.id
    ) pubs ON true
    WHERE
      -- Never published -- still relevant/available to publish.
      NOT EXISTS (SELECT 1 FROM ai_flyer_publications p WHERE p.flyer_id = r.id)
      -- Or has at least one publication that hasn't expired (still live, or manually
      -- unpublished/paused rather than run its course) -- still relevant.
      OR EXISTS (
        SELECT 1 FROM ai_flyer_publications p
        JOIN view_offer vo ON vo.id = p.view_offer_id
        WHERE p.flyer_id = r.id AND vo.status <> 'expired'
      )
    ORDER BY r.created_at DESC
    LIMIT p_page_size OFFSET p_page * p_page_size
  ) page_row;

  RETURN v_result;
END;
$$;


--
-- Name: get_all_branches_delivery_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_all_branches_delivery_settings() RETURNS TABLE(branch_id bigint, branch_name_en text, branch_name_ar text, minimum_order_amount numeric, delivery_service_enabled boolean, delivery_is_24_hours boolean, delivery_start_time time without time zone, delivery_end_time time without time zone, pickup_service_enabled boolean, pickup_is_24_hours boolean, pickup_start_time time without time zone, pickup_end_time time without time zone, delivery_message_ar text, delivery_message_en text, location_url text, latitude double precision, longitude double precision)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        b.id,
        b.name_en::text,
        b.name_ar::text,
        COALESCE(b.minimum_order_amount, 15.00)::numeric,
        COALESCE(b.delivery_service_enabled, true)::boolean,
        COALESCE(b.delivery_is_24_hours, true)::boolean,
        b.delivery_start_time,
        b.delivery_end_time,
        COALESCE(b.pickup_service_enabled, true)::boolean,
        COALESCE(b.pickup_is_24_hours, true)::boolean,
        b.pickup_start_time,
        b.pickup_end_time,
        COALESCE(b.delivery_message_ar, 'التوصيل متاح على مدار الساعة')::text,
        COALESCE(b.delivery_message_en, 'Delivery available 24/7')::text,
        b.location_url,
        b.latitude,
        b.longitude
    FROM public.branches b
    ORDER BY b.name_en;
END;
$$;


--
-- Name: get_all_breaks(date, date, integer, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_all_breaks(p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_branch_id integer DEFAULT NULL::integer, p_status character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.start_time DESC), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT
      br.id,
      br.employee_id,
      br.employee_name_en,
      br.employee_name_ar,
      br.branch_id,
      b.name_en as branch_name_en,
      b.name_ar as branch_name_ar,
      r.name_en as reason_en,
      r.name_ar as reason_ar,
      br.reason_note,
      br.start_time,
      br.end_time,
      br.duration_seconds,
      br.status
    FROM break_register br
    JOIN break_reasons r ON r.id = br.reason_id
    LEFT JOIN branches b ON b.id = br.branch_id
    WHERE (p_date_from IS NULL OR br.start_time::DATE >= p_date_from)
      AND (p_date_to IS NULL OR br.start_time::DATE <= p_date_to)
      AND (p_branch_id IS NULL OR br.branch_id = p_branch_id)
      AND (p_status IS NULL OR br.status = p_status)
    ORDER BY br.start_time DESC
    LIMIT 500
  ) t;

  RETURN jsonb_build_object('breaks', v_result);
END;
$$;


