--
-- Name: get_email_dashboard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_email_dashboard() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN jsonb_build_object(
    'sent_today', (SELECT count(*) FROM public.email_messages WHERE direction = 'outbound' AND status = 'sent' AND sent_at >= date_trunc('day', now())),
    'received_today', (SELECT count(*) FROM public.email_messages WHERE direction = 'inbound' AND received_at >= date_trunc('day', now())),
    'failed_today', (SELECT count(*) FROM public.email_queue WHERE status IN ('temporary_failed', 'permanent_failed') AND created_at >= date_trunc('day', now())),
    'pending_queue', (SELECT count(*) FROM public.email_queue WHERE status IN ('waiting', 'processing')),
    'scheduled', (SELECT count(*) FROM public.email_messages WHERE scheduled_at IS NOT NULL AND status = 'queued' AND scheduled_at > now()),
    'unread', (SELECT count(*) FROM public.email_messages WHERE is_read = false AND is_deleted = false AND direction = 'inbound'),
    'active_campaigns', (SELECT count(*) FROM public.email_campaigns WHERE status IN ('running', 'queued', 'scheduled')),
    'accounts', (SELECT coalesce(jsonb_agg(jsonb_build_object(
      'id', ea.id, 'name', ea.account_name, 'email', ea.email_address,
      'smtp_status', ea.last_smtp_test_status, 'imap_status', ea.last_imap_test_status,
      'last_sync', ea.last_sync_at, 'send_enabled', ea.send_enabled, 'sync_enabled', ea.sync_enabled
    )), '[]'::jsonb) FROM public.email_accounts ea WHERE ea.is_active = true),
    'recent_activity', (
      SELECT coalesce(jsonb_agg(row_to_json(l)::jsonb), '[]'::jsonb)
      FROM (SELECT event_type, safe_message, created_at FROM public.email_logs ORDER BY created_at DESC LIMIT 10) l
    )
  );
END;
$$;


--
-- Name: get_email_folders(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_email_folders(p_account_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN (
    SELECT coalesce(jsonb_agg(row_to_json(f)::jsonb), '[]'::jsonb)
    FROM (
      SELECT ef.*,
        CASE 
          WHEN ef.folder_type = 'trash' THEN (SELECT count(*) FROM public.email_messages em WHERE em.folder_id = ef.id AND em.is_deleted = true)
          ELSE (SELECT count(*) FROM public.email_messages em WHERE em.folder_id = ef.id AND em.is_read = false AND em.is_deleted = false)
        END as unread_count
      FROM public.email_folders ef
      WHERE ef.email_account_id = p_account_id AND ef.is_active = true
      ORDER BY CASE ef.folder_type
        WHEN 'inbox' THEN 1 WHEN 'sent' THEN 2 WHEN 'drafts' THEN 3
        WHEN 'starred' THEN 4 WHEN 'archive' THEN 5 WHEN 'spam' THEN 6
        WHEN 'trash' THEN 7 ELSE 8 END
    ) f
  );
END;
$$;


--
-- Name: get_email_groups(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_email_groups() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN (
    SELECT coalesce(jsonb_agg(row_to_json(g)::jsonb ORDER BY g.group_name), '[]'::jsonb)
    FROM (
      SELECT eg.*,
        (SELECT count(*) FROM public.email_group_members egm WHERE egm.email_group_id = eg.id AND egm.is_active = true) as member_count
      FROM public.email_groups eg
      WHERE eg.is_active = true
    ) g
  );
END;
$$;


--
-- Name: get_email_logs_report(text, uuid, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_email_logs_report(p_event_type text DEFAULT NULL::text, p_account_id uuid DEFAULT NULL::uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_page integer DEFAULT 1, p_page_size integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_offset integer;
BEGIN
  v_offset := (p_page - 1) * p_page_size;
  RETURN jsonb_build_object(
    'total', (
      SELECT count(*) FROM public.email_logs
      WHERE (p_event_type IS NULL OR event_type = p_event_type)
        AND (p_account_id IS NULL OR email_account_id = p_account_id)
        AND (p_date_from IS NULL OR created_at >= p_date_from)
        AND (p_date_to IS NULL OR created_at <= p_date_to)
    ),
    'logs', (
      SELECT coalesce(jsonb_agg(row_to_json(l)::jsonb), '[]'::jsonb)
      FROM (
        SELECT el.*, ea.account_name
        FROM public.email_logs el
        LEFT JOIN public.email_accounts ea ON ea.id = el.email_account_id
        WHERE (p_event_type IS NULL OR el.event_type = p_event_type)
          AND (p_account_id IS NULL OR el.email_account_id = p_account_id)
          AND (p_date_from IS NULL OR el.created_at >= p_date_from)
          AND (p_date_to IS NULL OR el.created_at <= p_date_to)
        ORDER BY el.created_at DESC
        LIMIT p_page_size OFFSET v_offset
      ) l
    )
  );
END;
$$;


--
-- Name: get_email_message(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_email_message(p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Mark as read
  UPDATE public.email_messages SET is_read = true WHERE id = p_message_id AND is_read = false;

  RETURN (
    SELECT jsonb_build_object(
      'message', row_to_json(em)::jsonb,
      'recipients', (SELECT coalesce(jsonb_agg(row_to_json(r)::jsonb), '[]'::jsonb) FROM public.email_message_recipients r WHERE r.email_message_id = em.id),
      'attachments', (SELECT coalesce(jsonb_agg(row_to_json(a)::jsonb), '[]'::jsonb) FROM public.email_attachments a WHERE a.email_message_id = em.id)
    )
    FROM public.email_messages em
    WHERE em.id = p_message_id
  );
END;
$$;


--
-- Name: get_email_messages(uuid, uuid, text, boolean, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_email_messages(p_account_id uuid, p_folder_id uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text, p_is_read boolean DEFAULT NULL::boolean, p_is_starred boolean DEFAULT NULL::boolean, p_page integer DEFAULT 1, p_page_size integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_offset integer;
  v_total integer;
BEGIN
  v_offset := (p_page - 1) * p_page_size;

  SELECT count(*) INTO v_total
  FROM public.email_messages em
  WHERE em.email_account_id = p_account_id
    AND em.is_deleted = false
    AND (p_folder_id IS NULL OR em.folder_id = p_folder_id)
    AND (p_is_read IS NULL OR em.is_read = p_is_read)
    AND (p_is_starred IS NULL OR em.is_starred = p_is_starred)
    AND (p_search IS NULL OR em.subject ILIKE '%' || p_search || '%' OR em.from_address ILIKE '%' || p_search || '%' OR em.body_preview ILIKE '%' || p_search || '%');

  RETURN jsonb_build_object(
    'total', v_total,
    'page', p_page,
    'page_size', p_page_size,
    'messages', (
      SELECT coalesce(jsonb_agg(row_to_json(m)::jsonb), '[]'::jsonb)
      FROM (
        SELECT em.id, em.folder_id, em.thread_id, em.direction, em.status, em.subject,
               em.from_name, em.from_address, em.body_preview, em.sent_at, em.received_at,
               em.is_read, em.is_starred, em.is_flagged, em.is_draft, em.priority,
               em.has_attachments, em.source_type,
               (SELECT count(*) FROM public.email_message_recipients r WHERE r.email_message_id = em.id) as recipient_count
        FROM public.email_messages em
        WHERE em.email_account_id = p_account_id
          AND em.is_deleted = false
          AND (p_folder_id IS NULL OR em.folder_id = p_folder_id)
          AND (p_is_read IS NULL OR em.is_read = p_is_read)
          AND (p_is_starred IS NULL OR em.is_starred = p_is_starred)
          AND (p_search IS NULL OR em.subject ILIKE '%' || p_search || '%' OR em.from_address ILIKE '%' || p_search || '%' OR em.body_preview ILIKE '%' || p_search || '%')
        ORDER BY coalesce(em.received_at, em.sent_at, em.created_at) DESC
        LIMIT p_page_size OFFSET v_offset
      ) m
    )
  );
END;
$$;


--
-- Name: get_email_messages_threaded(uuid, uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_email_messages_threaded(p_account_id uuid, p_folder_id uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_offset integer;
  v_total integer;
  v_is_trash boolean := false;
BEGIN
  v_offset := (p_page - 1) * p_page_size;

  -- Check if viewing trash folder
  IF p_folder_id IS NOT NULL THEN
    SELECT (folder_type = 'trash') INTO v_is_trash FROM public.email_folders WHERE id = p_folder_id;
  END IF;

  SELECT count(DISTINCT coalesce(em.thread_id, em.id)) INTO v_total
  FROM public.email_messages em
  WHERE em.email_account_id = p_account_id
    AND (CASE WHEN v_is_trash THEN em.is_deleted = true ELSE em.is_deleted = false END)
    AND (p_folder_id IS NULL OR em.folder_id = p_folder_id)
    AND (p_search IS NULL OR em.subject ILIKE '%' || p_search || '%' OR em.from_address ILIKE '%' || p_search || '%');

  RETURN jsonb_build_object(
    'total', v_total,
    'page', p_page,
    'page_size', p_page_size,
    'is_trash', v_is_trash,
    'threads', (
      SELECT coalesce(jsonb_agg(t ORDER BY t.latest_at DESC), '[]'::jsonb)
      FROM (
        SELECT DISTINCT ON (coalesce(em.thread_id, em.id))
          coalesce(em.thread_id, em.id) as thread_id,
          em.id as latest_message_id,
          em.subject,
          em.from_name,
          em.from_address,
          em.body_preview,
          em.is_read,
          em.is_starred,
          em.has_attachments,
          em.direction,
          coalesce(em.received_at, em.sent_at, em.created_at) as latest_at,
          (SELECT count(*) FROM public.email_messages m2 
           WHERE m2.thread_id = em.thread_id AND m2.thread_id IS NOT NULL) as message_count,
          (SELECT count(*) FROM public.email_messages m3 
           WHERE m3.thread_id = em.thread_id AND m3.thread_id IS NOT NULL AND m3.is_read = false) as unread_in_thread
        FROM public.email_messages em
        WHERE em.email_account_id = p_account_id
          AND (CASE WHEN v_is_trash THEN em.is_deleted = true ELSE em.is_deleted = false END)
          AND (p_folder_id IS NULL OR em.folder_id = p_folder_id)
          AND (p_search IS NULL OR em.subject ILIKE '%' || p_search || '%' OR em.from_address ILIKE '%' || p_search || '%')
        ORDER BY coalesce(em.thread_id, em.id), coalesce(em.received_at, em.sent_at, em.created_at) DESC
      ) t
      LIMIT p_page_size OFFSET v_offset
    )
  );
END;
$$;


--
-- Name: get_email_provider_presets(); Type: FUNCTION; Schema: public; Owner: -
