--
-- Name: get_email_thread_messages(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_email_thread_messages(p_thread_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Mark all as read
  UPDATE public.email_messages SET is_read = true WHERE thread_id = p_thread_id AND is_read = false;

  RETURN (
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'message', row_to_json(em)::jsonb,
      'recipients', (SELECT coalesce(jsonb_agg(row_to_json(r)::jsonb), '[]'::jsonb) FROM public.email_message_recipients r WHERE r.email_message_id = em.id)
    ) ORDER BY coalesce(em.received_at, em.sent_at, em.created_at) ASC), '[]'::jsonb)
    FROM public.email_messages em
    WHERE em.thread_id = p_thread_id AND em.is_deleted = false
  );
END;
$$;


--
-- Name: get_employee_basic_hours(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_employee_basic_hours(p_employee_id bigint) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    emp_basic_hours DECIMAL(4,2);
BEGIN
    SELECT basic_hours INTO emp_basic_hours
    FROM employee_basic_hours 
    WHERE employee_id = p_employee_id;
    
    -- Return employee-specific hours or default to 8.0
    RETURN COALESCE(emp_basic_hours, 8.0);
END;
$$;


--
-- Name: get_employee_basic_hours(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_employee_basic_hours(p_employee_id uuid, p_date date DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    basic_hours DECIMAL(4,2);
BEGIN
    SELECT ebh.basic_hours_per_day
    INTO basic_hours
    FROM employee_basic_hours ebh
    WHERE ebh.employee_id = p_employee_id
      AND ebh.is_active = true
      AND p_date >= ebh.effective_from
      AND (ebh.effective_to IS NULL OR p_date <= ebh.effective_to)
    ORDER BY ebh.effective_from DESC
    LIMIT 1;
    
    RETURN COALESCE(basic_hours, 8.0); -- Default to 8 hours if not configured
END;
$$;


--
-- Name: get_employee_claim_products(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_employee_claim_products(p_employee_id text, p_locale text DEFAULT 'en'::text) RETURNS TABLE(barcode text, product_name text, branch_id integer, claimed_at text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT
        ep.barcode,
        CASE WHEN p_locale = 'ar'
            THEN COALESCE(ep.product_name_ar, ep.product_name_en, '')
            ELSE COALESCE(ep.product_name_en, ep.product_name_ar, '')
        END AS product_name,
        (e->>'branch_id')::INTEGER AS branch_id,
        e->>'claimed_at'           AS claimed_at
    FROM erp_synced_products ep,
         jsonb_array_elements(ep.managed_by) AS e
    WHERE ep.managed_by IS NOT NULL
      AND ep.managed_by != '[]'::JSONB
      AND e->>'employee_id' = p_employee_id
    ORDER BY (e->>'claimed_at') DESC;
$$;


--
-- Name: get_employee_document_category_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_employee_document_category_stats(emp_id uuid) RETURNS TABLE(category public.document_category_enum, count bigint, total_days integer, latest_date timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        d.document_category::document_category_enum,
        COUNT(*)::BIGINT,
        SUM(COALESCE(d.category_days, 0))::INTEGER,
        MAX(d.upload_date)
    FROM hr_employee_documents d
    WHERE d.employee_id = emp_id 
      AND d.is_active = true 
      AND d.document_category IS NOT NULL
    GROUP BY d.document_category;
END;
$$;


--
-- Name: get_employee_dup_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_employee_dup_counts() RETURNS TABLE(employee_id text, dup_count bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT
        sub.emp_id AS employee_id,
        SUM(sub.cnt - 1)::BIGINT AS dup_count
    FROM (
        SELECT
            elem->>'employee_id' AS emp_id,
            COUNT(*) AS cnt
        FROM erp_synced_products,
             jsonb_array_elements(managed_by) AS elem
        WHERE managed_by IS NOT NULL
          AND managed_by != '[]'::JSONB
        GROUP BY barcode, elem->>'employee_id', (elem->>'branch_id')::INTEGER
        HAVING COUNT(*) > 1
    ) sub
    WHERE sub.emp_id IS NOT NULL
    GROUP BY sub.emp_id
    ORDER BY dup_count DESC;
$$;


--
-- Name: get_employee_master_list(text, integer, integer, text, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_employee_master_list(p_search text DEFAULT ''::text, p_page integer DEFAULT 1, p_limit integer DEFAULT 50, p_status_filter text DEFAULT NULL::text, p_branch_filter integer DEFAULT NULL::integer, p_position_filter uuid DEFAULT NULL::uuid) RETURNS TABLE(id text, name_en character varying, name_ar character varying, current_branch_id integer, branch_name_en character varying, branch_name_ar character varying, branch_location_en character varying, branch_location_ar character varying, current_position_id uuid, position_title_en character varying, position_title_ar character varying, employment_status text, whatsapp_number text, email text, total_count bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    e.id,
    e.name_en,
    e.name_ar,
    e.current_branch_id,
    b.name_en AS branch_name_en,
    b.name_ar AS branch_name_ar,
    b.location_en AS branch_location_en,
    b.location_ar AS branch_location_ar,
    e.current_position_id,
    pos.position_title_en,
    pos.position_title_ar,
    s.employment_status,
    e.whatsapp_number,
    e.email,
    COUNT(*) OVER() AS total_count
  FROM hr_employee_master e
  LEFT JOIN branches b ON b.id = e.current_branch_id
  LEFT JOIN hr_positions pos ON pos.id = e.current_position_id
  LEFT JOIN hr_employee_current_status s ON s.employee_id = e.id
  WHERE
    (COALESCE(p_search, '') = ''
      OR e.name_en ILIKE '%' || p_search || '%'
      OR e.name_ar ILIKE '%' || p_search || '%'
      OR e.id ILIKE '%' || p_search || '%'
      OR e.whatsapp_number ILIKE '%' || p_search || '%'
      OR e.email ILIKE '%' || p_search || '%')
    AND (p_status_filter IS NULL OR p_status_filter = '' OR s.employment_status = p_status_filter)
    AND (p_branch_filter IS NULL OR e.current_branch_id = p_branch_filter)
    AND (p_position_filter IS NULL OR e.current_position_id = p_position_filter)
  ORDER BY e.name_en ASC NULLS LAST
  LIMIT GREATEST(1, LEAST(p_limit, 200))
  OFFSET (GREATEST(1, p_page) - 1) * GREATEST(1, LEAST(p_limit, 200));
$$;


--
-- Name: get_employee_master_list(text, integer, integer, text, integer, uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_employee_master_list(p_search text DEFAULT ''::text, p_page integer DEFAULT 1, p_limit integer DEFAULT 50, p_status_filter text DEFAULT NULL::text, p_branch_filter integer DEFAULT NULL::integer, p_position_filter uuid DEFAULT NULL::uuid, p_exclude_statuses text[] DEFAULT NULL::text[]) RETURNS TABLE(id text, name_en character varying, name_ar character varying, current_branch_id integer, branch_name_en character varying, branch_name_ar character varying, branch_location_en character varying, branch_location_ar character varying, current_position_id uuid, position_title_en character varying, position_title_ar character varying, employment_status text, whatsapp_number text, email text, total_count bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    e.id, e.name_en, e.name_ar, e.current_branch_id,
    b.name_en AS branch_name_en, b.name_ar AS branch_name_ar,
    b.location_en AS branch_location_en, b.location_ar AS branch_location_ar,
    e.current_position_id, pos.position_title_en, pos.position_title_ar,
    s.employment_status, e.whatsapp_number, e.email,
    COUNT(*) OVER() AS total_count
  FROM hr_employee_master e
  LEFT JOIN branches b ON b.id = e.current_branch_id
  LEFT JOIN hr_positions pos ON pos.id = e.current_position_id
  LEFT JOIN hr_employee_current_status s ON s.employee_id = e.id
  WHERE
    (COALESCE(p_search, '') = ''
      OR e.name_en ILIKE '%' || p_search || '%'
      OR e.name_ar ILIKE '%' || p_search || '%'
      OR e.id ILIKE '%' || p_search || '%'
      OR e.whatsapp_number ILIKE '%' || p_search || '%'
      OR e.email ILIKE '%' || p_search || '%')
    AND (p_status_filter IS NULL OR p_status_filter = '' OR s.employment_status = p_status_filter)
    AND (p_branch_filter IS NULL OR e.current_branch_id = p_branch_filter)
    AND (p_position_filter IS NULL OR e.current_position_id = p_position_filter)
    AND (p_exclude_statuses IS NULL
         OR array_length(p_exclude_statuses, 1) IS NULL
         OR NOT (s.employment_status = ANY(p_exclude_statuses)))
  ORDER BY e.name_en ASC NULLS LAST
  LIMIT GREATEST(1, LEAST(p_limit, 200))
  OFFSET (GREATEST(1, p_page) - 1) * GREATEST(1, LEAST(p_limit, 200));
$$;


--
-- Name: get_employee_products(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_employee_products(p_employee_id text, p_limit integer DEFAULT 1000, p_offset integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_result JSON;
BEGIN
  SELECT json_build_object(
    'products', COALESCE((
      SELECT json_agg(row_to_json(t))
      FROM (
        SELECT 
          barcode, 
          product_name_en, 
          product_name_ar, 
          parent_barcode,
          expiry_dates,
          managed_by
        FROM erp_synced_products
        WHERE managed_by @> ('[{"employee_id":"' || p_employee_id || '"}]')::jsonb
        ORDER BY product_name_en
        LIMIT p_limit
        OFFSET p_offset
      ) t
    ), '[]'::json),
    'total_count', (
      SELECT count(*)
      FROM erp_synced_products
      WHERE managed_by @> ('[{"employee_id":"' || p_employee_id || '"}]')::jsonb
    )
  ) INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: get_employee_schedules(bigint, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_employee_schedules(p_employee_id bigint, p_start_date date, p_end_date date) RETURNS TABLE(schedule_id bigint, schedule_date date, start_time time without time zone, end_time time without time zone, hours numeric, is_overnight boolean, is_auto boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        ds.id,
        ds.schedule_date,
        ds.scheduled_start_time,
        ds.scheduled_end_time,
        ds.scheduled_hours,
        ds.is_overnight,
        ds.is_auto_generated
    FROM duty_schedules ds
    WHERE ds.employee_id = p_employee_id
      AND ds.schedule_date >= p_start_date
      AND ds.schedule_date <= p_end_date
    ORDER BY ds.schedule_date;
END;
$$;


--
-- Name: get_employee_schedules(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_employee_schedules(p_employee_id uuid, p_start_date date, p_end_date date) RETURNS TABLE(schedule_id uuid, schedule_date date, start_time time without time zone, end_time time without time zone, hours numeric, is_overnight boolean, is_auto boolean)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        ds.id,
        ds.schedule_date,
        ds.scheduled_start_time,
        ds.scheduled_end_time,
        ds.scheduled_hours,
        ds.is_overnight,
        ds.is_auto_generated
    FROM duty_schedules ds
    WHERE ds.employee_id = p_employee_id
      AND ds.schedule_date >= p_start_date
      AND ds.schedule_date <= p_end_date
    ORDER BY ds.schedule_date;
END;
$$;


--
-- Name: get_employee_status_as_of(text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_employee_status_as_of(p_employee_id text, p_date date) RETURNS TABLE(status text, effective_from date, effective_to date, reason text)
    LANGUAGE sql STABLE
    AS $$
    SELECT h.status, h.effective_from, h.effective_to, h.reason
    FROM public.hr_employee_status_history h
    WHERE h.employee_id = p_employee_id
      AND (h.effective_from IS NULL OR h.effective_from <= p_date)
      AND (h.effective_to IS NULL OR h.effective_to >= p_date)
    ORDER BY h.effective_from DESC NULLS LAST
    LIMIT 1;
$$;


--
-- Name: FUNCTION get_employee_status_as_of(p_employee_id text, p_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_employee_status_as_of(p_employee_id text, p_date date) IS 'Returns the employment status that was/is/will be active for one employee on a given date, per hr_employee_status_history.';


--
-- Name: get_erp_entry_tasks(bigint, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_erp_entry_tasks(p_branch_id bigint DEFAULT NULL::bigint, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 500) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT COALESCE(json_agg(row_to_json(r)), '[]'::json)
    FROM (
        SELECT
            e.id, e.status, e.branch_id,
            b.name_en AS branch_name_en, b.name_ar AS branch_name_ar,
            e.ledger_name, e.bill_number, e.voucher_number, e.bill_amount, e.original_bill_amount,
            e.payment_type, e.bank_ledger_name,
            e.created_by, e.created_by_name, e.created_at,
            e.payment_voucher_number, e.completed_by, e.completed_by_name, e.completed_at,
            e.task_id, e.task_assignment_id
        FROM erp_entry_tasks e
        LEFT JOIN branches b ON b.id = e.branch_id
        WHERE (p_branch_id IS NULL OR e.branch_id = p_branch_id)
          AND (p_status IS NULL OR e.status = p_status)
        ORDER BY e.created_at DESC
        LIMIT p_limit
    ) r;
$$;


--
-- Name: get_expense_category_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_expense_category_stats() RETURNS TABLE(total_parent_categories integer, enabled_parent_categories integer, disabled_parent_categories integer, total_sub_categories integer, enabled_sub_categories integer, disabled_sub_categories integer, vat_applicable_categories integer, vat_not_applicable_categories integer, both_vat_categories integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        (SELECT COUNT(*)::INT FROM expense_parent_categories) as total_parent_categories,
        (SELECT COUNT(*)::INT FROM expense_parent_categories WHERE is_enabled = true) as enabled_parent_categories,
        (SELECT COUNT(*)::INT FROM expense_parent_categories WHERE is_enabled = false) as disabled_parent_categories,
        COUNT(*)::INT as total_sub_categories,
        COUNT(*) FILTER (WHERE is_enabled = true)::INT as enabled_sub_categories,
        COUNT(*) FILTER (WHERE is_enabled = false)::INT as disabled_sub_categories,
        COUNT(*) FILTER (WHERE vat_applicable = true AND vat_not_applicable = false)::INT as vat_applicable_categories,
        COUNT(*) FILTER (WHERE vat_applicable = false AND vat_not_applicable = true)::INT as vat_not_applicable_categories,
        COUNT(*) FILTER (WHERE vat_applicable = true AND vat_not_applicable = true)::INT as both_vat_categories
    FROM expense_categories;
END;
$$;


--
-- Name: get_expiring_products_count(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_expiring_products_count(p_employee_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_branch_id INTEGER;
  v_count INTEGER := 0;
BEGIN
  -- Get employee's current branch
  SELECT current_branch_id INTO v_branch_id
  FROM hr_employee_master
  WHERE id = p_employee_id;

  IF v_branch_id IS NULL THEN
    RETURN jsonb_build_object('count', 0);
  END IF;

  -- Count products managed by this employee where expiry for their branch is < 15 days from now
  SELECT COUNT(DISTINCT p.barcode)
  INTO v_count
  FROM erp_synced_products p,
       LATERAL jsonb_array_elements(COALESCE(p.expiry_dates, '[]'::jsonb)) AS ed
  WHERE p.managed_by @> ('[{"employee_id":"' || p_employee_id || '"}]')::jsonb
    AND (ed->>'branch_id')::INTEGER = v_branch_id
    AND (ed->>'expiry_date') IS NOT NULL
    AND (ed->>'expiry_date')::DATE >= CURRENT_DATE
    AND (ed->>'expiry_date')::DATE < (CURRENT_DATE + INTERVAL '15 days');

  RETURN jsonb_build_object('count', v_count);
END;
$$;


--
-- Name: get_file_extension(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_file_extension(filename text) RETURNS text
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN lower(split_part(filename, '.', array_length(string_to_array(filename, '.'), 1)));
END;
$$;


--
-- Name: get_flagged_drawer_events(integer, date, date, boolean, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_flagged_drawer_events(p_branch_id integer DEFAULT NULL::integer, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_flagged_only boolean DEFAULT false, p_small_print_bytes bigint DEFAULT 51200) RETURNS TABLE(id bigint, branch_id integer, branch_name text, counter_name text, event_type text, event_time timestamp without time zone, byte_size bigint, user_name text, document_name text, printer_name text, erp_counter_id integer, is_small_print boolean, matched_action_name text, matched_voucher_number text, matched_user_name text, seconds_to_match numeric, is_flagged boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    -- erp_user_actions (the periodically-synced copy this used to LATERAL-join against for
    -- matching) was removed 2026-09 along with ERP-mode sync -- it had no consumer besides this
    -- join, since the "User Actions" reporting window always queried the ERP live via the bridge
    -- tunnel instead. The matched_*/is_flagged columns below are now always NULL: there is no
    -- synced copy left to match against. The Drawer Action Monitor's "Live ERP Check" tab performs
    -- the real matching itself, live via the tunnel, independent of these columns -- this RPC now
    -- only supplies it the list of print/drawer events to check.
    SELECT
        pa.id,
        pa.branch_id,
        COALESCE(b.name_en, 'Branch ' || pa.branch_id) AS branch_name,
        pa.counter_name,
        pa.event_type,
        pa.event_time + INTERVAL '3 hours' AS event_time,
        pa.byte_size,
        pa.user_name,
        pa.document_name,
        pa.printer_name,
        pa.erp_counter_id,
        (pa.byte_size IS NOT NULL AND pa.byte_size <= p_small_print_bytes) AS is_small_print,
        NULL::text AS matched_action_name,
        NULL::text AS matched_voucher_number,
        NULL::text AS matched_user_name,
        NULL::numeric AS seconds_to_match,
        NULL::boolean AS is_flagged
    FROM public.erp_print_actions pa
    LEFT JOIN public.branches b ON b.id = pa.branch_id
    WHERE (p_branch_id IS NULL OR pa.branch_id = p_branch_id)
      AND (p_date_from IS NULL OR (pa.event_time + INTERVAL '3 hours')::date >= p_date_from)
      AND (p_date_to IS NULL OR (pa.event_time + INTERVAL '3 hours')::date <= p_date_to)
      AND (NOT p_flagged_only)
    ORDER BY pa.event_time DESC;
$$;


--
-- Name: get_flyer_generator_data(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_flyer_generator_data(p_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  result jsonb;
BEGIN
  WITH 
  -- Step 1: Get all offer products for this offer
  offer_products AS (
    SELECT 
      fop.id,
      fop.offer_id,
      fop.product_barcode,
      fop.cost,
      fop.sales_price,
      fop.offer_price,
      fop.profit_amount,
      fop.profit_percent,
      fop.profit_after_offer,
      fop.decrease_amount,
      fop.offer_qty,
      fop.limit_qty,
      fop.free_qty,
      fop.created_at,
      fop.page_number,
      fop.page_order,
      fop.total_sales_price,
      fop.total_offer_price
    FROM flyer_offer_products fop
    WHERE fop.offer_id = p_offer_id
  ),
  -- Step 2: Get product details for all barcodes in the offer
  product_details AS (
    SELECT 
      p.barcode,
      p.product_name_en,
      p.product_name_ar,
      p.image_url,
      p.is_variation,
      p.parent_product_barcode,
      p.variation_group_name_en,
      p.variation_group_name_ar,
      p.variation_image_override,
      p.variation_order,
      pu.name_ar AS unit_name_ar,
      pu.name_en AS unit_name_en
    FROM products p
    LEFT JOIN product_units pu ON p.unit_id = pu.id
    WHERE p.barcode IN (SELECT product_barcode FROM offer_products)
  ),
  -- Step 3: Get variation images for all variations in the offer
  -- (grouped by parent_product_barcode)
  variation_images AS (
    SELECT 
      p.parent_product_barcode,
      jsonb_agg(
        jsonb_build_object(
          'barcode', p.barcode,
          'image_url', p.image_url,
          'variation_order', COALESCE(p.variation_order, 0)
        ) ORDER BY COALESCE(p.variation_order, 0)
      ) AS images
    FROM products p
    WHERE p.is_variation = true
      AND p.parent_product_barcode IS NOT NULL
      AND p.barcode IN (SELECT product_barcode FROM offer_products)
    GROUP BY p.parent_product_barcode
  ),
  -- Step 4: Build combined result for each offer product
  combined AS (
    SELECT 
      jsonb_build_object(
        'id', op.id,
        'offer_id', op.offer_id,
        'product_barcode', op.product_barcode,
        'cost', op.cost,
        'sales_price', op.sales_price,
        'offer_price', op.offer_price,
        'profit_amount', op.profit_amount,
        'profit_percent', op.profit_percent,
        'profit_after_offer', op.profit_after_offer,
        'decrease_amount', op.decrease_amount,
        'offer_qty', op.offer_qty,
        'limit_qty', op.limit_qty,
        'free_qty', op.free_qty,
        'created_at', op.created_at,
        'page_number', COALESCE(op.page_number, 1),
        'page_order', COALESCE(op.page_order, 1),
        'total_sales_price', op.total_sales_price,
        'total_offer_price', op.total_offer_price,
        'product_name_en', COALESCE(pd.product_name_en, ''),
        'product_name_ar', COALESCE(pd.product_name_ar, ''),
        'unit_name', COALESCE(pd.unit_name_ar, ''),
        'image_url', COALESCE(pd.image_url, pd.variation_image_override),
        'is_variation', COALESCE(pd.is_variation, false),
        'parent_product_barcode', pd.parent_product_barcode,
        'variation_group_name_en', pd.variation_group_name_en,
        'variation_group_name_ar', pd.variation_group_name_ar,
        'variation_order', pd.variation_order,
        'variation_images', COALESCE(vi.images, '[]'::jsonb)
      ) AS product_data
    FROM offer_products op
    LEFT JOIN product_details pd ON pd.barcode = op.product_barcode
    LEFT JOIN variation_images vi ON vi.parent_product_barcode = op.product_barcode
                                  OR vi.parent_product_barcode = pd.parent_product_barcode
  )
  SELECT jsonb_build_object(
    'products', COALESCE(jsonb_agg(c.product_data), '[]'::jsonb)
  )
  INTO result
  FROM combined c;

  RETURN COALESCE(result, jsonb_build_object('products', '[]'::jsonb));
END;
$$;


--
-- Name: get_flyer_template_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_flyer_template_detail(p_template_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result json;
BEGIN
  SELECT json_build_object(
    'id', t.id, 'name', t.name, 'description', t.description,
    'first_page_image_url', t.first_page_image_url, 'sub_page_image_urls', t.sub_page_image_urls,
    'first_page_configuration', t.first_page_configuration,
    'sub_page_configurations', t.sub_page_configurations, 'metadata', t.metadata,
    'is_active', t.is_active, 'is_default', t.is_default, 'category', t.category,
    'usage_count', t.usage_count, 'created_at', t.created_at
  ) INTO v_result
  FROM flyer_templates t
  WHERE t.id = p_template_id;

  IF v_result IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Template not found');
  END IF;

  RETURN json_build_object('success', true, 'data', v_result);
END;
$$;


--
-- Name: get_followup_occurrences(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_followup_occurrences() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_result json;
BEGIN
  SELECT json_build_object('success', true,
    'data', COALESCE(json_agg(row_to_json(r) ORDER BY r.due_date DESC, r.id DESC), '[]'::json))
  FROM (
    SELECT o.*, e.name_en as created_by_name
    FROM action_followup_other_occurrences o
    LEFT JOIN hr_employee_master e ON e.user_id = o.created_by
    ORDER BY o.due_date DESC, o.id DESC
    LIMIT 200
  ) r INTO v_result;
  RETURN v_result;
END;
$$;


--
-- Name: get_hr_date_wise_shifts(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_hr_date_wise_shifts(p_employee_ids text[]) RETURNS TABLE(employee_id text, version_id bigint, date_from date, date_to date, slot_order integer, shift_start_time time without time zone, shift_start_buffer numeric, shift_end_time time without time zone, shift_end_buffer numeric, is_shift_overlapping_next_day boolean, working_hours numeric, allowed_late_start_minutes integer, allowed_early_end_minutes integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT v.employee_id, v.id AS version_id, v.date_from, v.date_to,
           sl.slot_order, sl.shift_start_time, sl.shift_start_buffer,
           sl.shift_end_time, sl.shift_end_buffer,
           sl.is_shift_overlapping_next_day, sl.working_hours,
           sl.allowed_late_start_minutes, sl.allowed_early_end_minutes
    FROM hr_special_shift_date_wise_versions v
    JOIN hr_special_shift_date_wise_slots sl ON sl.version_id = v.id
    WHERE v.employee_id = ANY(p_employee_ids)
