--
-- Name: lockguard_heartbeat(text, bigint, text, text, text, boolean, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lockguard_heartbeat(p_device_id text, p_branch_id bigint, p_hostname text DEFAULT NULL::text, p_ip_address text DEFAULT NULL::text, p_protection_state text DEFAULT 'unknown'::text, p_maintenance_mode boolean DEFAULT false, p_os_version text DEFAULT NULL::text, p_app_version text DEFAULT NULL::text, p_counter_name text DEFAULT NULL::text, p_device_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    INSERT INTO public.lockguard_devices (device_id, branch_id, counter_name, device_name, hostname, ip_address, protection_state, maintenance_mode, os_version, app_version, last_seen)
    VALUES (p_device_id, p_branch_id, p_counter_name, p_device_name, p_hostname, p_ip_address, p_protection_state, p_maintenance_mode, p_os_version, p_app_version, now())
    ON CONFLICT (device_id) DO UPDATE SET
        branch_id = EXCLUDED.branch_id,
        counter_name = COALESCE(EXCLUDED.counter_name, lockguard_devices.counter_name),
        device_name = COALESCE(EXCLUDED.device_name, lockguard_devices.device_name),
        hostname = COALESCE(EXCLUDED.hostname, lockguard_devices.hostname),
        ip_address = COALESCE(EXCLUDED.ip_address, lockguard_devices.ip_address),
        protection_state = EXCLUDED.protection_state, maintenance_mode = EXCLUDED.maintenance_mode,
        os_version = COALESCE(EXCLUDED.os_version, lockguard_devices.os_version),
        app_version = COALESCE(EXCLUDED.app_version, lockguard_devices.app_version),
        last_seen = now(), updated_at = now();
    INSERT INTO public.lockguard_heartbeats (device_id, branch_id, hostname, ip_address, protection_state, maintenance_mode)
    VALUES (p_device_id, p_branch_id, p_hostname, p_ip_address, p_protection_state, p_maintenance_mode)
    ON CONFLICT (device_id) DO UPDATE SET branch_id = EXCLUDED.branch_id, hostname = EXCLUDED.hostname,
        ip_address = EXCLUDED.ip_address, protection_state = EXCLUDED.protection_state,
        maintenance_mode = EXCLUDED.maintenance_mode, created_at = now();
    RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: log_offer_usage(integer, uuid, integer, numeric, numeric, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_offer_usage(p_offer_id integer, p_customer_id uuid, p_order_id integer, p_discount_applied numeric, p_original_amount numeric, p_final_amount numeric, p_cart_items jsonb DEFAULT NULL::jsonb) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_log_id INTEGER;
BEGIN
    -- Insert usage log
    INSERT INTO offer_usage_logs (
        offer_id, customer_id, order_id,
        discount_applied, original_amount, final_amount,
        cart_items
    ) VALUES (
        p_offer_id, p_customer_id, p_order_id,
        p_discount_applied, p_original_amount, p_final_amount,
        p_cart_items
    ) RETURNING id INTO v_log_id;
    
    -- Increment offer usage counter
    UPDATE offers
    SET current_total_uses = current_total_uses + 1
    WHERE id = p_offer_id;
    
    -- Update customer_offers if customer-specific
    UPDATE customer_offers
    SET is_used = true,
        used_at = NOW(),
        usage_count = usage_count + 1
    WHERE offer_id = p_offer_id AND customer_id = p_customer_id;
    
    RETURN v_log_id;
END;
$$;


--
-- Name: log_user_action(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_user_action() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO user_audit_logs (
        user_id,
        action,
        table_name,
        record_id,
        old_values,
        new_values,
        created_at
    ) VALUES (
        CASE 
            WHEN TG_OP = 'DELETE' THEN OLD.id
            ELSE NEW.id
        END,
        TG_OP,
        TG_TABLE_NAME,
        CASE 
            WHEN TG_OP = 'DELETE' THEN OLD.id
            ELSE NEW.id
        END,
        CASE 
            WHEN TG_OP = 'UPDATE' THEN row_to_json(OLD)
            WHEN TG_OP = 'DELETE' THEN row_to_json(OLD)
            ELSE NULL
        END,
        CASE 
            WHEN TG_OP = 'INSERT' THEN row_to_json(NEW)
            WHEN TG_OP = 'UPDATE' THEN row_to_json(NEW)
            ELSE NULL
        END,
        now()
    );
    
    RETURN CASE 
        WHEN TG_OP = 'DELETE' THEN OLD
        ELSE NEW
    END;
END;
$$;


--
-- Name: manage_product_branch(text, text[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manage_product_branch(p_employee_id text, p_barcodes text[], p_branch_changes jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    UPDATE erp_synced_products
    SET managed_by = (
        SELECT jsonb_agg(
            CASE
                WHEN elem->>'employee_id' = p_employee_id THEN
                    elem || jsonb_build_object(
                        'branch_id',
                        COALESCE(
                            (SELECT (chg->>'to_id')::INTEGER
                             FROM jsonb_array_elements(p_branch_changes) AS chg
                             WHERE (chg->>'from_id')::INTEGER = (elem->>'branch_id')::INTEGER
                             LIMIT 1),
                            (elem->>'branch_id')::INTEGER
                        )
                    )
                ELSE elem
            END
        )
        FROM jsonb_array_elements(managed_by) AS elem
    )
    WHERE barcode = ANY(p_barcodes)
      AND managed_by IS NOT NULL;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


--
-- Name: mark_overdue_quick_tasks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_overdue_quick_tasks() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Mark main tasks as overdue
    UPDATE quick_tasks 
    SET status = 'overdue', updated_at = NOW()
    WHERE deadline_datetime < NOW() 
    AND status NOT IN ('completed', 'overdue');
    
    -- Mark individual assignments as overdue
    UPDATE quick_task_assignments
    SET status = 'overdue', updated_at = NOW()
    WHERE quick_task_id IN (
        SELECT id FROM quick_tasks 
        WHERE deadline_datetime < NOW()
    )
    AND status NOT IN ('completed', 'overdue');
END;
$$;


