--
-- Name: publish_ai_flyer(uuid, bigint, text, date, time without time zone, date, time without time zone, text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_ai_flyer(p_flyer_id uuid, p_branch_id bigint, p_offer_name text, p_start_date date, p_start_time time without time zone, p_end_date date, p_end_time time without time zone, p_file_url text, p_thumbnail_url text, p_page_paths text[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_offer_id uuid;
BEGIN
  SELECT view_offer_id INTO v_offer_id FROM ai_flyer_publications WHERE flyer_id = p_flyer_id AND branch_id = p_branch_id;

  IF v_offer_id IS NOT NULL AND EXISTS (SELECT 1 FROM view_offer WHERE id = v_offer_id) THEN
    UPDATE view_offer SET
      offer_name = p_offer_name,
      start_date = p_start_date,
      start_time = p_start_time,
      end_date = p_end_date,
      end_time = p_end_time,
      file_url = p_file_url,
      thumbnail_url = p_thumbnail_url,
      status = 'published',
      updated_at = now()
    WHERE id = v_offer_id;

    UPDATE ai_flyer_publications SET page_paths = p_page_paths, updated_at = now()
    WHERE flyer_id = p_flyer_id AND branch_id = p_branch_id;
  ELSE
    INSERT INTO view_offer (
      offer_name, branch_id, start_date, start_time, end_date, end_time,
      file_url, thumbnail_url, status
    ) VALUES (
      p_offer_name, p_branch_id, p_start_date, p_start_time, p_end_date, p_end_time,
      p_file_url, p_thumbnail_url, 'published'
    ) RETURNING id INTO v_offer_id;

    INSERT INTO ai_flyer_publications (flyer_id, view_offer_id, branch_id, page_paths)
    VALUES (p_flyer_id, v_offer_id, p_branch_id, p_page_paths);
  END IF;

  INSERT INTO ai_flyer_publish_log (flyer_id, view_offer_id, action)
  VALUES (p_flyer_id, v_offer_id, 'publish');

  RETURN v_offer_id;
END;
$$;


--
-- Name: queue_email_send(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_email_send(p_message_id uuid, p_queue_type text DEFAULT 'normal'::text, p_priority integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_account_id uuid;
  v_queue_id uuid;
  v_idempotency_key text;
  v_sent_folder_id uuid;
BEGIN
  -- Get account
  SELECT email_account_id INTO v_account_id FROM public.email_messages WHERE id = p_message_id;
  
  IF v_account_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Message not found');
  END IF;

  -- Get or create sent folder
  SELECT id INTO v_sent_folder_id FROM public.email_folders 
  WHERE email_account_id = v_account_id AND folder_type = 'sent' LIMIT 1;
  
  IF v_sent_folder_id IS NULL THEN
    INSERT INTO public.email_folders (email_account_id, remote_folder_name, display_name, folder_type)
    VALUES (v_account_id, 'Sent', 'Sent', 'sent')
    RETURNING id INTO v_sent_folder_id;
  END IF;

  -- Generate idempotency key
  v_idempotency_key := 'send-' || p_message_id::text || '-' || extract(epoch from now())::text;

  -- Update message: mark as queued, move to Sent folder, set direction
  UPDATE public.email_messages 
  SET status = 'queued', is_draft = false, folder_id = v_sent_folder_id, direction = 'outbound'
  WHERE id = p_message_id;

  -- Create queue item
  INSERT INTO public.email_queue (queue_type, priority, email_account_id, email_message_id, status, idempotency_key)
  VALUES (p_queue_type, p_priority, v_account_id, p_message_id, 'waiting', v_idempotency_key)
  RETURNING id INTO v_queue_id;

  INSERT INTO public.email_logs (event_type, email_account_id, email_message_id, queue_item_id, user_id, safe_message)
  VALUES ('message_queued', v_account_id, p_message_id, v_queue_id, auth.uid(), 'Email queued for sending');

  RETURN jsonb_build_object('success', true, 'queue_id', v_queue_id);
END;
$$;


--
-- Name: queue_push_notification(uuid, text, jsonb, text[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_push_notification(p_notification_id uuid, p_target_type text, p_target_users jsonb DEFAULT NULL::jsonb, p_target_roles text[] DEFAULT NULL::text[], p_target_branches uuid[] DEFAULT NULL::uuid[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    user_record RECORD;
    subscription_record RECORD;
    notification_data RECORD;
BEGIN
    -- Get notification data
    SELECT 
        title,
        body,
        type,
        created_at
    INTO notification_data
    FROM notifications 
    WHERE id = p_notification_id;
    
    IF NOT FOUND THEN
        RETURN;
    END IF;
    
    -- Process based on target type
    CASE p_target_type
        WHEN 'all_users' THEN
            -- Queue for all active users with push subscriptions
            FOR subscription_record IN 
                SELECT DISTINCT ps.user_id, ps.endpoint, ps.p256dh, ps.auth
                FROM push_subscriptions ps
                JOIN users u ON ps.user_id = u.id
                WHERE u.status = 'active'
                  AND ps.status = 'active'
            LOOP
                INSERT INTO notification_queue (
                    notification_id,
                    user_id,
                    endpoint,
                    p256dh,
                    auth,
                    payload,
                    status,
                    created_at
                ) VALUES (
                    p_notification_id,
                    subscription_record.user_id,
                    subscription_record.endpoint,
                    subscription_record.p256dh,
                    subscription_record.auth,
                    jsonb_build_object(
                        'title', notification_data.title,
                        'body', notification_data.body,
                        'type', notification_data.type,
                        'notification_id', p_notification_id
                    ),
                    'pending',
                    NOW()
                );
            END LOOP;
            
        WHEN 'specific_users' THEN
            -- Queue for specific users
            IF p_target_users IS NOT NULL THEN
                FOR subscription_record IN 
                    SELECT DISTINCT ps.user_id, ps.endpoint, ps.p256dh, ps.auth
                    FROM push_subscriptions ps
                    JOIN users u ON ps.user_id = u.id
                    WHERE u.status = 'active'
                      AND ps.status = 'active'
                      AND ps.user_id = ANY(
                          SELECT jsonb_array_elements_text(p_target_users)::UUID
                      )
                LOOP
                    INSERT INTO notification_queue (
                        notification_id,
                        user_id,
                        endpoint,
                        p256dh,
                        auth,
                        payload,
                        status,
                        created_at
                    ) VALUES (
                        p_notification_id,
                        subscription_record.user_id,
                        subscription_record.endpoint,
                        subscription_record.p256dh,
                        subscription_record.auth,
                        jsonb_build_object(
                            'title', notification_data.title,
                            'body', notification_data.body,
                            'type', notification_data.type,
                            'notification_id', p_notification_id
                        ),
                        'pending',
                        NOW()
                    );
                END LOOP;
            END IF;
            
        WHEN 'specific_roles' THEN
            -- Queue for users with specific roles
            IF p_target_roles IS NOT NULL THEN
                FOR subscription_record IN 
                    SELECT DISTINCT ps.user_id, ps.endpoint, ps.p256dh, ps.auth
                    FROM push_subscriptions ps
                    JOIN users u ON ps.user_id = u.id
                    JOIN user_roles ur ON u.id = ur.user_id
                    WHERE u.status = 'active'
                      AND ps.status = 'active'
                      AND ur.role_name = ANY(p_target_roles)
                LOOP
                    INSERT INTO notification_queue (
                        notification_id,
                        user_id,
                        endpoint,
                        p256dh,
                        auth,
                        payload,
                        status,
                        created_at
                    ) VALUES (
                        p_notification_id,
                        subscription_record.user_id,
                        subscription_record.endpoint,
                        subscription_record.p256dh,
                        subscription_record.auth,
                        jsonb_build_object(
                            'title', notification_data.title,
                            'body', notification_data.body,
                            'type', notification_data.type,
                            'notification_id', p_notification_id
                        ),
                        'pending',
                        NOW()
                    );
                END LOOP;
            END IF;
            
        WHEN 'specific_branches' THEN
            -- Queue for users in specific branches
            IF p_target_branches IS NOT NULL THEN
                FOR subscription_record IN 
                    SELECT DISTINCT ps.user_id, ps.endpoint, ps.p256dh, ps.auth
                    FROM push_subscriptions ps
                    JOIN users u ON ps.user_id = u.id
                    JOIN hr_employees e ON u.employee_id = e.id
                    WHERE u.status = 'active'
                      AND ps.status = 'active'
                      AND e.branch_id = ANY(p_target_branches)
                LOOP
                    INSERT INTO notification_queue (
                        notification_id,
                        user_id,
                        endpoint,
                        p256dh,
                        auth,
                        payload,
                        status,
                        created_at
                    ) VALUES (
                        p_notification_id,
                        subscription_record.user_id,
                        subscription_record.endpoint,
                        subscription_record.p256dh,
                        subscription_record.auth,
                        jsonb_build_object(
                            'title', notification_data.title,
                            'body', notification_data.body,
                            'type', notification_data.type,
                            'notification_id', p_notification_id
                        ),
                        'pending',
                        NOW()
                    );
                END LOOP;
            END IF;
    END CASE;
END;
$$;


--
-- Name: queue_quick_task_push_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_quick_task_push_notifications() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    user_record RECORD;
    notification_payload jsonb;
BEGIN
    -- Only process if this is a task assignment notification
    IF NEW.type = 'task_assignment' AND NEW.target_users IS NOT NULL THEN
        -- Extract assignment details from metadata
        notification_payload := jsonb_build_object(
            'title', NEW.title,
            'body', NEW.message,
            'icon', '/favicon.ico',
            'badge', '/favicon.ico',
            'data', jsonb_build_object(
                'notificationId', NEW.id,
                'type', NEW.type,
                'quick_task_id', (NEW.metadata->>'quick_task_id'),
                'assignment_details', (NEW.metadata->>'assignment_details'),
                'url', '/mobile/quick-task'
            )
        );

        -- Queue push notifications for each target user
        FOR user_record IN 
            SELECT DISTINCT jsonb_array_elements_text(NEW.target_users) as user_id
        LOOP
            INSERT INTO notification_queue (
                notification_id,
                user_id,
                status,
                payload,
                created_at
            ) VALUES (
                NEW.id,
                user_record.user_id::uuid,
                'pending',
                notification_payload,
                NOW()
            );
        END LOOP;
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION queue_quick_task_push_notifications(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.queue_quick_task_push_notifications() IS 'Enhanced queue function with better payload information for Quick Task notifications';


--
-- Name: reassign_task(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reassign_task(assignment_id uuid, new_assignee uuid, reassigned_by uuid, reason text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    UPDATE task_assignments 
    SET 
        assigned_to = new_assignee,
        reassigned_by = reassigned_by,
        reassignment_reason = reason,
        updated_at = NOW()
    WHERE id = assignment_id;
    
    RETURN FOUND;
END;
$$;


--
-- Name: reassign_task(uuid, text, text, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reassign_task(p_assignment_id uuid, p_reassigned_by text, p_new_user_id text DEFAULT NULL::text, p_new_branch_id uuid DEFAULT NULL::uuid, p_reassignment_reason text DEFAULT NULL::text, p_copy_deadline boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    new_assignment_id UUID;
    original_assignment RECORD;
BEGIN
    -- Get original assignment details
    SELECT * INTO original_assignment 
    FROM public.task_assignments 
    WHERE id = p_assignment_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Assignment not found: %', p_assignment_id;
    END IF;
    
    IF NOT original_assignment.is_reassignable THEN
        RAISE EXCEPTION 'Assignment is not reassignable: %', p_assignment_id;
    END IF;
    
    -- Create new assignment
    INSERT INTO public.task_assignments (
        task_id,
        assignment_type,
        assigned_to_user_id,
        assigned_to_branch_id,
        assigned_by,
        assigned_by_name,
        schedule_date,
        schedule_time,
        deadline_date,
        deadline_time,
        is_reassignable,
        notes,
        priority_override,
        require_task_finished,
        require_photo_upload,
        require_erp_reference,
        reassigned_from,
        reassignment_reason,
        reassigned_at
    ) VALUES (
        original_assignment.task_id,
        original_assignment.assignment_type,
        p_new_user_id,
        p_new_branch_id,
        p_reassigned_by,
        NULL, -- Will be filled by the application
        CASE WHEN p_copy_deadline THEN original_assignment.schedule_date ELSE NULL END,
        CASE WHEN p_copy_deadline THEN original_assignment.schedule_time ELSE NULL END,
        CASE WHEN p_copy_deadline THEN original_assignment.deadline_date ELSE NULL END,
        CASE WHEN p_copy_deadline THEN original_assignment.deadline_time ELSE NULL END,
        original_assignment.is_reassignable,
        original_assignment.notes,
        original_assignment.priority_override,
        original_assignment.require_task_finished,
        original_assignment.require_photo_upload,
        original_assignment.require_erp_reference,
        p_assignment_id,
        p_reassignment_reason,
        now()
    )
    RETURNING id INTO new_assignment_id;
    
    -- Mark original assignment as reassigned
    UPDATE public.task_assignments 
    SET status = 'reassigned',
        completed_at = now()
    WHERE id = p_assignment_id;
    
    RETURN new_assignment_id;
END;
$$;


--
-- Name: FUNCTION reassign_task(p_assignment_id uuid, p_reassigned_by text, p_new_user_id text, p_new_branch_id uuid, p_reassignment_reason text, p_copy_deadline boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reassign_task(p_assignment_id uuid, p_reassigned_by text, p_new_user_id text, p_new_branch_id uuid, p_reassignment_reason text, p_copy_deadline boolean) IS 'Reassigns a task to a different user or branch while maintaining audit trail';


--
-- Name: record_fine_payment(uuid, numeric, character varying, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_fine_payment(warning_id_param uuid, payment_amount_param numeric, payment_method_param character varying, payment_reference_param character varying, processed_by_param uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    payment_id UUID;
    total_paid DECIMAL(10,2);
    fine_amount DECIMAL(10,2);
BEGIN
    -- Get the fine amount
    SELECT ew.fine_amount INTO fine_amount
    FROM employee_warnings ew
    WHERE ew.id = warning_id_param;
    
    -- Insert payment record
    INSERT INTO employee_fine_payments (
        warning_id, payment_amount, payment_method, 
        payment_reference, processed_by
    ) VALUES (
        warning_id_param, payment_amount_param, payment_method_param,
        payment_reference_param, processed_by_param
    ) RETURNING id INTO payment_id;
    
    -- Calculate total paid
    SELECT COALESCE(SUM(payment_amount), 0) INTO total_paid
    FROM employee_fine_payments
    WHERE warning_id = warning_id_param;
    
    -- Update warning status based on payment
    UPDATE employee_warnings
    SET 
        fine_paid_amount = total_paid,
        fine_status = CASE 
            WHEN total_paid >= fine_amount THEN 'paid'
            WHEN total_paid > 0 THEN 'partial'
            ELSE 'pending'
        END,
        fine_paid_date = CASE 
            WHEN total_paid >= fine_amount THEN CURRENT_TIMESTAMP
            ELSE fine_paid_date
        END,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = warning_id_param;
    
    RETURN payment_id;
END;
$$;


--
-- Name: refresh_broadcast_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_broadcast_status(p_broadcast_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_total int;
    v_sent_count int;
    v_delivered_count int;
    v_read_count int;
    v_failed_count int;
    v_pending_count int;
    v_broadcast_status text;
    v_old_status text;
BEGIN
    -- Step 1: Update broadcast recipients whose wa_messages have a higher status
    UPDATE wa_broadcast_recipients r
    SET status = sub.new_status
    FROM (
        SELECT 
            r2.id AS recipient_id,
            (
                SELECT m.status
                FROM wa_messages m
                WHERE m.whatsapp_message_id = r2.whatsapp_message_id
                ORDER BY 
                    CASE m.status
                        WHEN 'read' THEN 3
                        WHEN 'delivered' THEN 2
                        WHEN 'sent' THEN 1
                        ELSE 0
                    END DESC
                LIMIT 1
            ) AS new_status
        FROM wa_broadcast_recipients r2
        WHERE r2.broadcast_id = p_broadcast_id
          AND r2.whatsapp_message_id IS NOT NULL
    ) sub
    WHERE r.id = sub.recipient_id
      AND sub.new_status IS NOT NULL
      AND (
          CASE sub.new_status
              WHEN 'read' THEN 3
              WHEN 'delivered' THEN 2
              WHEN 'sent' THEN 1
              ELSE 0
          END
      ) > (
          CASE r.status
              WHEN 'read' THEN 3
              WHEN 'delivered' THEN 2
              WHEN 'sent' THEN 1
              ELSE 0
          END
      );

    -- Step 2: Count statuses (exclusive - each recipient counted in exactly one category)
    SELECT 
        count(*) FILTER (WHERE status = 'pending'),
        count(*) FILTER (WHERE status = 'sent'),
        count(*) FILTER (WHERE status = 'delivered'),
        count(*) FILTER (WHERE status = 'read'),
        count(*) FILTER (WHERE status = 'failed'),
        count(*)
    INTO v_pending_count, v_sent_count, v_delivered_count, v_read_count, v_failed_count, v_total
    FROM wa_broadcast_recipients
    WHERE broadcast_id = p_broadcast_id;

    -- Step 3: Determine broadcast status
    SELECT status INTO v_old_status FROM wa_broadcasts WHERE id = p_broadcast_id;
    v_broadcast_status := v_old_status;
    
    IF v_pending_count > 0 THEN
        v_broadcast_status := 'sending';
    ELSIF v_failed_count = v_total AND v_total > 0 THEN
        v_broadcast_status := 'failed';
    ELSIF v_pending_count = 0 AND v_total > 0 THEN
        v_broadcast_status := 'completed';
    END IF;

    -- Step 4: Update the broadcast row with exclusive counts
    UPDATE wa_broadcasts
    SET 
        sent_count = v_sent_count,
        delivered_count = v_delivered_count,
        read_count = v_read_count,
        failed_count = v_failed_count,
        total_recipients = v_total,
        status = v_broadcast_status
    WHERE id = p_broadcast_id;

    -- Return summary
    RETURN jsonb_build_object(
        'status', v_broadcast_status,
        'total_recipients', v_total,
        'sent_count', v_sent_count,
        'delivered_count', v_delivered_count,
        'read_count', v_read_count,
        'failed_count', v_failed_count,
        'pending_count', v_pending_count
    );
END;
$$;


--
-- Name: refresh_edge_functions_cache(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_edge_functions_cache(p_functions jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  DELETE FROM public.edge_functions_cache;
  INSERT INTO public.edge_functions_cache (func_name, func_size, file_count, last_modified, has_index, func_code)
  SELECT
    (f->>'func_name')::text,
    (f->>'func_size')::text,
    (f->>'file_count')::int,
    to_timestamp((f->>'last_modified')::bigint),
    (f->>'has_index')::boolean,
    (f->>'func_code')::text
  FROM jsonb_array_elements(p_functions) AS f;
END;
$$;


