--
-- Name: reopen_incident_cascade(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_incident_cascade(p_incident_id text, p_actor_user_id uuid, p_session_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor uuid := p_actor_user_id;
  v_incident public.incidents%rowtype;
  v_action_count integer := 0;
  v_task_count integer := 0;
  v_assignment_count integer := 0;
  v_reset_statuses jsonb;
begin
  if v_actor is null or not exists (
    select 1
    from public.users u
    where u.id = v_actor
      and u.status = 'active'
      and coalesce(u.is_master_admin, false)
      and (
        auth.uid() = v_actor
        or exists (
          select 1
          from public.user_sessions us
          where us.user_id = v_actor
            and us.session_token = p_session_token
            and us.is_active = true
            and us.expires_at > now()
        )
      )
  ) then
    raise exception 'A valid active Master Admin session is required to reopen an incident';
  end if;

  select *
  into v_incident
  from public.incidents i
  where i.id::text = p_incident_id
  for update;

  if not found then
    raise exception 'Incident % was not found', p_incident_id;
  end if;

  if v_incident.resolution_status not in ('claimed', 'resolved') then
    raise exception 'Only claimed or resolved incidents can be reopened';
  end if;

  select coalesce(
    jsonb_object_agg(s.user_id, jsonb_build_object('status', 'reported')),
    '{}'::jsonb
  )
  into v_reset_statuses
  from jsonb_each(coalesce(v_incident.user_statuses, '{}'::jsonb)) s(user_id, status_data);

  select count(*)::integer
  into v_assignment_count
  from public.quick_task_assignments qta
  join public.quick_tasks qt on qt.id = qta.quick_task_id
  where qt.incident_id::text = p_incident_id;

  delete from public.quick_task_assignments qta
  using public.quick_tasks qt
  where qta.quick_task_id = qt.id
    and qt.incident_id::text = p_incident_id;

  delete from public.quick_tasks qt
  where qt.incident_id::text = p_incident_id;
  get diagnostics v_task_count = row_count;

  delete from public.incident_actions ia
  where ia.incident_id::text = p_incident_id;
  get diagnostics v_action_count = row_count;

  update public.incidents
  set resolution_status = 'reported',
      claims_status = null,
      claimed_user_id = null,
      user_statuses = v_reset_statuses,
      investigation_report = null,
      resolution_report = null,
      updated_at = now(),
      updated_by = v_actor
  where id::text = p_incident_id;

  return jsonb_build_object(
    'success', true,
    'incident_id', p_incident_id,
    'incident_actions_removed', v_action_count,
    'quick_tasks_removed', v_task_count,
    'task_assignments_removed', v_assignment_count
  );
end;
$$;


--
-- Name: request_access_code_change(character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_access_code_change(p_email character varying, p_whatsapp character varying) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_otp VARCHAR(6);
  v_whatsapp_clean VARCHAR(20);
BEGIN
  -- Clean WhatsApp number (remove spaces, dashes)
  v_whatsapp_clean := REGEXP_REPLACE(p_whatsapp, '[\s\-]', '', 'g');

  -- Find the user by matching email AND whatsapp_number in hr_employee_master
  -- Correct relationship: hr_employee_master.user_id = users.id
  SELECT u.id INTO v_user_id
  FROM users u
  JOIN hr_employee_master e ON e.user_id = u.id
  WHERE LOWER(TRIM(e.email)) = LOWER(TRIM(p_email))
    AND REGEXP_REPLACE(e.whatsapp_number, '[\s\-]', '', 'g') = v_whatsapp_clean
    AND u.status = 'active'
  LIMIT 1;

  IF v_user_id IS NULL THEN
    RETURN json_build_object(
      'success', false,
      'message', 'No matching user found. Please check your email and WhatsApp number.'
    );
  END IF;

  -- Rate limit: max 3 OTP requests per hour per user
  IF (
    SELECT COUNT(*) FROM access_code_otp
    WHERE user_id = v_user_id
      AND created_at > NOW() - INTERVAL '1 hour'
  ) >= 3 THEN
    RETURN json_build_object(
      'success', false,
      'message', 'Too many requests. Please try again later.'
    );
  END IF;

  -- Delete any existing unused OTPs for this user
  DELETE FROM access_code_otp WHERE user_id = v_user_id AND verified = false;

  -- Generate 6-digit OTP
  v_otp := LPAD(FLOOR(RANDOM() * 1000000)::TEXT, 6, '0');

  -- Store OTP (expires in 5 minutes)
  INSERT INTO access_code_otp (user_id, otp_code, email, whatsapp_number, expires_at)
  VALUES (v_user_id, v_otp, p_email, v_whatsapp_clean, NOW() + INTERVAL '5 minutes');

  RETURN json_build_object(
    'success', true,
    'otp', v_otp,
    'whatsapp_number', v_whatsapp_clean,
    'message', 'OTP generated successfully'
  );
END;
$$;


--
-- Name: request_access_code_resend(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_access_code_resend(p_whatsapp_number text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
    v_customer record;
    v_new_access_code text;
    v_hashed_new_code text;
    v_system_user_id uuid := 'e1fdaee2-97f0-4fc1-872f-9d99c6bd684b';
BEGIN
    SELECT id, name, access_code, registration_status, whatsapp_number
    INTO v_customer
    FROM public.customers
    WHERE whatsapp_number = p_whatsapp_number
       OR whatsapp_number = '+' || p_whatsapp_number
       OR regexp_replace(whatsapp_number, '[^0-9]', '', 'g') = regexp_replace(p_whatsapp_number, '[^0-9]', '', 'g')
    LIMIT 1;
    
    IF v_customer.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_found',
            'message', 'No account found with this WhatsApp number.');
    END IF;
    
    IF v_customer.registration_status != 'approved' THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_approved',
            'message', 'Your account is not active. Please register again or contact support.');
    END IF;
    
    -- Generate NEW code (can't retrieve hashed one)
    v_new_access_code := generate_unique_customer_access_code();
    v_hashed_new_code := encode(digest(v_new_access_code::bytea, 'sha256'), 'hex');

    UPDATE public.customers
    SET access_code = v_hashed_new_code,
        access_code_generated_at = now(),
        updated_at = now()
    WHERE id = v_customer.id;

    INSERT INTO public.customer_access_code_history (
        customer_id, old_access_code, new_access_code,
        generated_by, reason, notes
    ) VALUES (
        v_customer.id, v_customer.access_code, v_hashed_new_code,
        v_system_user_id, 'customer_request', 'Customer requested code resend (new code generated)'
    );
    
    RETURN jsonb_build_object(
        'success', true,
        'customer_id', v_customer.id,
        'access_code', v_new_access_code,
        'whatsapp_number', v_customer.whatsapp_number,
        'customer_name', v_customer.name,
        'message', 'A new access code has been sent to your WhatsApp.'
    );
END;
$$;


--
-- Name: request_new_access_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_new_access_code(p_whatsapp_number text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_customer_id uuid;
    v_customer_name text;
    v_current_time timestamp with time zone := now();
    v_request_id uuid;
    result json;
BEGIN
    -- Validate input
    IF p_whatsapp_number IS NULL OR trim(p_whatsapp_number) = '' THEN
        RETURN json_build_object(
            'success', false,
            'error', 'WhatsApp number is required'
        );
    END IF;
    
    -- Clean WhatsApp number (remove non-digits)
    p_whatsapp_number := regexp_replace(p_whatsapp_number, '[^0-9]', '', 'g');
    
    -- Add country code if not present (assume Saudi +966 for 9-digit numbers)
    IF length(p_whatsapp_number) = 9 THEN
        p_whatsapp_number := '966' || p_whatsapp_number;
    END IF;
    
    -- Find customer by WhatsApp number (check both formats: with and without +)
    SELECT 
        id,
        name
    INTO 
        v_customer_id,
        v_customer_name
    FROM public.customers
    WHERE (whatsapp_number = p_whatsapp_number 
           OR whatsapp_number = '+' || p_whatsapp_number
           OR regexp_replace(whatsapp_number, '[^0-9]', '', 'g') = p_whatsapp_number)
    AND registration_status = 'approved'
    LIMIT 1;
    
    -- Check if customer exists
    IF v_customer_id IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'error', 'No approved customer account found with this WhatsApp number. Please contact support if you believe this is an error.'
        );
    END IF;
    
    -- Create recovery request record
    BEGIN
        INSERT INTO public.customer_recovery_requests (
            customer_id,
            whatsapp_number,
            customer_name,
            request_type,
            verification_status
        ) VALUES (
            v_customer_id,
            p_whatsapp_number,
            v_customer_name,
            'account_recovery',
            'pending'
        ) RETURNING id INTO v_request_id;
    EXCEPTION
        WHEN OTHERS THEN
            RETURN json_build_object(
                'success', false,
                'error', 'Failed to create recovery request: ' || SQLERRM
            );
    END;

    -- Create notification for admin users
    BEGIN
        -- Get all admin user IDs (using boolean flags instead of role_type)
        DECLARE
            v_admin_user_ids text[];
        BEGIN
            SELECT array_agg(id::text) INTO v_admin_user_ids
            FROM public.users 
            WHERE (is_admin = true OR is_master_admin = true)
            AND status = 'active';
            
            -- Create notification for specific admin users
            INSERT INTO public.notifications (
                title,
                message,
                type,
                priority,
                target_type,
                target_users,
                status,
                created_by,
                created_by_name,
                created_by_role,
                metadata
            ) VALUES (
                'Account Recovery Request',
                'Customer ' || v_customer_name || ' has requested account recovery via WhatsApp: +' || p_whatsapp_number,
                'info',
                'high',
                'specific_users',
                array_to_json(v_admin_user_ids)::jsonb,
                'published',
                'b658eca1-3cc1-48b2-bd3c-33b81fab5a0f',
                'System',
                'Master Admin',
                json_build_object(
                    'customer_id', v_customer_id,
                    'customer_name', v_customer_name,
                    'whatsapp_number', '+' || p_whatsapp_number,
                    'request_id', v_request_id,
                    'verification_required', true,
                    'requested_at', v_current_time
                )
            );
        END;
    EXCEPTION
        WHEN OTHERS THEN
            -- Don't fail the whole recovery if notification fails
            RAISE NOTICE 'Failed to create notification: %', SQLERRM;
    END;

    result := json_build_object(
        'success', true,
        'message', 'Account recovery request submitted successfully. An administrator will contact you soon for verification.',
        'request_id', v_request_id,
        'customer_name', v_customer_name,
        'whatsapp_number', p_whatsapp_number
    );
    
    RETURN result;
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Failed to process account recovery request: ' || SQLERRM
        );
END;
$$;


--
-- Name: request_server_restart(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_server_restart() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Write a trigger file to the shared volume (PG data dir)
  -- Host path: /opt/supabase/supabase/docker/volumes/db/data/restart_trigger
  -- Container path: /var/lib/postgresql/data/restart_trigger
  COPY (SELECT 'restart_requested_at_' || now()::text) 
    TO '/var/lib/postgresql/data/restart_trigger';
  
  RETURN 'Restart requested successfully. Services will restart within 30 seconds.';
END;
$$;


--
-- Name: reschedule_visit(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reschedule_visit(visit_id uuid, new_date date) RETURNS date
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Update the visit with the new date
    UPDATE vendor_visits 
    SET next_visit_date = new_date, updated_at = NOW()
    WHERE id = visit_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Visit schedule not found with id: %', visit_id;
    END IF;
    
    RETURN new_date;
END;
$$;


--
-- Name: resolve_complete_box_edit(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_complete_box_edit(p_history_id uuid, p_status text, p_after_data jsonb DEFAULT NULL::jsonb, p_pos_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_history RECORD;
    v_approver RECORD;
    v_key text;
    v_before_val jsonb;
    v_after_val jsonb;
    v_diff_rows text := '';
    v_diff_count int := 0;
    v_account_id uuid;
    v_account_email text;
    v_account_name text;
    v_html text;
    v_subject text;
    v_msg_id uuid;
    v_queue_id uuid;
    v_queue_ids jsonb := '[]'::jsonb;
    v_context jsonb;
    v_context_html text;
BEGIN
    IF p_status NOT IN ('saved', 'cancelled') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid status');
    END IF;

    UPDATE public.complete_box_edit_history
    SET status = p_status,
        after_data = CASE WHEN p_status = 'saved' THEN p_after_data ELSE after_data END,
        resolved_at = now()
    WHERE id = p_history_id AND status = 'pending'
    RETURNING * INTO v_history;

    IF v_history IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Edit session not found or already resolved');
    END IF;

    v_context := public.get_complete_box_edit_context(v_history.box_operation_id);
    v_context_html := public.build_complete_box_context_html(v_context, p_pos_number);

    IF p_status = 'saved' THEN
        FOR v_key, v_before_val, v_after_val IN
            SELECT COALESCE(b.key, a.key), b.value, a.value
            FROM jsonb_each(COALESCE(v_history.before_data, '{}'::jsonb)) b
            FULL OUTER JOIN jsonb_each(COALESCE(v_history.after_data, '{}'::jsonb)) a ON b.key = a.key
        LOOP
            IF v_before_val IS DISTINCT FROM v_after_val THEN
                v_diff_count := v_diff_count + 1;
                v_diff_rows := v_diff_rows || format(
                    '<tr><td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;font-weight:600;color:#374151;">%s</td>' ||
                    '<td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;color:#dc2626;">%s</td>' ||
                    '<td style="padding:6px 10px;border-bottom:1px solid #e5e7eb;color:#059669;font-weight:600;">%s</td></tr>',
                    v_key,
                    COALESCE(v_before_val #>> '{}', '—'),
                    COALESCE(v_after_val #>> '{}', '—')
                );
            END IF;
        END LOOP;
    END IF;

    SELECT id, email_address, from_name INTO v_account_id, v_account_email, v_account_name
    FROM public.email_accounts WHERE is_active = true AND send_enabled = true AND default_for_otp = true LIMIT 1;
    IF v_account_id IS NULL THEN
        SELECT id, email_address, from_name INTO v_account_id, v_account_email, v_account_name
        FROM public.email_accounts WHERE is_active = true AND send_enabled = true LIMIT 1;
    END IF;
    IF v_account_id IS NULL THEN
        RETURN jsonb_build_object('success', true, 'warning', 'Resolved, but no email account configured to notify approvers');
    END IF;

    IF p_status = 'saved' THEN
        v_subject := 'Aqura - Box Edit Saved (Box #' || COALESCE(v_context->>'box_number', '?') || ')';
        v_html := '<div style="font-family:Arial,sans-serif;max-width:560px;margin:0 auto;padding:30px;">'
            || '<div style="text-align:center;margin-bottom:20px;"><h2 style="color:#059669;margin:0;">Aqura</h2>'
            || '<p style="color:#6b7280;font-size:14px;">Box Edit Saved / تم حفظ تعديل الصندوق</p></div>'
            || v_context_html
            || CASE WHEN v_diff_count = 0
                THEN '<p style="color:#6b7280;font-size:13px;">The edit was saved, but no field values actually changed. / تم الحفظ دون أي تغيير فعلي في القيم.</p>'
                ELSE '<table style="width:100%;border-collapse:collapse;font-size:13px;">'
                    || '<tr style="background:#f9fafb;"><th style="padding:6px 10px;text-align:left;">Field</th><th style="padding:6px 10px;text-align:left;">Before</th><th style="padding:6px 10px;text-align:left;">After</th></tr>'
                    || v_diff_rows || '</table>'
            END
            || '</div>';
    ELSE
        v_subject := 'Aqura - Box Edit Cancelled (Box #' || COALESCE(v_context->>'box_number', '?') || ')';
        v_html := '<div style="font-family:Arial,sans-serif;max-width:520px;margin:0 auto;padding:30px;">'
            || '<div style="text-align:center;margin-bottom:20px;"><h2 style="color:#6b7280;margin:0;">Aqura</h2>'
            || '<p style="color:#6b7280;font-size:14px;">Box Edit Cancelled / تم إلغاء تعديل الصندوق</p></div>'
            || v_context_html
            || '<p style="color:#374151;font-size:14px;">No changes were made in that session — the edit request was cancelled (or abandoned) before anything was saved.<br>'
            || 'لم يتم إجراء أي تغييرات في تلك الجلسة — تم إلغاء طلب التعديل (أو تركه) قبل حفظ أي شيء.</p>'
            || '</div>';
    END IF;

    FOR v_approver IN
        SELECT DISTINCT r.approver_user_id, e.email, e.name_en
        FROM public.complete_box_edit_otp_requests r
        JOIN public.hr_employee_master e ON e.user_id = r.approver_user_id
        WHERE r.box_operation_id = v_history.box_operation_id
          AND r.created_at >= v_history.created_at - interval '15 minutes'
          AND e.email IS NOT NULL AND e.email <> ''
    LOOP
        INSERT INTO public.email_messages (
            email_account_id, direction, status, subject, text_body, html_body,
            priority, from_address, from_name
        ) VALUES (
            v_account_id, 'outgoing', 'queued', v_subject,
            CASE WHEN p_status = 'saved' THEN 'A box edit was saved. ' || v_diff_count || ' field(s) changed.'
                 ELSE 'A box edit request was cancelled — no changes were made.' END,
            v_html, 'normal', v_account_email, COALESCE(v_account_name, 'Aqura')
        ) RETURNING id INTO v_msg_id;

        INSERT INTO public.email_message_recipients (email_message_id, recipient_type, email_address, display_name)
        VALUES (v_msg_id, 'to', v_approver.email, COALESCE(v_approver.name_en, ''));

        INSERT INTO public.email_queue (queue_type, priority, email_account_id, email_message_id, status, available_at, maximum_attempts)
        VALUES ('normal', 1, v_account_id, v_msg_id, 'pending', now(), 3)
        RETURNING id INTO v_queue_id;

        v_queue_ids := v_queue_ids || to_jsonb(v_queue_id);
    END LOOP;

    RETURN jsonb_build_object('success', true, 'queue_ids', v_queue_ids, 'diff_count', v_diff_count);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: revoke_cam_checker_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_cam_checker_access(p_requesting_user_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_is_master_admin boolean;
    v_has_access boolean;
BEGIN
    SELECT is_master_admin INTO v_is_master_admin FROM public.users WHERE id = p_requesting_user_id;
    SELECT is_enabled INTO v_has_access FROM public.button_permissions
      WHERE user_id = p_requesting_user_id AND button_code = 'SUPPORT_APP_ACCESS';

    IF NOT COALESCE(v_is_master_admin, false) AND NOT COALESCE(v_has_access, false) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Access denied: Master Admin or Support App Access permission required');
    END IF;

    DELETE FROM public.cam_checker_access WHERE user_id = p_user_id;

    RETURN jsonb_build_object('success', true);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: save_action_followup_approver(uuid, text, boolean, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_action_followup_approver(p_user_id uuid, p_user_name text, p_can_approve_po boolean, p_branch_permission text, p_selected_branches jsonb DEFAULT '[]'::jsonb, p_created_by uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result json;
BEGIN
  INSERT INTO action_followup_approvers (user_id, user_name, can_approve_po, branch_permission, selected_branches, created_by)
  VALUES (p_user_id, p_user_name, p_can_approve_po, p_branch_permission, p_selected_branches, COALESCE(p_created_by, auth.uid()))
  ON CONFLICT (user_id) DO UPDATE SET
    user_name = EXCLUDED.user_name,
    can_approve_po = EXCLUDED.can_approve_po,
    branch_permission = EXCLUDED.branch_permission,
    selected_branches = EXCLUDED.selected_branches,
    updated_at = now()
  RETURNING json_build_object('id', id, 'user_id', user_id, 'user_name', user_name,
    'can_approve_po', can_approve_po, 'branch_permission', branch_permission, 'selected_branches', selected_branches)
  INTO v_result;
  RETURN json_build_object('success', true, 'data', v_result);
END;
$$;


--
-- Name: save_email_draft(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_email_draft(p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_id uuid;
  v_account_id uuid;
  v_folder_id uuid;
BEGIN
  v_account_id := (p_data->>'email_account_id')::uuid;
  
  -- Get drafts folder (create if not exists)
  SELECT id INTO v_folder_id FROM public.email_folders
  WHERE email_account_id = v_account_id AND folder_type = 'drafts' LIMIT 1;
  
  IF v_folder_id IS NULL THEN
    INSERT INTO public.email_folders (email_account_id, remote_folder_name, display_name, folder_type)
    VALUES (v_account_id, 'Drafts', 'Drafts', 'drafts')
    RETURNING id INTO v_folder_id;
  END IF;

  IF p_data ? 'id' AND (p_data->>'id') IS NOT NULL THEN
    -- Update existing draft
    v_id := (p_data->>'id')::uuid;
    UPDATE public.email_messages SET
      subject = p_data->>'subject',
      html_body = p_data->>'html_body',
      text_body = p_data->>'text_body',
      body_preview = left(p_data->>'text_body', 200)
    WHERE id = v_id AND is_draft = true;
  ELSE
    -- Create new draft
    INSERT INTO public.email_messages (
      email_account_id, folder_id, direction, status, subject,
      from_name, from_address, html_body, text_body, body_preview,
      is_draft, source_type, created_by_user_id
    ) VALUES (
      v_account_id, v_folder_id, 'outbound', 'draft', p_data->>'subject',
      p_data->>'from_name', p_data->>'from_address',
      p_data->>'html_body', p_data->>'text_body', left(p_data->>'text_body', 200),
      true, 'manual', auth.uid()
    ) RETURNING id INTO v_id;
  END IF;

  -- Upsert recipients
  DELETE FROM public.email_message_recipients WHERE email_message_id = v_id;
  IF p_data ? 'recipients' THEN
    INSERT INTO public.email_message_recipients (email_message_id, recipient_type, email_address, display_name)
    SELECT v_id, r->>'type', r->>'email', r->>'name'
    FROM jsonb_array_elements(p_data->'recipients') r;
  END IF;

  RETURN jsonb_build_object('success', true, 'id', v_id);
END;
$$;


--
-- Name: save_flyer_template_configuration(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_flyer_template_configuration(p_template_id uuid, p_first_page_configuration jsonb, p_sub_page_configurations jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE flyer_templates
  SET first_page_configuration = p_first_page_configuration,
      sub_page_configurations = p_sub_page_configurations
  WHERE id = p_template_id;

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Template not found');
  END IF;

  RETURN json_build_object('success', true);
END;
$$;


--
-- Name: save_hr_employee_rule_periods(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_hr_employee_rule_periods(p_employee_id text, p_rule_type text, p_periods jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_join_date date;
    v_item jsonb;
    v_seq integer := 0;
    v_start_date date;
    v_end_date date;
    v_rule_id bigint;
    v_is_infinite boolean;
    v_duration_years integer;
    v_duration_months integer;
    v_rule public.settlement_rules%ROWTYPE;
    v_active_rule_id bigint;
    v_active_rule public.settlement_rules%ROWTYPE;
    v_total_months integer;
    v_cycle_months integer;
    v_completed_cycles integer;
    v_qualified integer;
BEGIN
    IF p_employee_id IS NULL OR BTRIM(p_employee_id) = '' THEN
        RAISE EXCEPTION 'p_employee_id is required';
    END IF;

    IF p_rule_type NOT IN ('ticket', 'leave_salary') THEN
        RAISE EXCEPTION 'p_rule_type must be ticket or leave_salary';
    END IF;

    SELECT e.join_date INTO v_join_date
    FROM public.hr_employee_master e
    WHERE e.id = p_employee_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Employee % was not found', p_employee_id;
    END IF;

    DELETE FROM public.hr_employee_applicability_rule_periods
    WHERE employee_id = p_employee_id
      AND rule_type = p_rule_type;

    IF p_periods IS NULL OR jsonb_typeof(p_periods) <> 'array' OR jsonb_array_length(p_periods) = 0 THEN
        INSERT INTO public.hr_employee_settlement_applicability (employee_id)
        VALUES (p_employee_id)
        ON CONFLICT (employee_id) DO NOTHING;

        IF p_rule_type = 'ticket' THEN
            UPDATE public.hr_employee_settlement_applicability
            SET
                ticket_rule_id = NULL,
                ticket_rule_enabled = false,
                qualified_ticket_count = NULL
            WHERE employee_id = p_employee_id;
        ELSE
            UPDATE public.hr_employee_settlement_applicability
            SET
                leave_salary_rule_id = NULL,
                leave_salary_rule_enabled = false,
                qualified_leave_days = NULL
            WHERE employee_id = p_employee_id;
        END IF;

        RETURN;
    END IF;

    v_start_date := COALESCE(v_join_date, CURRENT_DATE);

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_periods)
    LOOP
        v_seq := v_seq + 1;
        v_rule_id := NULLIF(v_item ->> 'rule_id', '')::bigint;
        v_is_infinite := COALESCE((v_item ->> 'is_infinite')::boolean, false);
        v_duration_years := GREATEST(0, COALESCE((v_item ->> 'duration_years')::integer, 0));
        v_duration_months := GREATEST(0, COALESCE((v_item ->> 'duration_months')::integer, 0));

        IF v_rule_id IS NULL THEN
            RAISE EXCEPTION 'rule_id is required for each period';
        END IF;

        IF v_is_infinite = false AND v_duration_years = 0 AND v_duration_months = 0 THEN
            RAISE EXCEPTION 'Duration is required for non-infinite periods';
        END IF;

        SELECT * INTO v_rule
        FROM public.settlement_rules r
        WHERE r.id = v_rule_id
            AND r.rule_type = p_rule_type
            AND r.is_active = true;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Active settlement rule % of type % was not found', v_rule_id, p_rule_type;
        END IF;

        IF v_is_infinite THEN
            v_end_date := NULL;
        ELSE
            v_end_date := (
                v_start_date
                + make_interval(years => v_duration_years, months => v_duration_months)
                - interval '1 day'
            )::date;
        END IF;

        INSERT INTO public.hr_employee_applicability_rule_periods (
            employee_id,
            rule_type,
            rule_id,
            sequence_no,
            duration_years,
            duration_months,
            effective_from,
            effective_to,
            is_infinite
        )
        VALUES (
            p_employee_id,
            p_rule_type,
            v_rule_id,
            v_seq,
            v_duration_years,
            v_duration_months,
            v_start_date,
            v_end_date,
            v_is_infinite
        );

        EXIT WHEN v_is_infinite;
        v_start_date := v_end_date + 1;
    END LOOP;

    SELECT p.rule_id
    INTO v_active_rule_id
    FROM public.hr_employee_applicability_rule_periods p
    WHERE p.employee_id = p_employee_id
        AND p.rule_type = p_rule_type
        AND p.effective_from <= CURRENT_DATE
        AND (p.is_infinite = true OR p.effective_to >= CURRENT_DATE)
    ORDER BY p.effective_from DESC
    LIMIT 1;

    IF v_active_rule_id IS NULL THEN
        INSERT INTO public.hr_employee_settlement_applicability (employee_id)
        VALUES (p_employee_id)
        ON CONFLICT (employee_id) DO NOTHING;

        IF p_rule_type = 'ticket' THEN
            UPDATE public.hr_employee_settlement_applicability
            SET
                ticket_rule_id = NULL,
                ticket_rule_enabled = false,
                qualified_ticket_count = NULL
            WHERE employee_id = p_employee_id;
        ELSE
            UPDATE public.hr_employee_settlement_applicability
            SET
                leave_salary_rule_id = NULL,
                leave_salary_rule_enabled = false,
                qualified_leave_days = NULL
            WHERE employee_id = p_employee_id;
        END IF;

        RETURN;
    END IF;

    SELECT * INTO v_active_rule
    FROM public.settlement_rules r
    WHERE r.id = v_active_rule_id;

    IF v_join_date IS NULL OR v_join_date > CURRENT_DATE THEN
        v_completed_cycles := 0;
    ELSE
        v_total_months :=
            (EXTRACT(YEAR FROM age(CURRENT_DATE, v_join_date))::int * 12)
            + EXTRACT(MONTH FROM age(CURRENT_DATE, v_join_date))::int;

        v_cycle_months := GREATEST(
            1,
            COALESCE(v_active_rule.qualification_cycle_value, v_active_rule.qualification_cycle_years, 1)
            * CASE WHEN COALESCE(v_active_rule.qualification_cycle_unit, 'year') = 'month' THEN 1 ELSE 12 END
        );

        v_completed_cycles := GREATEST(0, FLOOR(v_total_months::numeric / v_cycle_months)::int);
    END IF;

    INSERT INTO public.hr_employee_settlement_applicability (employee_id)
    VALUES (p_employee_id)
    ON CONFLICT (employee_id) DO NOTHING;

    IF p_rule_type = 'ticket' THEN
        v_qualified := v_completed_cycles * COALESCE(v_active_rule.ticket_count, 0);
        UPDATE public.hr_employee_settlement_applicability
        SET
            ticket_rule_id = v_active_rule.id,
            ticket_rule_enabled = true,
            qualified_ticket_count = v_qualified
        WHERE employee_id = p_employee_id;
    ELSE
        v_qualified := v_completed_cycles * COALESCE(v_active_rule.entitled_days, 0);
        UPDATE public.hr_employee_settlement_applicability
        SET
            leave_salary_rule_id = v_active_rule.id,
            leave_salary_rule_enabled = true,
            qualified_leave_days = v_qualified
        WHERE employee_id = p_employee_id;
    END IF;
END;
$$;


--
-- Name: save_internal_expense_approver(uuid, text, boolean, boolean, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_internal_expense_approver(p_user_id uuid, p_user_name text, p_can_send_request boolean, p_can_approve_request boolean, p_branch_permission text, p_selected_branches jsonb DEFAULT '[]'::jsonb, p_created_by uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result json;
BEGIN
    IF p_branch_permission NOT IN ('all', 'selected') THEN
        RETURN json_build_object('success', false, 'error', 'Invalid branch_permission');
    END IF;

    INSERT INTO internal_expense_approvers (
        user_id, user_name, can_send_request, can_approve_request,
        branch_permission, selected_branches, created_by
    )
    VALUES (
        p_user_id, p_user_name, p_can_send_request, p_can_approve_request,
        p_branch_permission, p_selected_branches, COALESCE(p_created_by, auth.uid())
    )
    ON CONFLICT (user_id) DO UPDATE SET
        user_name = EXCLUDED.user_name,
        can_send_request = EXCLUDED.can_send_request,
        can_approve_request = EXCLUDED.can_approve_request,
        branch_permission = EXCLUDED.branch_permission,
        selected_branches = EXCLUDED.selected_branches,
        updated_at = now()
    RETURNING json_build_object(
        'id', id, 'user_id', user_id, 'user_name', user_name,
        'can_send_request', can_send_request, 'can_approve_request', can_approve_request,
        'branch_permission', branch_permission, 'selected_branches', selected_branches
    ) INTO v_result;

    RETURN json_build_object('success', true, 'data', v_result);
END;
$$;


--
-- Name: save_push_subscription_scoped(uuid, text, jsonb, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_push_subscription_scoped(p_user_id uuid, p_endpoint text, p_subscription jsonb, p_user_agent text DEFAULT NULL::text, p_interface_type text DEFAULT NULL::text, p_reactivate boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row_id uuid;
  v_manually_disabled boolean;
BEGIN
  IF p_user_id IS NULL OR p_endpoint IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid arguments');
  END IF;

  IF p_interface_type IS NOT NULL AND p_interface_type NOT IN ('mobile', 'desktop', 'cashier') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid interface_type');
  END IF;

  -- p_reactivate: explicit user action (re-enabling the toggle on this
  -- device) clears a prior manual opt-out. Without it, manually_disabled
  -- sticks across re-registrations (e.g. a silent auto-subscribe on login).
  INSERT INTO public.push_subscriptions
    (user_id, endpoint, subscription, user_agent, interface_type, is_active, manually_disabled, updated_at)
  VALUES
    (p_user_id, p_endpoint, p_subscription, p_user_agent, p_interface_type, true, false, now())
  ON CONFLICT (endpoint) DO UPDATE
    SET user_id           = EXCLUDED.user_id,
        subscription      = EXCLUDED.subscription,
        user_agent        = EXCLUDED.user_agent,
        interface_type    = EXCLUDED.interface_type,
        manually_disabled = CASE WHEN p_reactivate THEN false ELSE push_subscriptions.manually_disabled END,
        is_active         = CASE WHEN p_reactivate THEN true ELSE NOT push_subscriptions.manually_disabled END,
        updated_at        = now()
  RETURNING id, manually_disabled INTO v_row_id, v_manually_disabled;

  -- Latest-device-only: deactivate every other subscription for this
  -- user + interface (applies to Master Admin too — no exemption).
  IF NOT v_manually_disabled AND p_interface_type IS NOT NULL THEN
    UPDATE public.push_subscriptions
       SET is_active = false,
           updated_at = now()
     WHERE user_id = p_user_id
       AND interface_type = p_interface_type
       AND id <> v_row_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'id', v_row_id, 'active', NOT v_manually_disabled);
END;
$$;


--
-- Name: FUNCTION save_push_subscription_scoped(p_user_id uuid, p_endpoint text, p_subscription jsonb, p_user_agent text, p_interface_type text, p_reactivate boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.save_push_subscription_scoped(p_user_id uuid, p_endpoint text, p_subscription jsonb, p_user_agent text, p_interface_type text, p_reactivate boolean) IS 'Upserts a push subscription by endpoint and makes it the sole active subscription for (user_id, interface_type). Respects manually_disabled: a device the user explicitly opted out of stays inactive even when re-registered.';


--
-- Name: search_tasks(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_tasks(search_query text, user_id_param text DEFAULT NULL::text, limit_param integer DEFAULT 50, offset_param integer DEFAULT 0) RETURNS TABLE(id uuid, title text, description text, require_task_finished boolean, require_photo_upload boolean, require_erp_reference boolean, can_escalate boolean, can_reassign boolean, created_by text, created_by_name text, status text, priority text, created_at timestamp with time zone, updated_at timestamp with time zone, due_date date, due_time time without time zone, rank real)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        t.id, t.title, t.description, t.require_task_finished, t.require_photo_upload, t.require_erp_reference,
        t.can_escalate, t.can_reassign, t.created_by, t.created_by_name, t.status, t.priority,
        t.created_at, t.updated_at, t.due_date, t.due_time,
        ts_rank(t.search_vector, plainto_tsquery('english', search_query)) as rank
    FROM public.tasks t
    WHERE t.deleted_at IS NULL
    AND (
        search_query IS NULL 
        OR search_query = '' 
        OR t.search_vector @@ plainto_tsquery('english', search_query)
        OR t.title ILIKE '%' || search_query || '%'
        OR t.description ILIKE '%' || search_query || '%'
    )
    ORDER BY 
        CASE WHEN search_query IS NOT NULL AND search_query != '' 
        THEN ts_rank(t.search_vector, plainto_tsquery('english', search_query)) 
        ELSE 0 END DESC,
        t.created_at DESC
    LIMIT limit_param OFFSET offset_param;
END;
$$;


--
-- Name: search_tasks(text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_tasks(search_term text DEFAULT NULL::text, task_status text DEFAULT NULL::text, assigned_user_id uuid DEFAULT NULL::uuid, created_by_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, title character varying, description text, status character varying, priority character varying, assigned_to uuid, created_by uuid, created_at timestamp with time zone, updated_at timestamp with time zone, due_date date, assignee_name character varying, creator_name character varying)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        t.id,
        t.title,
        t.description,
        t.status,
        t.priority,
        ta.assigned_to,
        t.created_by,
        t.created_at,
        t.updated_at,
        t.due_date,
        COALESCE(u_assignee.username, 'Unassigned')::VARCHAR as assignee_name,
        COALESCE(u_creator.username, 'Unknown')::VARCHAR as creator_name
    FROM tasks t
    LEFT JOIN task_assignments ta ON t.id = ta.task_id
    LEFT JOIN users u_assignee ON ta.assigned_to = u_assignee.id
    LEFT JOIN users u_creator ON t.created_by = u_creator.id
    WHERE (search_term IS NULL OR t.title ILIKE '%' || search_term || '%' OR t.description ILIKE '%' || search_term || '%')
      AND (task_status IS NULL OR t.status = task_status)
      AND (assigned_user_id IS NULL OR ta.assigned_to = assigned_user_id)
      AND (created_by_user_id IS NULL OR t.created_by = created_by_user_id)
      AND t.deleted_at IS NULL
    ORDER BY t.created_at DESC;
END;
$$;


--
-- Name: select_random_product(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.select_random_product(p_campaign_id uuid) RETURNS TABLE(id uuid, product_name_en character varying, product_name_ar character varying, product_image_url text, original_price numeric, offer_price numeric, special_barcode character varying, stock_remaining integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    p.id,
    p.product_name_en,
    p.product_name_ar,
    p.product_image_url,
    p.original_price,
    p.offer_price,
    p.special_barcode,
    p.stock_remaining
  FROM coupon_products p
  WHERE p.campaign_id = p_campaign_id
    AND p.is_active = true
    AND p.stock_remaining > 0
    AND p.deleted_at IS NULL
  ORDER BY RANDOM()
  LIMIT 1
  FOR UPDATE SKIP LOCKED;
END;
$$;


--
-- Name: send_complete_box_edit_otp(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_complete_box_edit_otp(p_box_operation_id uuid, p_requested_by uuid, p_pos_number text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_approver RECORD;
    v_otp text;
    v_otp_hash text;
    v_masked text;
    v_expires_at timestamptz := now() + interval '5 minutes';
    v_account_id uuid;
    v_account_email text;
    v_account_name text;
    v_html text;
    v_msg_id uuid;
    v_queue_id uuid;
    v_queue_ids jsonb := '[]'::jsonb;
    v_sent_count int := 0;
    v_context jsonb;
    v_context_html text;
BEGIN
    v_context := public.get_complete_box_edit_context(p_box_operation_id);
    v_context_html := public.build_complete_box_context_html(v_context, p_pos_number);

    SELECT id, email_address, from_name INTO v_account_id, v_account_email, v_account_name
    FROM public.email_accounts
    WHERE is_active = true AND send_enabled = true AND default_for_otp = true
    LIMIT 1;

    IF v_account_id IS NULL THEN
        SELECT id, email_address, from_name INTO v_account_id, v_account_email, v_account_name
        FROM public.email_accounts
        WHERE is_active = true AND send_enabled = true
        LIMIT 1;
    END IF;

    IF v_account_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'No email account configured for sending');
    END IF;

    -- Invalidate any still-pending OTPs from a previous request for this box
    UPDATE public.complete_box_edit_otp_requests
    SET is_used = true, used_at = now()
    WHERE box_operation_id = p_box_operation_id AND is_used = false;

    FOR v_approver IN
        SELECT ca.user_id, e.email, e.name_en
        FROM public.complete_box_approvers ca
        JOIN public.hr_employee_master e ON e.user_id = ca.user_id
        WHERE ca.is_active = true AND e.email IS NOT NULL AND e.email <> ''
    LOOP
        v_otp := lpad(floor(random() * 1000000)::int::text, 6, '0');
        v_otp_hash := extensions.crypt(v_otp, extensions.gen_salt('bf'));
        v_masked := substring(v_approver.email from 1 for 3) || '****@' || split_part(v_approver.email, '@', 2);

        INSERT INTO public.complete_box_edit_otp_requests (box_operation_id, approver_user_id, otp_hash, masked_email, expires_at)
        VALUES (p_box_operation_id, v_approver.user_id, v_otp_hash, v_masked, v_expires_at);

        v_html := '<div style="font-family:Arial,sans-serif;max-width:520px;margin:0 auto;padding:30px;">'
            || '<div style="text-align:center;margin-bottom:24px;"><h2 style="color:#059669;margin:0;">Aqura</h2>'
            || '<p style="color:#6b7280;font-size:14px;">Complete Box Edit Approval / موافقة تعديل صندوق الإغلاق</p></div>'
            || '<p style="color:#374151;font-size:14px;">A request was made to edit a closing box record.<br>'
            || 'تم تقديم طلب لتعديل سجل إغلاق صندوق.</p>'
            || v_context_html
            || '<div style="background:#f0fdf4;border:2px solid #059669;border-radius:12px;padding:24px;text-align:center;margin-bottom:20px;">'
            || '<p style="color:#374151;font-size:14px;margin:0 0 8px;">Approval code / رمز الموافقة:</p>'
            || '<div style="font-size:36px;font-weight:700;letter-spacing:8px;color:#059669;margin:12px 0;">' || v_otp || '</div>'
            || '<p style="color:#6b7280;font-size:12px;margin:8px 0 0;">Expires in 5 minutes / تنتهي الصلاحية خلال 5 دقائق</p></div>'
            || '<p style="color:#9ca3af;font-size:11px;text-align:center;">Only share this code with the person who should be allowed to make this edit.<br>'
            || 'لا تشارك هذا الرمز إلا مع الشخص المسموح له بإجراء هذا التعديل.</p>'
            || '</div>';

        INSERT INTO public.email_messages (
            email_account_id, direction, status, subject, text_body, html_body,
            priority, from_address, from_name
        ) VALUES (
            v_account_id, 'outgoing', 'queued',
            'Aqura - Box Edit Approval Code (Box #' || COALESCE(v_context->>'box_number', '?') || ')',
            'Approval code: ' || v_otp || E'\nExpires in 5 minutes.\nOnly share this code with the person who should be allowed to make this edit.',
            v_html, 'critical', v_account_email, COALESCE(v_account_name, 'Aqura')
        ) RETURNING id INTO v_msg_id;

        INSERT INTO public.email_message_recipients (email_message_id, recipient_type, email_address, display_name)
        VALUES (v_msg_id, 'to', v_approver.email, COALESCE(v_approver.name_en, ''));

        INSERT INTO public.email_queue (queue_type, priority, email_account_id, email_message_id, status, available_at, maximum_attempts)
        VALUES ('normal', 1, v_account_id, v_msg_id, 'pending', now(), 3)
        RETURNING id INTO v_queue_id;

        v_queue_ids := v_queue_ids || to_jsonb(v_queue_id);
        v_sent_count := v_sent_count + 1;
    END LOOP;

    IF v_sent_count = 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'No active approvers with an email on file');
    END IF;

    RETURN jsonb_build_object('success', true, 'queue_ids', v_queue_ids, 'approver_count', v_sent_count, 'expires_in_seconds', 300);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: send_order_notification(uuid, text, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_order_notification(p_order_id uuid, p_title text, p_message text, p_type text DEFAULT 'info'::text, p_priority text DEFAULT 'medium'::text, p_performed_by uuid DEFAULT NULL::uuid, p_target_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_notification_id UUID;
    v_admin_user RECORD;
    v_title_en TEXT;
    v_title_ar TEXT;
    v_message_en TEXT;
    v_message_ar TEXT;
BEGIN
    IF p_title LIKE '%|||%' THEN
        v_title_en := split_part(p_title, '|||', 1);
        v_title_ar := split_part(p_title, '|||', 2);
    END IF;
    IF p_message LIKE '%|||%' THEN
        v_message_en := split_part(p_message, '|||', 1);
        v_message_ar := split_part(p_message, '|||', 2);
    END IF;

    INSERT INTO notifications (
        title, message, title_en, title_ar, message_en, message_ar, type, created_by, created_by_name, created_by_role,
        priority, status, target_type, target_roles, sent_at
    ) VALUES (
        p_title, p_message, v_title_en, v_title_ar, v_message_en, v_message_ar, p_type,
        COALESCE(p_performed_by::text, 'system'), 'System', 'System',
        p_priority, 'published',
        CASE WHEN p_target_user_id IS NOT NULL THEN 'specific_users' ELSE 'role_based' END,
        to_jsonb(ARRAY['Admin', 'Master Admin']),
        NOW()
    ) RETURNING id INTO v_notification_id;

    -- If targeting a specific user
    IF p_target_user_id IS NOT NULL THEN
        INSERT INTO notification_recipients (notification_id, user_id, role, is_read, delivery_status)
        VALUES (v_notification_id, p_target_user_id, 'User', FALSE, 'delivered');
    END IF;

    -- Always notify admins
    FOR v_admin_user IN
        SELECT id,
               CASE WHEN is_master_admin THEN 'Master Admin'
                    WHEN is_admin THEN 'Admin'
                    ELSE 'User' END as role_type
        FROM users
        WHERE status = 'active' AND (is_admin = true OR is_master_admin = true)
        AND id <> COALESCE(p_target_user_id, '00000000-0000-0000-0000-000000000000'::uuid)
    LOOP
        INSERT INTO notification_recipients (notification_id, user_id, role, is_read, delivery_status)
        VALUES (v_notification_id, v_admin_user.id, v_admin_user.role_type, FALSE, 'delivered');
    END LOOP;

    RETURN v_notification_id;
END;
$$;


--
-- Name: set_active_sidebar_animation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_active_sidebar_animation(animation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    UPDATE public.sidebar_animations SET is_active = false WHERE is_active = true;
    UPDATE public.sidebar_animations SET is_active = true WHERE id = animation_id;
END;
$$;


--
