CREATE FUNCTION public.trigger_log_order_offer_usage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Update offer_usage_logs with order_id for items that have offers
    UPDATE offer_usage_logs
    SET order_id = NEW.order_id
    WHERE offer_id IN (
        SELECT offer_id
        FROM order_items
        WHERE order_id = NEW.order_id
        AND has_offer = TRUE
        AND offer_id IS NOT NULL
    )
    AND order_id IS NULL
    AND customer_id = (
        SELECT customer_id FROM orders WHERE id = NEW.order_id
    )
    AND used_at >= (
        SELECT created_at FROM orders WHERE id = NEW.order_id
    ) - INTERVAL '1 minute';
    
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION trigger_log_order_offer_usage(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trigger_log_order_offer_usage() IS 'Links offer usage logs to orders for tracking';


--
-- Name: trigger_notify_new_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_notify_new_order() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_customer_name VARCHAR(255);
    v_notification_id UUID;
    v_admin_user RECORD;
    v_title TEXT;
    v_message TEXT;
    v_title_en TEXT;
    v_title_ar TEXT;
    v_message_en TEXT;
    v_message_ar TEXT;
    v_fulfillment_label_en TEXT;
    v_fulfillment_label_ar TEXT;
    -- Push notification vars
    v_push_title TEXT;
    v_push_body TEXT;
    v_service_role_key TEXT;
    v_supabase_url TEXT;
    v_request_id BIGINT;
    v_user_ids JSONB;
BEGIN
    -- Get customer name
    SELECT name INTO v_customer_name
    FROM customers
    WHERE id = NEW.customer_id;

    -- Determine fulfillment labels
    IF NEW.fulfillment_method = 'pickup' THEN
        v_fulfillment_label_en := 'Pickup';
        v_fulfillment_label_ar := 'استلام';
    ELSE
        v_fulfillment_label_en := 'Delivery';
        v_fulfillment_label_ar := 'توصيل';
    END IF;

    -- Bilingual title and message for in-app notification
    v_title_en := 'New Order #' || NEW.order_number || ' (' || v_fulfillment_label_en || ')';
    v_title_ar := 'طلب جديد #' || NEW.order_number || ' (' || v_fulfillment_label_ar || ')';
    v_title := v_title_en || '|||' || v_title_ar;

    v_message_en := 'Order #' || NEW.order_number || ' from ' || COALESCE(v_customer_name, NEW.customer_name) || ' - Total: ' || NEW.total_amount || ' SAR - ' || v_fulfillment_label_en;
    v_message_ar := 'طلب #' || NEW.order_number || ' من ' || COALESCE(v_customer_name, NEW.customer_name) || ' - الإجمالي: ' || NEW.total_amount || ' ريال - ' || v_fulfillment_label_ar;
    v_message := v_message_en || '|||' || v_message_ar;

    -- Create the in-app notification
    INSERT INTO notifications (
        title, message, title_en, title_ar, message_en, message_ar, type, created_by, created_by_name, created_by_role,
        priority, status, target_type, target_roles, sent_at
    ) VALUES (
        v_title, v_message, v_title_en, v_title_ar, v_message_en, v_message_ar, 'order_new',
        NEW.customer_id::text,
        COALESCE(v_customer_name, NEW.customer_name),
        'Customer',
        'high', 'published', 'role_based',
        to_jsonb(ARRAY['Admin', 'Master Admin']),
        NOW()
    ) RETURNING id INTO v_notification_id;

    -- Create notification_recipients for all Admin and Master Admin users
    FOR v_admin_user IN
        SELECT id,
               CASE WHEN is_master_admin THEN 'Master Admin'
                    WHEN is_admin THEN 'Admin'
                    ELSE 'User' END as role_type
        FROM users
        WHERE status = 'active' AND (is_admin = true OR is_master_admin = true)
    LOOP
        INSERT INTO notification_recipients (
            notification_id, user_id, role, is_read, delivery_status
        ) VALUES (
            v_notification_id, v_admin_user.id, v_admin_user.role_type, FALSE, 'delivered'
        );
    END LOOP;

    -- ===== PUSH NOTIFICATION TO BRANCH DELIVERY RECEIVERS =====
    -- Collect user_ids of branch default delivery receivers
    SELECT jsonb_agg(to_jsonb(dr.user_id::text))
    INTO v_user_ids
    FROM branch_default_delivery_receivers dr
    WHERE dr.branch_id = NEW.branch_id AND dr.is_active = true;

    -- If no branch receivers, skip push
    IF v_user_ids IS NULL OR jsonb_array_length(v_user_ids) = 0 THEN
        RAISE LOG 'No branch delivery receivers for branch %, skipping push for order %', NEW.branch_id, NEW.order_number;
        RETURN NEW;
    END IF;

    -- Build push content (Arabic primary) -- unchanged
    v_push_title := 'طلب جديد  #' || NEW.order_number;
    v_push_body := 'طلب جديد من ' || COALESCE(v_customer_name, NEW.customer_name) || ' - ' || NEW.total_amount || ' ريال - ' || v_fulfillment_label_ar
        || chr(10) || 'New order from ' || COALESCE(v_customer_name, NEW.customer_name) || ' - ' || NEW.total_amount || ' SAR - ' || v_fulfillment_label_en;

        -- Resolve Supabase URL: vault -> current_setting -> internal docker default
    SELECT decrypted_secret INTO v_supabase_url
    FROM vault.decrypted_secrets WHERE name = 'supabase_url' LIMIT 1;

    IF v_supabase_url IS NULL THEN
        BEGIN
            v_supabase_url := current_setting('app.supabase_url', true);
        EXCEPTION WHEN OTHERS THEN
            v_supabase_url := NULL;
        END;
    END IF;

    IF v_supabase_url IS NULL THEN
        v_supabase_url := 'http://supabase-kong:8000';
    END IF;

    -- Resolve service role key: vault -> current_setting -> skip (no hardcoded fallback)
    SELECT decrypted_secret INTO v_service_role_key
    FROM vault.decrypted_secrets
    WHERE name = 'service_role_key'
    LIMIT 1;

    IF v_service_role_key IS NULL THEN
        BEGIN
            v_service_role_key := current_setting('supabase.service_role_key', true);
        EXCEPTION WHEN OTHERS THEN
            v_service_role_key := NULL;
        END;
    END IF;

    IF v_service_role_key IS NULL THEN
        RAISE WARNING 'trigger_notify_new_order: service_role_key not found in vault; skipping push';
        RETURN NEW;
    END IF;

    -- Send push via edge function to branch receivers only
    SELECT net.http_post(
        url := v_supabase_url || '/functions/v1/send-push-notification',
        headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer ' || v_service_role_key
        ),
        body := jsonb_build_object(
            'notificationId', v_notification_id::text,
            'userIds', v_user_ids,
            'payload', jsonb_build_object(
                'title', v_push_title,
                'body', v_push_body,
                'url', '/desktop',
                'type', 'order_new',
                'icon', '/icons/icon-192x192.png',
                'badge', '/icons/icon-72x72.png'
            )
        )
    ) INTO v_request_id;

    RAISE LOG 'Staff push for new order % sent to % branch receivers, request_id: %',
        NEW.order_number, jsonb_array_length(v_user_ids), v_request_id;

    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION trigger_notify_new_order(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trigger_notify_new_order() IS 'Notifies all Admin and Master Admin users when a new order is placed';


--
-- Name: trigger_order_status_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_order_status_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Only log if status actually changed
    IF OLD.order_status IS DISTINCT FROM NEW.order_status THEN
        INSERT INTO order_audit_logs (
            order_id,
            action_type,
            from_status,
            to_status,
            performed_by,
            notes
        ) VALUES (
            NEW.id,
            'status_changed',
            OLD.order_status,
            NEW.order_status,
            NEW.updated_by,
            'Status changed from ' || OLD.order_status || ' to ' || NEW.order_status
        );
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION trigger_order_status_audit(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trigger_order_status_audit() IS 'Automatically creates audit log when order status changes';


--
-- Name: trigger_process_fingerprints(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_process_fingerprints() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_last_called TIMESTAMPTZ;
    v_supabase_url TEXT;
    v_service_key  TEXT;
    v_request_id   BIGINT;
BEGIN
    -- Read env-like values stored as Supabase secrets via vault or app.settings
    -- These must be set via: ALTER DATABASE postgres SET app.supabase_url = '...';
    --                        ALTER DATABASE postgres SET app.service_role_key = '...';
    BEGIN
        v_supabase_url := current_setting('app.supabase_url', true);
        v_service_key  := current_setting('app.service_role_key', true);
    EXCEPTION WHEN OTHERS THEN
        -- Settings not configured — skip silently
        RETURN NEW;
    END;

    IF v_supabase_url IS NULL OR v_supabase_url = '' THEN
        RETURN NEW;
    END IF;

    -- Debounce: skip if called within the last 30 seconds
    SELECT last_called_at INTO v_last_called
    FROM public.edge_function_trigger_log
    WHERE function_name = 'process-fingerprints';

    IF v_last_called IS NOT NULL AND
       (NOW() - v_last_called) < INTERVAL '30 seconds' THEN
        -- Too soon — skip this call, the recent one covers it
        RETURN NEW;
    END IF;

    -- Update (or insert) the debounce timestamp
    INSERT INTO public.edge_function_trigger_log (function_name, last_called_at)
    VALUES ('process-fingerprints', NOW())
    ON CONFLICT (function_name)
    DO UPDATE SET last_called_at = NOW();

    -- Fire async HTTP call to the process-fingerprints edge function
    SELECT net.http_post(
        url     := v_supabase_url || '/functions/v1/process-fingerprints',
        headers := jsonb_build_object(
            'Content-Type',  'application/json',
            'Authorization', 'Bearer ' || v_service_key
        ),
        body    := '{"rollingDays":3}'::jsonb
    ) INTO v_request_id;

    RETURN NEW;
END;
$$;


--
-- Name: trigger_sync_erp_reference_on_task_completion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_sync_erp_reference_on_task_completion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    update_count INTEGER := 0;
BEGIN
    -- Only process if ERP reference is provided and completed
    IF NEW.erp_reference_completed = true 
       AND NEW.erp_reference_number IS NOT NULL 
       AND TRIM(NEW.erp_reference_number) != '' THEN
        
        -- Check if this is a regular task completion (not receiving task)
        -- Regular tasks (like payment tasks) don't need this trigger
        -- This trigger only handles receiving_tasks (inventory manager tasks)
        
        -- Since receiving_tasks is a separate system with its own completion logic,
        -- and regular tasks/task_assignments are separate,
        -- we don't need to do anything here for regular task completions.
        
        -- The receiving tasks have their own completion system via:
        -- complete_receiving_task() function which is called directly
        
        RAISE NOTICE 'ℹ️  Task completion with ERP reference: Task ID %, ERP: %', 
                     NEW.task_id, 
                     TRIM(NEW.erp_reference_number);
        
        -- Note: For payment tasks, the ERP reference sync is handled in the application code
        -- (TaskCompletionModal.svelte) which updates vendor_payment_schedule.payment_reference
        
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: trigger_update_order_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_update_order_totals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Recalculate total items and quantities when order_items change
    UPDATE orders
    SET total_items = (
            SELECT COUNT(*)
            FROM order_items
            WHERE order_id = COALESCE(NEW.order_id, OLD.order_id)
        ),
        total_quantity = (
            SELECT COALESCE(SUM(quantity), 0)
            FROM order_items
            WHERE order_id = COALESCE(NEW.order_id, OLD.order_id)
        ),
        updated_at = NOW()
    WHERE id = COALESCE(NEW.order_id, OLD.order_id);
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: FUNCTION trigger_update_order_totals(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trigger_update_order_totals() IS 'Recalculates order item counts when order_items change';


--
-- Name: unclaim_products(text, text[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unclaim_products(p_employee_id text, p_barcodes text[], p_branch_id integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    UPDATE erp_synced_products
    SET managed_by = (
        SELECT COALESCE(jsonb_agg(elem), '[]'::JSONB)
        FROM jsonb_array_elements(managed_by) AS elem
        WHERE NOT (
            elem->>'employee_id' = p_employee_id
            AND (p_branch_id IS NULL OR (elem->>'branch_id')::INTEGER = p_branch_id)
        )
    )
    WHERE barcode = ANY(p_barcodes)
      AND managed_by IS NOT NULL;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


