--
-- Name: update_email_template(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_email_template(p_id uuid, p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- Save version before update
  INSERT INTO public.email_template_versions (email_template_id, version_number, subject_template, html_body_template, text_body_template, change_note, created_by)
  SELECT id, version, subject_template, html_body_template, text_body_template, 'Auto-saved before update', auth.uid()
  FROM public.email_templates WHERE id = p_id;

  UPDATE public.email_templates SET
    template_name = coalesce(p_data->>'template_name', template_name),
    template_code = coalesce(p_data->>'template_code', template_code),
    category = coalesce(p_data->>'category', category),
    subject_template = coalesce(p_data->>'subject_template', subject_template),
    html_body_template = coalesce(p_data->>'html_body_template', html_body_template),
    text_body_template = coalesce(p_data->>'text_body_template', text_body_template),
    available_placeholders_json = CASE WHEN p_data ? 'available_placeholders_json' THEN p_data->'available_placeholders_json' ELSE available_placeholders_json END,
    default_signature_id = CASE WHEN p_data ? 'default_signature_id' THEN (p_data->>'default_signature_id')::uuid ELSE default_signature_id END,
    version = version + 1,
    updated_by = auth.uid()
  WHERE id = p_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: update_employee_master_basic(text, text, text, integer, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_employee_master_basic(p_id text, p_name_en text DEFAULT NULL::text, p_name_ar text DEFAULT NULL::text, p_current_branch_id integer DEFAULT NULL::integer, p_current_position_id uuid DEFAULT NULL::uuid, p_whatsapp_number text DEFAULT NULL::text, p_email text DEFAULT NULL::text) RETURNS TABLE(id text, name_en character varying, name_ar character varying, current_branch_id integer, current_position_id uuid, whatsapp_number text, email text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF COALESCE(trim(p_id), '') = '' THEN
    RAISE EXCEPTION 'Employee ID is required';
  END IF;

  IF p_current_branch_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM branches b WHERE b.id = p_current_branch_id) THEN
      RAISE EXCEPTION 'Branch not found';
    END IF;
  END IF;

  IF p_current_position_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM hr_positions pos WHERE pos.id = p_current_position_id) THEN
      RAISE EXCEPTION 'Position not found';
    END IF;
  END IF;

  RETURN QUERY
  UPDATE hr_employee_master e
  SET
    name_en = COALESCE(NULLIF(trim(p_name_en), ''), e.name_en),
    name_ar = COALESCE(NULLIF(trim(p_name_ar), ''), e.name_ar),
    current_branch_id = COALESCE(p_current_branch_id, e.current_branch_id),
    current_position_id = CASE
      WHEN p_current_position_id IS NOT NULL THEN p_current_position_id
      ELSE e.current_position_id
    END,
    whatsapp_number = CASE
      WHEN p_whatsapp_number IS NOT NULL THEN NULLIF(trim(p_whatsapp_number), '')
      ELSE e.whatsapp_number
    END,
    email = CASE
      WHEN p_email IS NOT NULL THEN NULLIF(trim(p_email), '')
      ELSE e.email
    END,
    updated_at = NOW()
  WHERE e.id = p_id
  RETURNING
    e.id,
    e.name_en,
    e.name_ar,
    e.current_branch_id,
    e.current_position_id,
    e.whatsapp_number,
    e.email;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Employee not found';
  END IF;
END;
$$;


