--
-- Name: update_login_home_section(text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_login_home_section(p_section text, p_data jsonb, p_updated_by uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql
    AS $_$
DECLARE
  v_result json;
BEGIN
  IF p_section NOT IN (
    'nav_button', 'headline', 'tagline', 'contact_button',
    'signup_button', 'logo', 'badges'
  ) THEN
    RAISE EXCEPTION 'Invalid section: %', p_section;
  END IF;

  IF p_section = 'badges' AND jsonb_array_length(p_data) > 5 THEN
    RAISE EXCEPTION 'badges cannot exceed 5 items';
  END IF;

  IF EXISTS (SELECT 1 FROM public.login_home) THEN
    EXECUTE format(
      'UPDATE public.login_home SET %I = $1, updated_by = $2, updated_at = now()',
      p_section
    ) USING p_data, p_updated_by;
  ELSE
    EXECUTE format(
      'INSERT INTO public.login_home (%I, updated_by) VALUES ($1, $2)',
      p_section
    ) USING p_data, p_updated_by;
  END IF;

  SELECT row_to_json(t) INTO v_result
  FROM public.login_home t
  LIMIT 1;

  RETURN v_result;
END;
$_$;


--
-- Name: update_login_layout_section(text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_login_layout_section(p_section text, p_data jsonb, p_updated_by uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
BEGIN
        IF p_section NOT IN ('topbar', 'about', 'contact', 'footer', 'main_layout', 'home_content', 'services', 'why_choose', 'gallery', 'offers', 'careers', 'privacy_policy', 'company') THEN
                RAISE EXCEPTION 'Invalid section: %', p_section;
        END IF;

        IF EXISTS (SELECT 1 FROM public.login_layout LIMIT 1) THEN
                EXECUTE format(
                        'UPDATE public.login_layout SET %I = $1, updated_by = $2, updated_at = now() WHERE true',
                        p_section
                ) USING p_data, p_updated_by;
        ELSE
                EXECUTE format(
                        'INSERT INTO public.login_layout (%I, updated_by) VALUES ($1, $2)',
                        p_section
                ) USING p_data, p_updated_by;
        END IF;
END;
$_$;


