      hr_positions.position_title_en,
      hr_positions.position_title_ar,
      hr_positions.department_id,
      hr_positions.level_id,
      hr_positions.is_active,
      hr_positions.created_at;
  ELSE
    RETURN QUERY
    UPDATE hr_positions
    SET
      position_title_en = trim(p_title_en),
      position_title_ar = trim(p_title_ar),
      department_id = p_department_id,
      level_id = p_level_id,
      is_active = COALESCE(p_is_active, true)
    WHERE hr_positions.id = p_id
    RETURNING
      hr_positions.id,
      hr_positions.position_title_en,
      hr_positions.position_title_ar,
      hr_positions.department_id,
      hr_positions.level_id,
      hr_positions.is_active,
      hr_positions.created_at;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Position not found';
    END IF;
  END IF;
END;
$$;


--
-- Name: upsert_receiving_records_permission(uuid, uuid, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_receiving_records_permission(p_requesting_user_id uuid, p_target_user_id uuid, p_can_edit_erp_reference boolean, p_can_edit_record boolean, p_can_delete boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_is_master_admin boolean;
BEGIN
    SELECT is_master_admin INTO v_is_master_admin
    FROM public.users
    WHERE id = p_requesting_user_id;

    IF NOT COALESCE(v_is_master_admin, false) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Access denied: Master Admin only');
    END IF;

    INSERT INTO public.receiving_records_permissions
        (user_id, can_edit_erp_reference, can_edit_record, can_delete, granted_by, updated_at)
    VALUES
        (p_target_user_id, p_can_edit_erp_reference, p_can_edit_record, p_can_delete, p_requesting_user_id, now())
    ON CONFLICT (user_id)
    DO UPDATE SET
        can_edit_erp_reference = excluded.can_edit_erp_reference,
        can_edit_record = excluded.can_edit_record,
        can_delete = excluded.can_delete,
        granted_by = excluded.granted_by,
        updated_at = now();

    RETURN jsonb_build_object('success', true);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: FUNCTION upsert_receiving_records_permission(p_requesting_user_id uuid, p_target_user_id uuid, p_can_edit_erp_reference boolean, p_can_edit_record boolean, p_can_delete boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.upsert_receiving_records_permission(p_requesting_user_id uuid, p_target_user_id uuid, p_can_edit_erp_reference boolean, p_can_edit_record boolean, p_can_delete boolean) IS 'Master-Admin-only write path for receiving_records_permissions, bypassing the anon role''s read-only table grant via SECURITY DEFINER. Used by ReceivingRecordsPermissionsModal instead of a direct table upsert.';


