--
-- Name: verify_complete_box_edit_otp(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_complete_box_edit_otp(p_box_operation_id uuid, p_requested_by uuid, p_otp text, p_before_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_row RECORD;
    v_matched RECORD;
    v_history_id uuid;
BEGIN
    IF p_otp IS NULL OR length(p_otp) <> 6 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid OTP format');
    END IF;

    FOR v_row IN
        SELECT * FROM public.complete_box_edit_otp_requests
        WHERE box_operation_id = p_box_operation_id AND is_used = false AND expires_at > now()
    LOOP
        IF v_row.otp_hash = extensions.crypt(p_otp, v_row.otp_hash) THEN
            v_matched := v_row;
            EXIT;
        END IF;
    END LOOP;

    IF v_matched IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Incorrect or expired verification code');
    END IF;

    -- The matched code, and every other still-pending code for this box, are
    -- consumed together — one approval is enough, and it closes the window
    -- for a second, unrelated code to be used later.
    UPDATE public.complete_box_edit_otp_requests
    SET is_used = true, used_at = now()
    WHERE box_operation_id = p_box_operation_id AND is_used = false;

    INSERT INTO public.complete_box_edit_history (box_operation_id, requested_by, approved_by, before_data, status)
    VALUES (p_box_operation_id, p_requested_by, v_matched.approver_user_id, p_before_data, 'pending')
    RETURNING id INTO v_history_id;

    RETURN jsonb_build_object('success', true, 'history_id', v_history_id, 'approved_by', v_matched.approver_user_id);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: verify_email_otp(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_email_otp(p_user_id uuid, p_otp text, p_purpose text DEFAULT 'login'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_record record;
BEGIN
    IF p_otp IS NULL OR length(p_otp) != 6 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid OTP format');
    END IF;

    SELECT id, otp_hash, expires_at INTO v_record
    FROM public.email_otp_requests
    WHERE user_id = p_user_id AND purpose = p_purpose AND is_used = false AND expires_at > now()
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_record IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'No valid OTP found. It may have expired — please request a new one.');
    END IF;

    IF v_record.otp_hash = extensions.crypt(p_otp, v_record.otp_hash) THEN
        UPDATE public.email_otp_requests SET is_used = true, used_at = now() WHERE id = v_record.id;
        RETURN jsonb_build_object('success', true);
    ELSE
        RETURN jsonb_build_object('success', false, 'error', 'Incorrect verification code');
    END IF;
END;
$$;


--
-- Name: verify_otp_and_change_access_code(character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_otp_and_change_access_code(p_email character varying, p_whatsapp character varying, p_otp character varying, p_new_code character varying) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
  v_otp_record RECORD;
  v_whatsapp_clean VARCHAR(20);
  v_hashed_code VARCHAR(255);
  v_existing_count INT;
BEGIN
  v_whatsapp_clean := REGEXP_REPLACE(p_whatsapp, '[\s\-]', '', 'g');

  -- Find matching user (correct JOIN: e.user_id = u.id)
  SELECT u.id INTO v_user_id
  FROM users u
  JOIN hr_employee_master e ON e.user_id = u.id
  WHERE LOWER(TRIM(e.email)) = LOWER(TRIM(p_email))
    AND REGEXP_REPLACE(e.whatsapp_number, '[\s\-]', '', 'g') = v_whatsapp_clean
    AND u.status = 'active'
  LIMIT 1;

  IF v_user_id IS NULL THEN
    RETURN json_build_object('success', false, 'message', 'User not found.');
  END IF;

  -- Find valid OTP
  SELECT id, otp_code, attempts INTO v_otp_record
  FROM access_code_otp
  WHERE user_id = v_user_id
    AND verified = false
    AND expires_at > NOW()
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_otp_record IS NULL THEN
    RETURN json_build_object('success', false, 'message', 'No valid OTP found. Please request a new one.');
  END IF;

  -- Check attempts
  IF v_otp_record.attempts >= 5 THEN
    UPDATE access_code_otp SET verified = true WHERE id = v_otp_record.id;
    RETURN json_build_object('success', false, 'message', 'Too many failed attempts. Please request a new OTP.');
  END IF;

  -- Verify OTP
  IF v_otp_record.otp_code != p_otp THEN
    UPDATE access_code_otp SET attempts = attempts + 1 WHERE id = v_otp_record.id;
    RETURN json_build_object('success', false, 'message', 'Invalid OTP code.');
  END IF;

  -- Check new code is not already used by another user
  SELECT COUNT(*) INTO v_existing_count
  FROM users
  WHERE id != v_user_id
    AND quick_access_code IS NOT NULL
    AND quick_access_code != ''
    AND extensions.crypt(p_new_code, quick_access_code) = quick_access_code;

  IF v_existing_count > 0 THEN
    RETURN json_build_object('success', false, 'message', 'This access code is already in use. Please choose a different one.');
  END IF;

  -- Hash the new code and update
  v_hashed_code := extensions.crypt(p_new_code, extensions.gen_salt('bf'));

  UPDATE users
  SET quick_access_code = v_hashed_code,
      updated_at = NOW()
  WHERE id = v_user_id;

  -- Mark OTP as verified
  UPDATE access_code_otp SET verified = true WHERE id = v_otp_record.id;

  RETURN json_build_object('success', true, 'message', 'Access code changed successfully.');
END;
$$;


--
-- Name: verify_password(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_password(password text, hash text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN hash = crypt(password, hash);
END;
$$;


--
-- Name: verify_password(character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_password(input_username character varying, input_password character varying) RETURNS TABLE(user_id uuid, username character varying, email character varying, role_type character varying, is_valid boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        u.id as user_id,
        u.username,
        u.email,
        -- Return derived role_type for backward compatibility
        CASE 
            WHEN u.is_master_admin = true THEN 'Master Admin'::character varying
            WHEN u.is_admin = true THEN 'Admin'::character varying
            ELSE 'User'::character varying
        END as role_type,
        (u.password_hash = crypt(input_password, u.password_hash)) as is_valid
    FROM users u
    WHERE u.username = input_username
      AND u.deleted_at IS NULL
    LIMIT 1;
END;
$$;


--
-- Name: verify_quick_access_code(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_quick_access_code(p_code character varying) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_user RECORD;
BEGIN
  -- Validate input format
  IF p_code IS NULL OR LENGTH(p_code) != 6 OR p_code !~ '^[0-9]{6}$' THEN
    RETURN json_build_object('success', false, 'error', 'Invalid access code format');
  END IF;

  -- Find user where crypt(input, stored_hash) = stored_hash
  SELECT id, username, user_type, status, is_master_admin, is_admin,
         employee_id, branch_id, position_id, avatar, quick_access_code, quick_access_salt,
         default_language
  INTO v_user
  FROM users
  WHERE status = 'active'
    AND extensions.crypt(p_code, quick_access_code) = quick_access_code;

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Invalid access code');
  END IF;

  RETURN json_build_object(
    'success', true,
    'user', json_build_object(
      'id', v_user.id,
      'username', v_user.username,
      'user_type', v_user.user_type,
      'status', v_user.status,
      'is_master_admin', v_user.is_master_admin,
      'is_admin', v_user.is_admin,
      'employee_id', v_user.employee_id,
      'branch_id', v_user.branch_id,
      'position_id', v_user.position_id,
      'avatar', v_user.avatar,
      'default_language', v_user.default_language
    )
  );
END;
$_$;


--
-- Name: verify_quick_task_completion(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_quick_task_completion(completion_id_param uuid, verified_by_user_id_param uuid, verification_notes_param text DEFAULT NULL::text, is_approved boolean DEFAULT true) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    new_status VARCHAR(50);
BEGIN
    IF is_approved THEN
        new_status := 'verified';
    ELSE
        new_status := 'rejected';
    END IF;
    
    UPDATE quick_task_completions 
    SET completion_status = new_status,
        verified_by_user_id = verified_by_user_id_param,
        verified_at = now(),
        verification_notes = verification_notes_param,
        updated_at = now()
    WHERE id = completion_id_param;
    
    RETURN FOUND;
END;
$$;


