CREATE TABLE public.aqura_change_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    requested_by_user_id uuid NOT NULL,
    branch_id bigint NOT NULL,
    requested_to_user_id uuid NOT NULL,
    denomination_counts jsonb NOT NULL,
    total_amount numeric(14,2) NOT NULL,
    status text DEFAULT 'Pending'::text NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    received_counts jsonb,
    received_total numeric(14,2),
    received_at timestamp with time zone,
    withdrawal_counts jsonb,
    withdrawal_total numeric(14,2),
    safe_box_printed_at timestamp with time zone,
    processed_at timestamp with time zone,
    cashier_confirmed_counts jsonb,
    cashier_confirmed_at timestamp with time zone,
    completed_at timestamp with time zone,
    safe_box_printer_name text,
    cashier_printer_name text,
    request_date date NOT NULL,
    daily_serial bigint NOT NULL,
    request_number text NOT NULL,
    CONSTRAINT aqura_change_requests_denomination_counts_check CHECK ((jsonb_typeof(denomination_counts) = 'object'::text)),
    CONSTRAINT aqura_change_requests_status_check CHECK ((status = ANY (ARRAY['Pending'::text, 'Cash Received'::text, 'Safe Box Printed'::text, 'Ready for Cashier Confirmation'::text, 'Cashier Confirmed'::text, 'Completed'::text]))),
    CONSTRAINT aqura_change_requests_total_amount_check CHECK ((total_amount > (0)::numeric))
);


--
-- Name: aqura_pos_print_actions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.aqura_pos_print_actions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    flow_id uuid NOT NULL,
    user_id uuid NOT NULL,
    branch_id bigint NOT NULL,
    action_type text NOT NULL,
    reason text,
    custom_reason text,
    printer_name text NOT NULL,
    print_status text NOT NULL,
    error_message text,
    printed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    request_id uuid,
    source text,
    pos_counter_id integer,
    pos_counter_name text,
    pos_counter_number text,
    CONSTRAINT aqura_pos_print_actions_action_type_check CHECK ((action_type = ANY (ARRAY['printer_selection'::text, 'test_print_attempt'::text, 'test_print_success'::text, 'test_print_failure'::text, 'opening_pos_counter'::text, 'closing_pos_counter'::text, 'recharge_card_operation'::text, 'other_reason'::text, 'final_print_attempt'::text, 'final_print_success'::text, 'final_print_failure'::text, 'safe_box_opening'::text, 'pos_counter_opening'::text]))),
    CONSTRAINT aqura_pos_print_actions_print_status_check CHECK ((print_status = ANY (ARRAY['selected'::text, 'attempted'::text, 'success'::text, 'failure'::text, 'reason_selected'::text]))),
    CONSTRAINT aqura_pos_print_actions_printed_at_check CHECK ((((print_status = 'success'::text) AND (printed_at IS NOT NULL)) OR ((print_status <> 'success'::text) AND (printed_at IS NULL))))
);


--
-- Name: TABLE aqura_pos_print_actions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.aqura_pos_print_actions IS 'Append-only audit events for POS Manager Cashier Counter printer selection, test jobs, reason selection and final jobs.';


