CREATE TABLE public.aqura_safe_box_operations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    branch_id bigint NOT NULL,
    operation_type text,
    denomination_counts jsonb,
    total_amount numeric(14,2),
    balance_before numeric(14,2),
    balance_after numeric(14,2),
    printer_name text NOT NULL,
    status text DEFAULT 'Opening'::text NOT NULL,
    opened_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    denomination_record_id uuid,
    main_counts_before jsonb,
    main_counts_after jsonb,
    safe_box_counts_before jsonb,
    safe_box_counts_after jsonb,
    opening_print_status text,
    opening_printed_at timestamp with time zone,
    CONSTRAINT aqura_safe_box_operations_denomination_counts_check CHECK (((denomination_counts IS NULL) OR (jsonb_typeof(denomination_counts) = 'object'::text))),
    CONSTRAINT aqura_safe_box_operations_operation_type_check CHECK (((operation_type IS NULL) OR (operation_type = 'Withdraw'::text))),
    CONSTRAINT aqura_safe_box_operations_status_check CHECK ((status = ANY (ARRAY['Opening'::text, 'Print Failed'::text, 'Open'::text, 'Completed'::text]))),
    CONSTRAINT aqura_safe_box_operations_total_amount_check CHECK (((total_amount IS NULL) OR (total_amount > (0)::numeric)))
);


