    sequence_no integer NOT NULL,
    duration_years integer DEFAULT 0 NOT NULL,
    duration_months integer DEFAULT 0 NOT NULL,
    effective_from date NOT NULL,
    effective_to date,
    is_infinite boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hr_employee_applicability_rule_periods_duration_check CHECK ((((is_infinite = true) AND (effective_to IS NULL)) OR ((is_infinite = false) AND (effective_to IS NOT NULL) AND (effective_to >= effective_from)))),
    CONSTRAINT hr_employee_applicability_rule_periods_type_check CHECK ((rule_type = ANY (ARRAY['ticket'::text, 'leave_salary'::text])))
);


