--
-- Name: hr_employee_master_with_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hr_employee_master_with_status AS
 SELECT m.id,
    m.user_id,
    m.current_branch_id,
    m.current_position_id,
    m.name_en,
    m.name_ar,
    m.employee_id_mapping,
    m.created_at,
    m.updated_at,
    m.nationality_id,
    m.id_expiry_date,
    m.id_document_url,
    m.health_card_expiry_date,
    m.health_card_document_url,
    m.driving_licence_expiry_date,
    m.driving_licence_document_url,
    m.id_number,
    m.health_card_number,
    m.driving_licence_number,
    m.bank_name,
    m.iban,
    m.contract_expiry_date,
    m.contract_document_url,
    m.sponsorship_status,
    m.insurance_expiry_date,
    m.insurance_company_id,
    m.health_educational_renewal_date,
    m.date_of_birth,
    m.join_date,
    m.work_permit_expiry_date,
    m.probation_period_expiry_date,
    m.permitted_early_leave_hours,
    m.whatsapp_number,
    m.email,
    m.privacy_policy_accepted,
    m.erp_employee_id_mapping,
    s.employment_status,
    s.employment_status_effective_date,
    s.employment_status_reason
   FROM (public.hr_employee_master m
     LEFT JOIN public.hr_employee_current_status s ON ((s.employee_id = m.id)));


--
-- Name: VIEW hr_employee_master_with_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.hr_employee_master_with_status IS 'hr_employee_master plus its current employment_status/effective_date/reason from hr_employee_status_history, for read-only compatibility with old queries.';


