-- Name: view_offer; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.view_offer (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    offer_name character varying(255) NOT NULL,
    branch_id bigint NOT NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    file_url text NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    start_time time without time zone DEFAULT '00:00:00'::time without time zone,
    end_time time without time zone DEFAULT '23:59:00'::time without time zone,
    thumbnail_url text,
    view_button_count integer DEFAULT 0,
    page_visit_count integer DEFAULT 0,
    offer_name_en character varying(255),
    offer_name_ar character varying(255),
    status text DEFAULT 'published'::text NOT NULL,
    CONSTRAINT view_offer_status_check CHECK ((status = ANY (ARRAY['published'::text, 'unpublished'::text, 'expired'::text])))
);


--
-- Name: COLUMN view_offer.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.view_offer.status IS 'published (live/scheduled), unpublished (manually pulled) or expired (auto-flipped by expire_view_offers via pg_cron). Every pre-existing and manually-added row defaults to published, matching prior behaviour.';


